export type CategoryId =
  | "acrylic"
  | "acrylic-bending"
  | "standee"
  | "light"
  | "phone-gadget"
  | "mirror-magnet"
  | "sticker-paper"
  | "card-photo"
  | "banner"
  | "calendar-frame"
  | "home"
  | "bag"
  | "apparel"
  | "fabric"
  | "gifts";

export interface Category {
  id: CategoryId;
  name: string;
  nameEn: string;
  emoji: string;
  gradient: string;
  description: string;
}

/**
 * 1 ขั้นของตาราง "+฿ ตามจำนวนที่สั่ง" ของตัวเลือกหนึ่ง (ดู ProductOptionChoice.extraTiers)
 * upTo = สั่งไม่เกินกี่ชิ้นถึงใช้ราคานี้ · ไม่ใส่/null = ขั้นสุดท้าย (ตั้งแต่นั้นขึ้นไป)
 */
export interface ExtraTier {
  upTo?: number | null;
  extra: number;
}

export interface ProductOptionChoice {
  name: string;
  extra?: number;
  /**
   * ให้ลูกค้าระบุ "จำนวน" ของตัวเลือกนี้ (ใช้ได้เฉพาะกลุ่ม multi)
   * เช่น เพิ่มสาย 2 เส้น → +฿ ของตัวนี้คูณ 2 · ค่าที่เก็บเขียนเป็น "เพิ่มสาย ×2"
   * ไม่เปิด = ติ๊กแล้วนับเป็น 1 เสมอ · ตั้งแยกทีละตัวได้ (บางตัวระบุจำนวนได้ บางตัวติ๊กเฉย ๆ)
   */
  qty?: boolean;
  /** จำนวนสูงสุดของตัวเลือกนี้ (ไม่ตั้ง = 99) */
  qtyMax?: number;
  /**
   * หน่วยของ "จำนวน" ที่ลูกค้าระบุ เช่น "ซม." — ตัวเลือกที่คิดเป็นขนาด (เซนละ +฿8) จะได้เห็นชัดว่ากรอกกี่เซนติเมตร
   * มีผลกับหน้าสินค้าอย่างเดียว (ป้ายข้างช่องจำนวน/ยอดรวมของตัวเลือก) — ราคายังคิด +฿ × จำนวน เหมือนเดิม
   * ไม่ตั้ง = นับเป็น "จำนวนอัน" เฉย ๆ เหมือนก่อน
   */
  qtyUnit?: string;
  /**
   * เลือกตัวนี้แล้ว 1 หน่วยที่สั่งได้ของกี่ชิ้น
   * เช่น สติกเกอร์ขนาด 3cm ได้ 45 ชิ้นต่อแผ่น A3 · ขนาด 20cm ได้ 1 ชิ้น
   * ใช้เป็นเพดานจำนวนลายที่คละได้ — คละ 1 ลายต้องใช้อย่างน้อย 1 ชิ้น
   * จึงคละได้ไม่เกิน (ชิ้นต่อหน่วย × จำนวนหน่วยที่สั่ง)
   */
  perUnit?: number;
  /**
   * 🖼 ภาพประกอบของตัวเลือกนี้ (URL) — สินค้าที่มีหลายแบบให้ลูกค้าเห็นหน้าตาแต่ละแบบ
   * แสดงเป็นภาพย่อบนปุ่มตัวเลือก และกดเลือกแล้วแกลเลอรีสลับไปภาพนี้ (ถ้าอยู่ในแกลเลอรี)
   */
  imageSrc?: string;
  /**
   * 🎬 คลิปประกอบของตัวเลือกนี้ (URL .mp4) — การ์ดกลุ่ม display "cards" เล่นคลิปวนแทนภาพนิ่ง
   * และกดเลือกแล้วแกลเลอรีสลับไปช่องคลิปนี้ (imageSrc ยังต้องมี ใช้เป็นโปสเตอร์/ภาพสำรอง)
   */
  videoSrc?: string;
  /**
   * 📝 คำอธิบายสั้น ๆ ใต้ชื่อตัวเลือก — โชว์เฉพาะกลุ่มที่ตั้ง display "cards"
   * (การ์ดแบบเดียวกับแผงเลือกเรทราคา: รูป + ชื่อ + คำอธิบาย) เช่น อธิบายความต่าง
   * ไดคัท 50% กับ 100% ให้ลูกค้าเข้าใจตั้งแต่ตอนเลือก · กลุ่ม pills/dropdown ไม่โชว์ค่านี้
   */
  desc?: string;
  /**
   * 💬 ข้อความกำกับที่โชว์ "เฉพาะตอนตัวเลือกนี้ถูกเลือกอยู่" — ขึ้นในการ์ดของตัวเลือกนั้น
   * เช่น ไดคัทเข้าเนื้อ: "**กรณีไดคัทเข้าเนื้อ** จะมีฝุ่นของสีหมึกติดที่งาน สามารถเช็ดออกได้"
   * ต่างจาก desc ที่โชว์ตลอด — ใช้เตือนเงื่อนไขเฉพาะของตัวที่เลือก · รองรับ **คำเน้น** แบบ note ของกลุ่ม
   * โชว์เฉพาะกลุ่ม display "cards" (แบบเดียวกับ desc)
   */
  selectedNote?: string;
  /**
   * ผูกกับ SKU ในคลังวัสดุ — ลูกค้าเลือกค่านี้แล้วออเดอร์ชำระเงิน ระบบตัดสต๊อกตัวนี้ให้อัตโนมัติ
   * ใส่ที่ "ตัวเลือก" ไม่ใช่ที่สินค้า เพราะสินค้าหนึ่งตัวใช้วัสดุต่างกันตามที่ลูกค้าเลือก
   * (ตั้งค่าที่ preset ครั้งเดียว = ทุกสินค้าที่ลิงก์คลังนั้นได้ตามไปด้วย)
   */
  stockItemId?: string;
  /** ใช้กี่หน่วยต่อสินค้า 1 ชิ้น (ไม่ตั้ง = 1) */
  stockQtyPer?: number;
  /**
   * 💬 เลือกตัวนี้แล้ว = งานสั่งทำ ราคาต้องให้แอดมินตีให้ (ไม่ใช้ตารางราคาปกติ)
   * เช่น "แบบที่ 3 (กำหนดขนาดเอง)" ในกลุ่มแบบ — ลูกค้ากรอกขนาดเองแล้วรอแอดมินตีราคา
   * ลูกค้ายัง "กดสั่งไว้ก่อน" ได้ตามปกติ ราคาขึ้นเป็น 0 จนกว่าแอดมินจะใส่ให้
   */
  askPrice?: boolean;
  /**
   * ⭐ แบบที่ลูกค้านิยมสั่ง — หน้าสินค้าโชว์ป้าย "นิยม" ท้ายชื่อ
   * เป็นป้ายบอกทางเฉย ๆ ไม่มีผลกับราคา ตารางราคา หรือการคิดเงินใด ๆ
   */
  popular?: boolean;
  /**
   * 🏷️ ป้ายสั้น ๆ ท้ายชื่อตัวเลือก เช่น "ฟรี!" · "แนะนำ" — บอกทางเฉย ๆ ไม่มีผลกับราคา
   * (ต่างจาก popular ตรงที่พิมพ์ข้อความเองได้ · ใส่ทั้งคู่ก็ได้ ป้ายจะขึ้นเรียงกัน)
   */
  badge?: string;
  /**
   * 📄 เลือกตัวนี้แล้ว วัสดุ 1 แผ่นทำได้กี่ชิ้น — เช่น สมุด A5 ได้ 4 เล่มต่อฟิล์ม A3 แผ่นหนึ่ง
   * ใช้คู่กับกลุ่มที่ตั้ง ProductOption.sheetFee (ค่าธรรมเนียมที่คิดต่อแผ่น ไม่ใช่ต่อชิ้น)
   * ไม่ตั้ง = 1 ชิ้นต่อแผ่น
   */
  perSheet?: number;
  /**
   * 📄 เลือกตัวนี้แล้ว งาน 1 ชิ้น "กิน" วัสดุกี่แผ่น — เช่น ปฏิทิน 8 แผ่น ใช้กระดาษ 4 แผ่น A3 ต่อเล่ม
   * ด้านกลับของ perSheet (ที่เป็นหลายชิ้นต่อ 1 แผ่น) · ใช้คู่กับกลุ่มที่ตั้ง ProductOption.sheetFee เหมือนกัน
   * ไม่ตั้ง = 1 แผ่นต่อชิ้น · ใส่พร้อม perSheet ได้ (จำนวนแผ่น = ⌈จำนวน × แผ่นต่อชิ้น ÷ ชิ้นต่อแผ่น⌉)
   *
   * ใส่เป็น **ตาราง** ได้เมื่อจำนวนแผ่นขึ้นกับอีกกลุ่มด้วย — คีย์ = ชื่อตัวเลือกในกลุ่ม sheetFee.by
   * เช่น ปฏิทินไดคัท ขนาด 6x6-8x8 นิ้ว: { "8 แผ่น (16หน้า)": 4, "14 แผ่น (28หน้า)": 7 }
   * (จำนวนแผ่นของขนาดหนึ่ง ๆ ไม่ใช่ตัวคูณคงที่ของจำนวนแผ่นในเล่ม จึงต้องกางเป็นตาราง)
   */
  sheetsPerUnit?: number | Record<string, number>;
  /**
   * 📐 เลือกขนาดตัดนี้แล้ว 1 หน่วยที่สั่งได้งานกี่ชิ้น — งาน "แบ่งแผ่น" เช่น ขนาดตัด A5 = 4 ชิ้น / แผ่น A3
   * ใช้สรุปให้ลูกค้าว่าสั่งกี่หน่วยแล้วได้งานกี่ชิ้น (ดู unitYieldOf) — ตัวเลขบอกทางเฉย ๆ
   * ไม่มีผลกับราคา/โควตาคละลาย/ตะกร้า (คนละตัวกับ perUnit ที่เป็นเพดานจำนวนลาย)
   * หน่วยที่อ้างถึงคือหน่วยขายของเรทนั้น — กลุ่มขนาดตัดที่ผูกเรทคนละหน่วย (แผ่น A3 / ตร.ม.) ต้องแยกกลุ่ม
   */
  piecesPerUnit?: number;
  /**
   * 💰 +฿ ของ "ช่วงสั่งน้อย" — ใช้เมื่อจำนวนยังไม่ถึง extraFromQty ของกลุ่ม
   * มีไว้สำหรับกลุ่มที่ช่วงปลีกกับช่วงส่งคิดคนละเรท เช่น สแตนดี้: ช่วงปลีกฐาน 7 ซม.ขึ้นไป
   * คิด ซม.ละ 5 บาท ส่วนช่วงส่ง (11 ชิ้นขึ้นไป) คิดตามตาราง extra ปกติ
   * ไม่ตั้ง = ช่วงที่ต่ำกว่าเกณฑ์ไม่คิดเพิ่ม (พฤติกรรมเดิม) · ไม่มีผลกับกลุ่ม extraPerDesign
   */
  extraBelow?: number;
  /**
   * 💰 +฿ ของ "ช่วงสั่งน้อยสุด" (ขั้นที่ 3) — ใช้เมื่อจำนวนไม่เกิน extraSmallUpToQty ของกลุ่ม
   * ปกติ +฿ ของตัวเลือกมี 2 ขั้น (extraBelow / extra ตัดที่ extraFromQty) — ตัวนี้เติมขั้นล่างสุดให้
   * เช่น ติ่งห้อยพวงกุญแจ: 1-10 ชิ้น 20 · 11-29 ชิ้น 15 · 30 ชิ้นขึ้นไป 12 (ราคาต่างกันทุกขนาดติ่งห้อย
   * จึงใช้ค่าเหมา smallQtyFee ที่เป็นเลขเดียวทั้งกลุ่มแทนไม่ได้)
   * ไม่ตั้ง (หรือกลุ่มไม่ได้ตั้ง extraSmallUpToQty) = คิดตามกติกา 2 ขั้นเดิมทุกอย่าง
   */
  extraSmall?: number;
  /**
   * 💰 ตาราง "+฿ ตามจำนวนที่สั่ง" ของตัวเลือกนี้ — สั่งเยอะ ค่าตัวเลือกถูกลงเป็นขั้น ๆ
   * เช่น FLEX ผ้าเชียร์ ขนาดไม่เกิน 15x55cm: 1-10 ผืน ฿250 · 11-29 ฿245 · 30-99 ฿240 ·
   * 100-499 ฿235 · 500 ผืนขึ้นไป ฿230 (ราคาต่างกันทุกขนาด จึงใช้ขั้นราคา 2-3 ขั้นของกลุ่มแทนไม่ได้)
   * มีตาราง = ใช้แทน extra / extraBelow / extraSmall / extraFromQty ทั้งหมด (ตารางเดียวครอบทุกช่วงอยู่แล้ว)
   * ⚠️ ยังต้องใส่ extra ไว้เป็นราคาขั้นแรกด้วย — ที่ที่ยังไม่รู้จำนวน (ช่วงราคาสินค้า/หน้ารายการ) อ่านค่านั้น
   * ไม่ตั้ง = คิด extra ตายตัวเหมือนเดิม
   */
  extraTiers?: ExtraTier[];
  /**
   * 📏 ค่าบริการตามขนาดชิ้นงานที่ลูกค้ากรอก — ขั้นราคาตาม "ด้านที่ยาวที่สุด" ของคู่ช่องกรอก
   * กว้าง/ยาว และคูณจำนวนชิ้นต่อ 1 หน่วยขายจากการจัดวางได้ (งานผ้า: ตัดแบ่ง/เย็บขอบ/โพ้งขอบ)
   * คิดรวมกับ extra ปกติใน choiceExtraOf จึงติดไปทุกที่เอง (ราคาหน้าเว็บ · ป้าย +฿ · ตะกร้า · ใบเสนอราคา)
   */
  sizeFee?: SizeFee;
  /**
   * 🎨 กติกาคละลายเฉพาะตอนเลือกตัวนี้ — ทับ mixRule ระดับสินค้า (ดู mixRuleFor)
   * ใช้กับกลุ่มที่ค่าคละไม่เท่ากันตามแบบงาน เช่น สติ๊กเกอร์ "แบบไดคัท":
   * ไดคัท 50% ค่าคละลายละ 20 บาท · ไดคัท 100% ใช้กติกากลางของสินค้าตามเดิม
   */
  mixRule?: MixRule;
}

export interface ProductOption {
  label: string;
  choices: ProductOptionChoice[];
  /**
   * กลุ่มนี้เป็น "วัสดุ" ที่กินสต๊อก — ไม่ใช่กระบวนการอย่าง "สกรีนกี่ด้าน" ที่ไม่มีของหายจากชั้น
   * ใช้กรองในหน้าแอดมินว่ากลุ่มไหนควรผูก SKU · ไม่ตั้ง = ยังไม่ได้จัดประเภท
   */
  stockBearing?: boolean;
  /**
   * ถ้ามี = กลุ่มนี้ "ลิงก์" กับคลังตัวเลือกกลาง (option preset) ตาม id นี้
   * ตอนอ่านข้อมูลจริง label+choices จะถูกแทนที่ด้วยของในคลัง (ดู resolveOptions)
   * choices ที่เก็บไว้เป็นสำเนาสำรอง (snapshot) เผื่อคลังถูกลบ · ไม่มี = กลุ่มอิสระ (พิมพ์เอง)
   */
  presetId?: string;
  /**
   * รูปแบบแสดงบนหน้าร้าน:
   * - ไม่ระบุ/'pills' = ปุ่มแยก (ค่าเริ่มต้น) — เลือกได้ 1 อย่าง
   * - 'dropdown' = เมนูเลือก (เหมาะกับตัวเลือกเยอะ) — เลือกได้ 1 อย่าง
   * - 'multi' = ติ๊กเลือกได้หลายอย่าง (เช่น อุปกรณ์เสริม/ลูกเล่นที่สั่งพร้อมกันได้) — เลือก 0 ถึงหลายอย่าง
   *   ค่าที่เลือกเก็บรวมเป็นข้อความเดียวคั่นด้วย MULTI_SEP · +฿ คิดรวมทุกตัวที่ติ๊ก
   * - 'input' = ช่องให้ลูกค้า "กรอกค่าเอง" (ไม่มีรายการให้เลือก) เช่น ขนาดงานสั่งทำ
   *   ตั้งรายละเอียดช่องที่ ProductOption.input · ค่าที่กรอกเก็บลง selections[label] เหมือนกลุ่มอื่น
   *   ไม่มีราคาในตัว (ไม่คิด +฿ ไม่เป็นแกนตารางราคา) — ใช้คู่กับ askPrice ให้แอดมินตีราคา
   * - 'cards' = การ์ดแนวตั้งแบบเดียวกับแผงเลือกเรทราคา (รูปใหญ่ + ชื่อ + คำอธิบาย desc)
   *   เหมาะกับกลุ่ม "แบบ/ชนิด/เนื้อ" ที่หน้าตาต่างกันชัด ๆ และมีภาพประกอบ — เลือกได้ 1 อย่าง
   */
  display?: "pills" | "dropdown" | "multi" | "input" | "cards";
  /**
   * 🔽 กลุ่ม "ของเสริมที่ปิดไว้ก่อน" — หน้าสินค้าโชว์แค่หัวข้อ + สวิตช์เปิด/ปิด ยังไม่กางตัวเลือก
   * เปิดสวิตช์ถึงจะเห็นรายการให้เลือก · ปิดกลับ = เด้งกลับไปตัวเลือกแรก (ตัวที่ไม่คิดเงิน)
   * ใช้กับกลุ่มที่ลูกค้าส่วนใหญ่ไม่ได้ใช้ เช่น เคลือบด้านหลัง / เคลือบฟอยล์ — หน้าจะได้ไม่ยาวรก
   * ⚠️ ตัวเลือกแรกของกลุ่มต้องเป็นตัว "ไม่เอา" (0 บาท) เสมอ เพราะตอนปิดระบบจะใช้ตัวนั้น
   * กลุ่มติ๊กหลายอย่าง (display 'multi') ใช้ได้เหมือนกัน — ปิดสวิตช์ = ล้างที่ติ๊กทั้งหมด
   */
  collapsible?: boolean;
  /**
   * (ของเก่า) เคยเปิด "ระบุจำนวน" ทั้งกลุ่ม — ตอนนี้ตั้งรายตัวที่ ProductOptionChoice.qty แทน
   * ยังอ่านค่าเดิมอยู่เพื่อไม่ให้สินค้าที่ตั้งไว้ก่อนหน้าราคาเพี้ยน · หน้าแก้ไขสินค้าจะย้ายให้เองตอนเปิดครั้งถัดไป
   */
  qtyPerChoice?: boolean;
  /** (ของเก่า) จำนวนสูงสุดระดับกลุ่ม — ใช้เป็นค่าตั้งต้นให้ตัวเลือกที่ไม่ได้ตั้งเอง */
  qtyMax?: number;
  /**
   * "แสดงเมื่อ" — โชว์กลุ่มนี้เฉพาะตอนกลุ่มอื่นเลือกค่าที่กำหนด · ไม่ตรง = ซ่อนทั้งกลุ่ม
   * (ไม่ถามลูกค้า ไม่คิดเงิน ไม่ติดไปกับตะกร้า/ออเดอร์)
   * เช่น กลุ่ม "สีตะขอ C" แสดงเมื่อ ตะขอ = C เท่านั้น — ต่างจากกฎเงื่อนไขที่กรองได้แค่ "ตัวเลือกในกลุ่ม"
   * ไม่ตั้ง = แสดงตลอด
   */
  showWhen?: { label: string; choices: string[] };
  /**
   * เงื่อนไข "และ" ข้อที่สอง — ต้องตรงพร้อมกันกับ showWhen ถึงจะแสดงกลุ่มนี้
   * เช่น "FLEX ลงด้านไหน" แสดงเมื่อ เรทราคา = สกรีน 2 ด้าน และ FLEX = เลือกไว้แล้ว
   * (งานสกรีนด้านเดียวไม่ต้องถาม เพราะมีด้านเดียวอยู่แล้ว)
   */
  showWhenAlso?: { label: string; choices: string[] };
  /**
   * เงื่อนไข "และ" เพิ่มเติม (ข้อที่ 3 เป็นต้นไป) — ทุกข้อต้องตรงพร้อมกันกับ showWhen/showWhenAlso
   * ใช้กับกลุ่มที่ต้องเช็คตัวแปรมากกว่า 2 ตัว เช่น สติ๊กเกอร์ UV: ช่องกรอกขนาดไดคัทเอง
   * ต้องตรงทั้ง โหมดตัด (50%) + เรทราคา (A3/ตร.ม.) + ขนาดตัด (กำหนดเอง) พร้อมกัน
   * ไม่ตั้ง/ว่าง = ไม่มีเงื่อนไขเพิ่ม (พฤติกรรมเดิม)
   */
  showWhenAll?: { label: string; choices: string[] }[];
  /**
   * เงื่อนไข "หรือ" — แสดงกลุ่มนี้เมื่อข้อใดข้อหนึ่งตรง (ต่างจาก showWhen/showWhenAll ที่ต้องตรงทุกข้อ)
   * ใช้กับกลุ่มที่มีทางเปิดหลายทาง เช่น "รูปแบบการห้อย" ของพวงกุญแจหลายชิ้น:
   * โชว์เมื่อพวงมี 2 ชิ้นขึ้นไป "หรือ" ติ๊กติ่งห้อยไว้ (ชิ้นเดียว+ติ่งห้อยก็มีอะไรให้จัดเรียงแล้ว)
   * ตั้งคู่กับเงื่อนไข "และ" ได้ — ต้องผ่านทั้งฝั่ง และ/หรือ ถึงจะแสดง · ไม่ตั้ง/ว่าง = ไม่มีเงื่อนไขฝั่งนี้
   */
  showWhenAny?: { label: string; choices: string[] }[];
  /**
   * 🧩 "ชุดตัวเลือก" — กลุ่มที่ตั้งชื่อชุดเดียวกันและอยู่ติดกัน จะถูกจับใส่กรอบเดียวกันบนหน้าสินค้า
   * พร้อมหัวชุด (เช่น "ชิ้นที่ 2") กันสายตาหลงเวลาสินค้ามีกลุ่มเยอะ ๆ ที่หน้าตาซ้ำกันทุกชิ้น
   * ชื่อกลุ่มที่ลงท้ายด้วยชื่อชุด จะตัดส่วนท้ายออกตอนแสดงในกรอบ ("ขนาดชิ้นที่ 2" → "ขนาด")
   * — ชื่อเต็มยังใช้ในตะกร้า/ออเดอร์/ใบงานเหมือนเดิม · ไม่ตั้ง = เรียงเรียบ ๆ แบบเดิม
   */
  section?: string;
  /**
   * 🎯 ค่าเริ่มต้นของกลุ่มนี้ผูกกับค่าของกลุ่มอื่น — ลูกค้าเปลี่ยนค่ากลุ่มคุมเมื่อไหร่
   * กลุ่มนี้รีเซ็ตเป็นค่าเริ่มต้นของค่านั้น (ที่เลือกไว้ก่อนหน้าไม่เกี่ยว เริ่มใหม่ตามกลุ่มคุม)
   * เช่น อะคริลิคประกบ: "รับตะขอไหม" ตั้ง { label: "เรทราคา", map: { "สแตนดี้…": "ไม่รับตะขอ" } }
   * — เลือกเรทสแตนดี้แล้วเริ่มที่ "ไม่รับตะขอ" (ลูกค้ายังกดเปลี่ยนกลับได้)
   * ค่าของกลุ่มคุมที่ไม่อยู่ใน map = ไม่แตะกลุ่มนี้ · อ้าง "เรทราคา" (RATE_LABEL) ได้
   */
  defaultBy?: { label: string; map: Record<string, string> };
  /**
   * ราคาบวกเพิ่ม (+฿) ของกลุ่มนี้ มีผลเมื่อสั่งตั้งแต่กี่ชิ้นขึ้นไป
   * เช่น อะไหล่เข็มกลัด ตั้ง 11 = ช่วงปลีก 1-10 ชิ้น ราคารวมอะไหล่แล้ว (ไม่บวกเพิ่ม)
   * สั่ง 11 ชิ้นขึ้นไปค่อยคิดเพิ่มต่อชิ้นตามตัวเลือก · ไม่ตั้ง = บวกเพิ่มทุกจำนวน
   */
  extraFromQty?: number;
  /**
   * ขั้นราคาที่ 3 ของกลุ่มนี้ — สั่งไม่เกินกี่ชิ้นถึงใช้ ProductOptionChoice.extraSmall
   * (เหนือช่วงนี้กลับไปใช้กติกา 2 ขั้นเดิม extraBelow / extra ตัดที่ extraFromQty)
   * ต่างจาก smallQtyFee ตรงที่ราคาช่วงนี้ตั้งแยกได้ "ทุกตัวเลือก" ไม่ใช่เลขเหมาเลขเดียวทั้งกลุ่ม
   * — ใช้กับกลุ่มที่แต่ละแถวราคาไม่เท่ากัน (เช่น ติ่งห้อยแยกตามขนาด)
   * ไม่ตั้ง = ไม่มีขั้นที่ 3 (พฤติกรรมเดิมของทุกสินค้า)
   */
  extraSmallUpToQty?: number;
  /**
   * 🔢 +฿ ของกลุ่มนี้คูณด้วย "จำนวนที่ระบุไว้ในกลุ่มอื่น" — ใส่ชื่อกลุ่มต้นทาง
   * ใช้กับกลุ่มลูกที่ราคาผูกกับของชิ้นเดียวกัน เช่น Acrylic Kit: กลุ่ม "ตะขอ" ให้ระบุจำนวนได้
   * (ติ๊ก F แล้วใส่ 3 ชิ้น) กลุ่ม "สีตะขอ · โลหะ" ที่โชว์ตามตะขอ F ต้องคิดสีคูณ 3 ตามไปด้วย
   * นับเฉพาะตัวเลือกที่กลุ่มนี้ผูกไว้ใน showWhen ของกลุ่มต้นทางเดียวกัน (สีของตะขอ F ไม่นับจำนวนตะขอ C)
   * ไม่ตั้ง = คูณ 1 เหมือนเดิม
   */
  qtyFrom?: string;
  /**
   * 💰 ราคาตัวเลือกกลุ่มนี้ "ดึงจากตารางเรท" เหมือนเป็นแกนตารางชื่อนี้ — ใส่ชื่อกลุ่มแกน (driver)
   * ใช้กับสินค้า "หลายชิ้นใน 1 หน่วย" เช่น พวงกุญแจหลายชิ้นใน 1 พวง:
   * กลุ่ม "ขนาดชิ้นที่ 2..10" ตั้ง priceAsDriver: "ขนาดชิ้นที่ 1" → เลือก 5cm = บวกราคาช่อง 5cm
   * ของตารางเรท ณ ช่วงจำนวนปัจจุบัน (ความหนา/งานสกรีน/ประเภทตามที่เลือกอยู่)
   * ราคาจึงขยับตามเรทเองอัตโนมัติ ไม่ต้องกรอก +฿ ตายตัว · ไม่ตั้ง = คิด extra ปกติ
   */
  priceAsDriver?: string;
  /**
   * แกนอื่นของช่องราคา (นอกจาก priceAsDriver) ให้ดึงค่าจาก "กลุ่มอื่น" แทนกลุ่ม global
   * รูปแบบ { ชื่อแกนตาราง: ชื่อกลุ่มที่เอาค่ามาใช้ } — ใช้กับสินค้าหลายชิ้นที่แต่ละชิ้น
   * เลือกสเปคของตัวเอง เช่น "ขนาดชิ้นที่ 2" ตั้ง
   *   { "ประเภทอะคริลิค ชิ้นที่ 1": "ประเภทอะคริลิค ชิ้นที่ 2", "งานสกรีน ชิ้นที่ 1": "งานสกรีน ชิ้นที่ 2" }
   * → ราคาชิ้นที่ 2 = ช่องตารางของ (ขนาดชิ้นที่ 2 × ประเภทชิ้นที่ 2 × งานสกรีนชิ้นที่ 2)
   * กลุ่มต้นทางยังไม่มีค่า/แกนไม่มีจริง = ใช้ค่ากลุ่ม global ตามเดิม · ใช้คู่กับ priceAsDriver เท่านั้น
   */
  priceAsDriverAlso?: Record<string, string>;
  /**
   * ค่าธรรมเนียม "ช่วงสั่งน้อย" ของกลุ่มนี้ — คิดเพิ่มต่อชิ้นเมื่อสั่งไม่เกินจำนวนที่กำหนด
   * เช่น พวงกุญแจ 3mm ช่วงปลีก 1-10 ชิ้น เลือกตะขอบวกชิ้นละ 10 บาท (ยกเว้นห่วงแถมฟรี Z1/Z2)
   * คิด "เพิ่มจาก" ราคาของตัวเลือกนั้นตามปกติ · ตัวเลือกใน freeChoices ไม่คิด
   */
  /**
   * "ฟรีเมื่อ" — ตัวเลือกที่ระบุไม่คิด +฿ เมื่อกลุ่มอื่นเลือกค่าที่กำหนด
   * เช่น ห่วง Z1/Z2 ฟรีเมื่อความหนา = 3mm · ความหนาอื่นคิด +฿ ตามปกติ
   */
  freeWhen?: {
    /** ตัวเลือกในกลุ่มนี้ที่ได้ฟรี */
    choices: string[];
    /** เงื่อนไขจากกลุ่มอื่น */
    when: { label: string; choices: string[] };
  };
  smallQtyFee?: {
    /** บวกเพิ่มต่อชิ้น (บาท) — ใส่ค่าติดลบได้ = ลดให้ต่อชิ้นในช่วงนั้นแทน */
    fee: number;
    /** คิดเมื่อสั่งไม่เกินกี่ชิ้น (เช่น 10 = คิดเฉพาะ 1-10 ชิ้น) */
    upToQty: number;
    /** ตัวเลือกที่ยกเว้น ไม่คิดค่าธรรมเนียมนี้ (เช่น ห่วงที่แถมฟรี) */
    freeChoices?: string[];
    /** จำกัดเฉพาะเมื่อกลุ่มอื่นเลือกค่าเหล่านี้ (เช่น ความหนาอะคริลิค = 3mm) — ไม่ตั้ง = ทุกกรณี */
    when?: { label: string; choices: string[] };
  };
  /**
   * รายละเอียดช่องกรอก — มีผลเฉพาะกลุ่มที่ตั้ง display: 'input'
   * (กลุ่มชนิดนี้ไม่มี choices ให้เลือก ลูกค้าพิมพ์ค่าเอง)
   */
  input?: OptionInput;
  /**
   * 💰 คิดเงินตามตัวเลขที่ลูกค้ากรอกในกลุ่มนี้ — บาทต่อ 1 หน่วยที่กรอก (ดู InputFee)
   * เช่น ปฏิทินผ้าแคนวาส "เพิ่มขนาด (นิ้ว/ด้าน)" กรอก 2 → +30 บาท/ผืน เมื่อเรทนิ้วละ 15
   * มีผลเฉพาะกลุ่ม display 'input' ที่ input.kind = 'number'
   */
  inputFee?: InputFee;
  /**
   * ✍️ ช่องกรอกนี้เป็น "ข้อมูลประกอบของงานปกติ" ไม่ใช่งานสั่งทำ — โชว์เรียงกับกลุ่มตัวเลือกปกติ
   * (ไม่เข้ากล่อง 📐 ไม่ต้องติ๊ก "สั่งทำ" ก่อน และตรวจว่ากรอกครบก่อนสั่งเสมอ)
   * เช่น ขนาดไดคัทของงานกระดาษ — ราคายังคิดตามตารางเดิม แค่ต้องรู้ขนาดไว้ผลิต
   * ใช้คู่กับ showWhen ได้ (ถามเฉพาะเรท/ตัวเลือกที่ต้องใช้) · มีผลเฉพาะกลุ่ม display 'input'
   */
  standardInput?: boolean;
  /**
   * 📐 โชว์ "จำนวนชิ้นโดยประมาณต่อแผ่นวัสดุ" ใต้ช่องกรอกของกลุ่มนี้ (กลุ่มนี้ = ด้านสูง)
   * อ่านด้านกว้างจากช่องกรอกกลุ่ม pairLabel — กรอกครบสองช่องแล้วคำนวณจากการเรียงแนวตรง
   * เลือกแนวตั้ง/แนวนอนที่ได้เยอะกว่า · เป็นตัวเลขบอกทางเฉย ๆ ไม่มีผลกับราคา/ตะกร้า
   * (ยกเว้นกลุ่มนั้นตั้ง capDesigns ไว้ — ตัวเลขนั้นจะกลายเป็นเพดานจำนวนลายที่คละได้ด้วย)
   */
  sheetYield?: SheetYield;
  /**
   * 🎨 จำนวนชิ้นต่อ 1 หน่วยสั่งของกลุ่มนี้ = "เพดานจำนวนลายที่คละได้" ด้วย (ดู perUnitCapacity)
   * คละ 1 ลายใช้อย่างน้อย 1 ชิ้น — งานไดคัทจึงคละได้ไม่เกินชิ้นที่ตัดได้จริงต่อแผ่น
   * อ่านจากขนาดตายตัวที่เลือก (choice.piecesPerUnit) หรือขนาดที่กรอกเอง (sheetYield) ก็ได้
   * ไม่ตั้ง = ตัวเลขต่อแผ่นเป็นแค่ข้อมูลบอกทาง ไม่ไปยุ่งกับโควตาลาย (พฤติกรรมเดิมของทุกสินค้า)
   */
  capDesigns?: boolean;
  /**
   * กลุ่มนี้เป็นส่วนของ "งานสั่งทำ" — มีผลแค่ในหน้าแก้ไขหลังบ้าน (ไปแก้ที่แผง 📐 แทนแผง 🎛️)
   * หน้าร้านแสดง/คิดราคาเหมือนกลุ่มอื่นทุกอย่าง · กลุ่มช่องกรอก (display 'input') ถือเป็นงานสั่งทำเสมอ
   * โดยไม่ต้องตั้งธงนี้
   */
  madeToOrder?: boolean;
  /**
   * 💬 ใช้กลุ่มนี้แล้ว = งานสั่งทำ ราคาต้องให้แอดมินตีให้
   * (กลุ่มช่องกรอกมักตั้งคู่กันเสมอ เพราะขนาดที่ลูกค้ากรอกเองไม่มีในตารางราคา)
   * ตั้งรายตัวเลือกก็ได้ที่ ProductOptionChoice.askPrice — เข้าข้อไหนข้อหนึ่งก็ถือว่าต้องตีราคา
   */
  askPrice?: boolean;
  /**
   * 🎁 "กี่ตัวแรกรวมในราคา" ของกลุ่มติ๊กหลายอย่าง — ตัวที่เกินจากนี้ถึงคิด +฿
   * เช่น สีไหม 3 สีแรกรวมในราคาแล้ว สีที่ 4 เป็นต้นไปคิดสีละ 10
   * นับตามลำดับที่แสดงในกลุ่ม (ตัวที่ระบุจำนวนได้ นับตามจำนวนที่ระบุ) · ไม่ตั้ง/0 = คิดทุกตัวตามปกติ
   */
  freeFirstN?: number;
  /**
   * 🎨 แสดงกลุ่มติ๊กหลายอย่างเป็น "ตารางสวอตช์สี" — วงกลมสี + ชื่อสั้นใต้ภาพ เรียงตาราง
   * ใช้กับกลุ่มที่ตัวเลือกเยอะมากและ "สี" คือสาระหลัก (เช่น สีไหมปัก 80 เบอร์)
   * รูปประจำตัวเลือกใช้เป็นสวอตช์บนปุ่มเท่านั้น — ไม่เข้าแกลเลอรี ไม่สลับภาพใหญ่ (ชิปเล็ก ขยายแล้วเบลอ)
   */
  swatchGrid?: boolean;
  /**
   * ✍️ แสดงกลุ่ม "เลือกได้อย่างเดียว" เป็น "ตารางแถบตัวอย่าง" — รูปแถบยาว + รหัสใต้ภาพ เรียงตาราง
   * ใช้กับกลุ่มที่หน้าตาของตัวอย่างคือสาระหลักและตัวเลือกเยอะ (เช่น ฟอนต์ปัก 26 แบบ)
   * รูปประจำตัวเลือกคือ "ทั้งบรรทัดตัวอย่าง" — ในตารางโชว์ครึ่งซ้าย (ตัวโตพอเห็นทรง)
   * แล้วโชว์เต็มบรรทัดของแบบที่เลือกไว้ใต้ตาราง · คู่กับ chartSrc ให้กดดูชาร์ตเต็มได้
   * ทับค่า display บนหน้าร้าน (ตั้ง display เป็นเมนูเลื่อนไว้เป็นทรงสำรองได้) · ไม่เข้าแกลเลอรี
   */
  sampleGrid?: boolean;
  /**
   * 🔍 รูป "ตารางเต็ม" ของกลุ่มสวอตช์/แถบตัวอย่าง — ลูกค้ากดดูขยาย/เทียบทุกแบบในรูปเดียว
   * (ชิปบนปุ่มเป็นรูปเล็ก ขยายแล้วเบลอ — รูปนี้คือไฟล์ความละเอียดเต็มไว้เปิด lightbox)
   */
  chartSrc?: string;
  /**
   * 👀 รูปตัวอย่างประกอบ note ของกลุ่ม — มี note + รูปนี้ = ท้าย note มีปุ่มกดเปิดรูปดูเต็มจอทันที
   * (ไม่ต้องไล่หาในแท็บ) เช่น อินโฟกราฟิก "การนับจุด DICUT" ของกลุ่มขนาดตัดสติ๊กเกอร์
   */
  noteImageSrc?: string;
  /**
   * 📝 ข้อความกำกับใต้ชื่อกลุ่มบนหน้าสินค้า — สเปกที่ลูกค้าควรรู้ตอนกำลังเลือก
   * เช่น "ตัวภาพพิมพ์บนกระดาษอาร์ตการ์ด 260 แกรม" (ของที่ไม่มีให้เลือก แต่ต้องบอก)
   * เป็นข้อความอย่างเดียว ไม่มีผลกับราคา/ตะกร้า/ออเดอร์
   */
  note?: string;
  /**
   * 💰 +฿ ของกลุ่มนี้คิด "ต่อลาย" ไม่ใช่ต่อชิ้น — เช่น สีไหมเกิน 3 สี คิดสีละ 10 บาทต่อแบบ
   * (ค่าขึ้นบล็อค/ค่าสีเป็นงานครั้งเดียวต่อลาย ไม่ขึ้นกับจำนวนชิ้นที่ปัก)
   * เงินส่วนนี้ไปโผล่ใน designFeeFor (ค่าเพิ่มทั้งรายการ) แทนราคา/ชิ้น
   */
  extraPerDesign?: boolean;
  /**
   * 📄 +฿ ของกลุ่มนี้คิด "ต่อแผ่นวัสดุ" ไม่ใช่ต่อชิ้น — เช่น ค่าฟิล์มเคลือบพิเศษคิดต่อแผ่น A3
   * จำนวนแผ่น = ⌈จำนวนที่สั่ง × แผ่นต่อชิ้น ÷ ชิ้นต่อแผ่น⌉ — ทั้งสองค่ามาจากตัวเลือกที่เลือกในกลุ่ม from
   * (ชิ้นต่อแผ่น = perSheet · แผ่นต่อชิ้น = sheetsPerUnit · ไม่ตั้ง = 1 ทั้งคู่)
   * เช่น สมุด A5 (4 เล่ม/แผ่น) สั่ง 5 เล่ม = 2 แผ่น = ค่าฟิล์ม ×2
   * เช่น ปฏิทิน 8 แผ่น (4 A3/เล่ม) สั่ง 5 เล่ม = 20 แผ่น = ค่าฟิล์ม ×20
   * เงินส่วนนี้ไปโผล่ใน designFeeFor (ค่าเพิ่มทั้งรายการ) เหมือน extraPerDesign ไม่เข้าราคา/ชิ้น
   */
  sheetFee?: {
    /** กลุ่มที่บอกว่า 1 แผ่นได้กี่ชิ้น (อ่าน perSheet ของตัวเลือกที่เลือกในกลุ่มนั้น) */
    from: string;
    /**
     * กลุ่มที่ 2 ที่ร่วมกำหนดจำนวนแผ่น — ตั้งเมื่อ sheetsPerUnit ในกลุ่ม from เป็นตาราง
     * เช่น ปฏิทินไดคัท: from "ขนาดกระดาษ" × by "จำนวนแผ่น" → 1/1 · 2/3 · 4/7 แผ่น A3 ต่อเล่ม
     */
    by?: string;
    /** ชื่อ "แผ่น" ที่โชว์ให้ลูกค้า เช่น "แผ่น A3" (ไม่ตั้ง = "แผ่น") */
    unit?: string;
  };
}

/**
 * ช่องให้ลูกค้ากรอกค่าเอง (กลุ่มตัวเลือกชนิด 'input')
 * ใช้กับงานสั่งทำที่ขนาด/รายละเอียดมาจากลูกค้า เช่น สแตนดี้ที่ระบุความสูงตัวหน้า/ตัวหลัง/ฐานเอง
 * ค่าที่กรอกเก็บลง selections เป็นข้อความพร้อมหน่วย ("2.5 ซม.") — ตะกร้า/ใบงาน/ใบเสร็จอ่านได้ทันที
 */
export interface OptionInput {
  /** ชนิดค่าที่ให้กรอก — number = ตัวเลข (ตรวจช่วงได้) · text = ข้อความสั้น · textarea = ข้อความหลายบรรทัด */
  kind: "number" | "text" | "textarea";
  /** หน่วยต่อท้ายค่า เช่น "ซม." (มาจากคลังหน่วย) — เฉพาะ kind number */
  unit?: string;
  /** ค่าต่ำสุด/สูงสุดที่ยอมรับ (number) — กันลูกค้าพิมพ์ขนาดที่ทำไม่ได้ */
  min?: number;
  max?: number;
  /** รับเฉพาะจำนวนเต็ม (number) — เช่น ขนาดอาร์มปักไม่รับทศนิยม */
  integer?: boolean;
  /** ความยาวสูงสุด (text/textarea) — ไม่ตั้ง = 200 */
  maxLength?: number;
  /** ข้อความจาง ๆ ในช่อง เช่น "2.5" */
  placeholder?: string;
  /** คำอธิบายใต้ช่อง เช่น "วัดจากขอบล่างถึงปลายบนสุด" */
  hint?: string;
  /** ไม่กรอก = กดสั่งไม่ได้ (ไม่ตั้ง = ต้องกรอก) */
  required?: boolean;
}

/** กลุ่มนี้เป็น "ช่องกรอก" ไหม (ลูกค้าพิมพ์ค่าเอง ไม่ได้เลือกจากรายการ) */
export function isInputOption(opt: ProductOption): boolean {
  return opt.display === "input";
}

/** ความยาวข้อความสูงสุดของช่องกรอกแบบตัวอักษร */
export const INPUT_MAX_LEN = 200;

/**
 * เขียนค่าที่ลูกค้ากรอกให้เป็นข้อความที่เก็บลง selections — ต่อหน่วยให้ถ้ามี
 * ("2.5" + "ซม." → "2.5 ซม.") · ค่าว่าง = ยังไม่ได้กรอก คืนค่าว่าง
 */
export function formatInputValue(opt: ProductOption, raw: string): string {
  const v = raw.trim();
  if (!v) return "";
  const unit = opt.input?.unit?.trim();
  return unit ? `${v} ${unit}` : v;
}

/** อ่านค่าที่ลูกค้ากรอกกลับจาก selections (ตัดหน่วยที่ต่อท้ายออก) */
export function parseInputValue(opt: ProductOption, stored: string | undefined): string {
  const v = (stored ?? "").trim();
  if (!v) return "";
  const unit = opt.input?.unit?.trim();
  return unit && v.endsWith(unit) ? v.slice(0, -unit.length).trim() : v;
}

/**
 * ตรวจค่าที่กรอกในกลุ่มนี้ — คืนข้อความบอกปัญหา หรือ null ถ้าผ่าน
 * ใช้ทั้งตอนกดสั่ง (บล็อก) และตอนแสดงคำเตือนใต้ช่อง จะได้เกณฑ์เดียวกันเสมอ
 */
export function inputError(
  opt: ProductOption,
  stored: string | undefined,
  /** ตัวเลือกที่เลือกอยู่ — ส่งมาด้วยถ้าเพดานของช่องนี้ขึ้นกับตัวเลือกอื่น (ดู inputMaxOf) */
  selections?: Record<string, string>
): string | null {
  const cfg = opt.input;
  if (!cfg) return null;
  const raw = parseInputValue(opt, stored);
  const required = cfg.required !== false;
  // ชื่อกลุ่มมักมีวงเล็บ ("(ตัวหน้า) ขนาด") — ครอบอัญประกาศไว้ ประโยคจะได้ไม่อ่านติดกันจนงง
  const name = `“${opt.label}”`;
  if (!raw) return required ? `กรอก${name}ด้วยนะครับ` : null;
  if (cfg.kind === "number") {
    const n = Number(raw);
    if (!Number.isFinite(n) || n <= 0) return `${name} ต้องเป็นตัวเลข`;
    if (cfg.integer && !Number.isInteger(n)) return `${name} ต้องเป็นจำนวนเต็ม (ไม่รับทศนิยม)`;
    const u = cfg.unit ? ` ${cfg.unit}` : "";
    if (cfg.min != null && n < cfg.min) return `${name} ต้องไม่ต่ำกว่า ${cfg.min}${u}`;
    const max = inputMaxOf(opt, selections);
    if (max != null && n > max) return `${name} ต้องไม่เกิน ${max}${u}`;
    return null;
  }
  const max = cfg.maxLength ?? INPUT_MAX_LEN;
  if (raw.length > max) return `${name} ยาวเกิน ${max} ตัวอักษร`;
  return null;
}

/**
 * 📐 สเปกคำนวณ "จำนวนชิ้นโดยประมาณต่อแผ่นวัสดุ" ของคู่ช่องกรอกกว้าง×สูง (ดู ProductOption.sheetYield)
 * ขนาดเป็นหน่วยเดียวกับที่ลูกค้ากรอก (ซม.) — ตัวเลขและวิธีวางอิงโปรแกรมจัดวางจริงของร้าน
 * (Print-Fit บน Desktop): ชีท Dicut 100% 48.3×33 ซม. พื้นที่พิมพ์ 44.76×29.89 หักขอบเผื่อ 0.5
 * รอบด้าน → พื้นที่วางจริง 43.76×28.89 · ระยะห่างระหว่างชิ้น 0.5
 */
export interface SheetYield {
  /** ชื่อกลุ่มช่องกรอก "ด้านกว้าง" ที่ใช้คู่กัน (กลุ่มที่ตั้ง sheetYield เองคือด้านสูง) */
  pairLabel: string;
  /** พื้นที่วางชิ้นงานจริง ด้านกว้าง × ด้านยาว (หักขอบพื้นที่พิมพ์/ขอบเผื่อออกแล้ว) */
  sheetW: number;
  sheetH: number;
  /**
   * ระยะห่างระหว่างชิ้นงาน (หน่วยเดียวกับที่ลูกค้ากรอก) — งานไดคัทวางชิ้นติดกันไม่ได้
   * เช่น 0.5 = เว้น 5 มม. · คิดเฉพาะช่องไฟ "ระหว่าง" ชิ้น ไม่กินขอบแผ่น · ไม่ตั้ง = วางชิด
   */
  gap?: number;
  /**
   * ระยะเผื่อ "ด้านสูง" ต่อชิ้นตอนจัดวาง (หน่วยเดียวกับที่ลูกค้ากรอก) — งานที่ชิ้นพิมพ์จริง
   * สูงกว่าขนาดสำเร็จ เช่น ใบเย็บบนต้องเผื่อส่วนพับครอบปากถุง 2 ซม. · ไม่ตั้ง = ไม่เผื่อ
   */
  addH?: number;
  /** ชื่อแผ่นที่โชว์ให้ลูกค้า เช่น "แผ่น A3" (ไม่ตั้ง = "แผ่น") */
  sheetName?: string;
  /**
   * 🔁 หน่วยขายที่ "ใหญ่กว่าแผ่น" 1 หน่วยเท่ากับกี่แผ่น — คีย์คือหน่วยขายของเรทนั้น
   * เช่น { "ตร.ม.": 8 } = 1 ตร.ม. เท่ากับ 8 แผ่น A3 (เรทตารางเมตรของสติ๊กเกอร์ UV)
   * มีตัวคูณแล้ว unitYieldOf จึงสรุป "สั่งกี่หน่วย = ได้กี่ชิ้น" ให้เรทนั้นได้ด้วย
   * ไม่ตั้ง (หรือหน่วยขายไม่มีในนี้) = ไม่รู้ตัวคูณ → โชว์แค่ "ต่อ 1 แผ่น" ไม่คูณจำนวนที่สั่ง
   * ⚠️ เลขนี้ต้องตรงกับที่ร้านคิดเงินจริง อย่าคำนวณจากพื้นที่เอง (ปัดเศษไม่เหมือนกัน)
   */
  unitSheets?: Record<string, number>;
  /**
   * 📋 ตาราง "จำนวนชิ้นต่อแผ่น" ที่ร้านกำหนดเอง — มีตาราง = ใช้เลขในตารางแทนการคำนวณจากการจัดวาง
   * เทียบด้วย "ด้านที่ยาวที่สุด" (หน่วยเดียวกับที่ลูกค้ากรอก) กับ upTo · เรียงน้อย→มาก ใช้ข้อแรกที่ไม่เกิน
   * ข้อสุดท้ายไม่ใส่ upTo = รับทุกขนาดที่เหลือ · ไม่มีข้อไหนตรงเลย = กลับไปคำนวณจากการจัดวางตามเดิม
   * เช่น สติ๊กเกอร์วาชิ ไดคัท 100%: ≤2 ซม. 140 ชิ้น · ≤3 ซม. 70 · ≤4 ซม. 35 …
   * (เลขที่ร้านใช้จริง เผื่อพื้นที่ mark + ระยะจับชิ้นไว้แล้ว จึงน้อยกว่าที่คำนวณจากการวางชิ้นตรง ๆ)
   */
  perSheetTiers?: { upTo?: number; per: number }[];
}

/**
 * เรียงเป็นกริดแนวเดียวทั้งกล่อง — วิธีที่ช่างวางจริงและเป็นเลขที่การันตีได้ว่าวางได้แน่
 * (ช่องไฟคิดเฉพาะระหว่างชิ้น จึงขยายกล่องด้วยช่องไฟหนึ่งข้างเหมือน packSingleSize)
 */
function gridCount(w: number, h: number, binW: number, binH: number, gap: number): number {
  if (w <= 0 || h <= 0) return 0;
  return Math.max(0, Math.floor((binW + gap) / (w + gap))) * Math.max(0, Math.floor((binH + gap) / (h + gap)));
}

/** กริดที่ดีที่สุดของสองแนววาง (ตั้ง/นอน) */
function gridBest(itemW: number, itemH: number, binW: number, binH: number, gap: number): number {
  return Math.max(gridCount(itemW, itemH, binW, binH, gap), gridCount(itemH, itemW, binW, binH, gap));
}

/**
 * 📐 เพดานล่างที่ "การันตีว่าวางได้" — กริดเต็มกล่อง หรือแบ่งกล่องเป็น 2 แถบแล้วแถบละแนว
 *
 * MaxRects ใน packSingleSize เป็นอัลกอริทึมโลภ เลือกแนวชิ้นแรกผิดแล้วพลาดยาว
 * เช่น A5 (14.8×21) บนแผ่น A3 (42×29.7): คำตอบจริงคือหมุนนอนทั้ง 4 ใบพอดีแผ่น
 * แต่ MaxRects วางใบแรกแนวตั้ง (คะแนน BSSF ดีกว่าเฉพาะหน้า) แล้วเหลือเศษวางต่อไม่ได้ → ได้ 2
 * เลยต้องเทียบกับการวางแบบกริดตรง ๆ ด้วย แล้วเอาค่าที่มากกว่า — ค่าที่ได้จากตรงนี้
 * มีผังวางจริงรองรับทุกใบ ไม่ใช่การเดา จึงไม่ทำให้บอกลูกค้าเกินจริง
 */
function bandBest(itemW: number, itemH: number, binW: number, binH: number, gap: number): number {
  let best = gridBest(itemW, itemH, binW, binH, gap);
  if (itemW <= 0 || itemH <= 0) return best;
  const sides = itemW === itemH ? [itemH] : [itemH, itemW];
  // แบ่งเป็นแถบบน/ล่าง — แถบบนวางเป็นแถวสูงเท่าด้านที่เลือก n แถว ที่เหลือวางแนวไหนก็ได้
  for (const rowH of sides) {
    for (let n = 1; n * rowH + (n - 1) * gap <= binH; n++) {
      const band = n * rowH + (n - 1) * gap;
      const rest = binH - band - gap;
      best = Math.max(
        best,
        gridBest(itemW, itemH, binW, band, gap) + (rest > 0 ? gridBest(itemW, itemH, binW, rest, gap) : 0)
      );
    }
  }
  // แบ่งเป็นแถบซ้าย/ขวา — ตรรกะเดียวกันแต่สลับแกน
  for (const colW of sides) {
    for (let n = 1; n * colW + (n - 1) * gap <= binW; n++) {
      const band = n * colW + (n - 1) * gap;
      const rest = binW - band - gap;
      best = Math.max(
        best,
        gridBest(itemW, itemH, band, binH, gap) + (rest > 0 ? gridBest(itemW, itemH, rest, binH, gap) : 0)
      );
    }
  }
  return best;
}

/**
 * วางชิ้นขนาดเดียวกันให้ได้มากที่สุดในกล่อง — พอร์ตจากโปรแกรมจัดวาง Print-Fit ของร้าน
 * (MaxRects: ชิ้นถูกบวกระยะห่างรอบตัว กล่องขยายด้วยระยะห่างหนึ่งข้าง จึงคิดช่องไฟเฉพาะระหว่างชิ้น
 *  หมุนได้รายชิ้น · ให้คะแนนช่องว่างแบบ Best Short Side Fit / Best Area Fit แล้วเอาค่าที่ดีกว่า)
 */
function packSingleSize(itemW: number, itemH: number, binW: number, binH: number, gap: number): number {
  const w = itemW + gap;
  const h = itemH + gap;
  let best = 0;
  for (const heuristic of ["BSSF", "BAF"] as const) {
    const free: { x: number; y: number; w: number; h: number }[] = [
      { x: 0, y: 0, w: binW + gap, h: binH + gap },
    ];
    let count = 0;
    // เพดานกันลูป (ชิ้นเล็กสุด 1 ซม. วางได้ราวห้าร้อยกว่าชิ้น) — ถึงเพดานคือ "เยอะมาก" พอสำหรับตัวเลขบอกทาง
    while (count < 2000) {
      let fit = { score: Infinity, at: -1, rot: false };
      for (let i = 0; i < free.length; i++) {
        const r = free[i];
        if (w <= r.w && h <= r.h) {
          const score = heuristic === "BSSF" ? Math.min(r.w - w, r.h - h) : r.w * r.h - w * h;
          if (score < fit.score) fit = { score, at: i, rot: false };
        }
        if (h <= r.w && w <= r.h) {
          const score = heuristic === "BSSF" ? Math.min(r.w - h, r.h - w) : r.w * r.h - h * w;
          if (score < fit.score) fit = { score, at: i, rot: true };
        }
      }
      if (fit.at < 0) break;
      const target = free.splice(fit.at, 1)[0];
      const pw = fit.rot ? h : w;
      const ph = fit.rot ? w : h;
      count++;
      const contains = (a: (typeof free)[0], b: (typeof free)[0]) =>
        a.x >= b.x && a.y >= b.y && a.x + a.w <= b.x + b.w && a.y + a.h <= b.y + b.h;
      const placed = { x: target.x, y: target.y, w: pw, h: ph };
      for (let i = free.length - 1; i >= 0; i--) if (contains(free[i], placed)) free.splice(i, 1);
      if (ph < target.h) free.push({ x: target.x, y: target.y + ph, w: target.w, h: target.h - ph });
      if (pw < target.w) free.push({ x: target.x + pw, y: target.y, w: target.w - pw, h: ph });
      for (let i = free.length - 1; i >= 0; i--)
        for (let j = free.length - 1; j >= 0; j--)
          if (i !== j && contains(free[i], free[j])) {
            free.splice(i, 1);
            break;
          }
    }
    if (count > best) best = count;
  }
  // MaxRects โลภ พลาดผังที่ดีกว่าได้ (ดู bandBest) — เทียบกับผังกริดที่การันตีว่าวางได้เสมอ
  return Math.max(best, bandBest(itemW, itemH, binW, binH, gap));
}

/**
 * จำนวนชิ้นโดยประมาณต่อ 1 แผ่น จากค่าที่ลูกค้ากรอก (กว้างจากกลุ่ม pairLabel × สูงจากกลุ่มนี้)
 * จัดวางแบบเดียวกับโปรแกรม Print-Fit — null = ไม่ได้ตั้ง sheetYield หรือยังกรอกไม่ครบ · 0 = ใหญ่เกินแผ่น
 */
export function sheetYieldCount(
  product: Product,
  opt: ProductOption,
  selections: Record<string, string>
): number | null {
  const cfg = opt.sheetYield;
  if (!cfg) return null;
  const pair = product.options.find((o) => o.label === cfg.pairLabel);
  if (!pair) return null;
  const w = Number(parseInputValue(pair, selections[pair.label]));
  const h = Number(parseInputValue(opt, selections[opt.label]));
  if (!Number.isFinite(w) || !Number.isFinite(h) || w <= 0 || h <= 0) return null;
  const itemH = h + (cfg.addH ?? 0);
  /*
   * ร้านตั้งตารางจำนวนต่อแผ่นเองไว้ (perSheetTiers) = ใช้เลขนั้น ไม่คำนวณจากการจัดวาง
   * ตารางร้านเผื่อพื้นที่ mark/ระยะจับชิ้นไว้แล้ว การคำนวณตรง ๆ จะได้เยอะกว่าที่ทำได้จริง
   */
  for (const t of cfg.perSheetTiers ?? []) {
    if ((t.upTo == null || Math.max(w, itemH) <= t.upTo) && t.per > 0) return t.per;
  }
  return packSingleSize(w, itemH, cfg.sheetW, cfg.sheetH, cfg.gap ?? 0);
}

/**
 * 📏 สเปก "ค่าบริการตามขนาดชิ้นงาน" ของตัวเลือกหนึ่ง (ดู ProductOptionChoice.sizeFee)
 * งานผ้าแขวนผนัง: ค่าตัดแบ่ง/เย็บขอบ/โพ้งขอบ คิดต่อชิ้นตาม "ด้านที่ยาวที่สุด" ของชิ้นงาน
 * และคูณจำนวนชิ้นที่ตัดได้ต่อ 1 หน่วยขาย (จัดวางแบบเดียวกับ sheetYield)
 */
export interface SizeFee {
  /**
   * อ่านขนาดจากช่องกรอกเมื่อค่าของกลุ่มนี้ตรงเงื่อนไข (ตั้งให้ตรงกับ showWhen ของช่องกรอก
   * กันอ่านค่าค้างของช่องที่ถูกซ่อน) — ไม่ตรง = ใช้ defaultLongest แทน · ไม่ตั้ง = อ่านช่องกรอกเสมอ
   */
  when?: { label: string; choices: string[] };
  /**
   * 🔒 คิดค่าบริการนี้ "เฉพาะเมื่อ" ค่าของกลุ่มที่ระบุตรงเงื่อนไข — ไม่ตรง = ไม่คิดเลย (ทั้งสองทาง
   * ทั้งอ่านช่องกรอกและ defaultLongest) · ต่างจาก when ที่แค่สลับว่าจะอ่านขนาดจากไหน
   * ใช้กับค่าบริการที่ "ขึ้นกับตัวเลือกกลุ่มอื่น" เช่น ค่าตัดขอบของ **ตัดเต็มหลา** ที่คิดเฉพาะตอน
   * เลือกเย็บขอบ/โพ้งขอบ (ต้องเจียนขอบผ้าให้ก่อน) — เลือกไม่เย็บขอบ = รับผ้าเต็มผืน ไม่มีค่าตัด
   */
  onlyWhen?: { label: string; choices: string[] };
  /** ชื่อกลุ่มช่องกรอก ด้านกว้าง / ด้านยาว (display "input") */
  widthLabel: string;
  heightLabel: string;
  /** ขั้นราคา: ด้านยาวสุดไม่เกิน upTo (หน่วยเดียวกับที่กรอก) → fee บาท/ชิ้น — เรียงเล็ก→ใหญ่ · เกินขั้นสุดท้ายใช้ขั้นสุดท้าย */
  tiers: { upTo: number; fee: number }[];
  /** ด้านยาวสุดที่ใช้เมื่อ when ไม่ตรง เช่น ตัดเต็มหลา = 145 — ไม่ตั้ง = ช่วงนั้นไม่คิดค่าบริการ */
  defaultLongest?: number;
  /** คูณจำนวนชิ้นต่อ 1 หน่วยขาย จากการจัดวางชิ้น กว้าง×ยาว ในพื้นที่นี้ (ไม่ตั้ง = คิดชิ้นเดียว) */
  perPiece?: { sheetW: number; sheetH: number; gap?: number };
}

/** 💰 ที่มาของค่าบริการตามขนาด — ไว้กางให้ลูกค้าเห็นว่า +฿ มาจาก ชิ้นละเท่าไหร่ × กี่ชิ้น */
export interface SizeFeeBreakdown {
  /** ยอดรวม = perPiece × pieces */
  fee: number;
  /** บาท/ชิ้น ตามขั้นด้านยาวสุด */
  perPiece: number;
  /** จำนวนชิ้นที่คูณ (1 = ไม่ได้คูณจากการจัดวาง เช่น เต็มหลา) */
  pieces: number;
}

/**
 * 💰 ค่าบริการตามขนาด ณ ค่าที่ลูกค้ากรอกตอนนี้ พร้อมที่มา — null = ยังกรอกไม่ครบ/เงื่อนไขไม่คิด
 * ใช้ข้อมูลจาก selections ล้วน ๆ (ไม่ต้องมี product) จึงเรียกได้จากทุกชั้นที่คิด extra
 */
export function sizeFeeBreakdownOf(cfg: SizeFee, selections: Record<string, string>): SizeFeeBreakdown | null {
  const tierFee = (longest: number) =>
    (cfg.tiers.find((t) => longest <= t.upTo) ?? cfg.tiers[cfg.tiers.length - 1])?.fee ?? 0;
  // 🔒 ประตูแรก: กลุ่มอื่นยังไม่เข้าเงื่อนไข = ไม่คิดค่าบริการนี้เลย (ดู SizeFee.onlyWhen)
  if (cfg.onlyWhen && !valueMatchesAny(selections[cfg.onlyWhen.label], cfg.onlyWhen.choices)) return null;
  if (cfg.when && !valueMatchesAny(selections[cfg.when.label], cfg.when.choices)) {
    if (!cfg.defaultLongest) return null;
    const fee = tierFee(cfg.defaultLongest);
    return fee ? { fee, perPiece: fee, pieces: 1 } : null;
  }
  const num = (v: string | undefined) => {
    const n = parseFloat(String(v ?? "").replace(/[^\d.]/g, ""));
    return Number.isFinite(n) && n > 0 ? n : null;
  };
  const w = num(selections[cfg.widthLabel]);
  const h = num(selections[cfg.heightLabel]);
  if (w == null || h == null) return null; // ช่องกรอกบังคับกรอกก่อนสั่งอยู่แล้ว — ระหว่างพิมพ์ยังไม่คิด
  const perPiece = tierFee(Math.max(w, h));
  if (!perPiece) return null;
  if (!cfg.perPiece) return { fee: perPiece, perPiece, pieces: 1 };
  // ชิ้นใหญ่จนวางไม่ได้ (pieces 0) ก็ยังคิดอย่างน้อย 1 ชิ้น — ช่องกรอกมี max กันขนาดเกินอยู่แล้ว
  const pieces = Math.max(1, packSingleSize(w, h, cfg.perPiece.sheetW, cfg.perPiece.sheetH, cfg.perPiece.gap ?? 0));
  return { fee: perPiece * pieces, perPiece, pieces };
}

/** 💰 เฉพาะยอดรวมของ sizeFeeBreakdownOf — ตัวที่ choiceExtraOf ใช้คิดเงินจริง */
export function sizeFeeOf(cfg: SizeFee, selections: Record<string, string>): number {
  return sizeFeeBreakdownOf(cfg, selections)?.fee ?? 0;
}

/**
 * 💰 สเปก "คิดเงินตามตัวเลขที่กรอก" ของกลุ่มช่องกรอก (ดู ProductOption.inputFee)
 * ต่างจาก SizeFee ตรงที่ SizeFee = ขั้นบันไดตามด้านยาวสุดของชิ้นงาน
 * ส่วนตัวนี้ = คูณตรง ๆ กับค่าที่กรอก (ปฏิทินผ้าแคนวาส: เพิ่มขนาดนิ้วละ 15/25 บาทต่อด้าน)
 */
export interface InputFee {
  /** บาทต่อ 1 หน่วยที่กรอก เมื่อไม่มีเรทเงื่อนไขไหนตรง (0 = นอกเงื่อนไขไม่คิด) */
  perUnit: number;
  /**
   * เรทที่ต่างกันตามตัวเลือกของกลุ่มอื่น — ใช้ข้อแรกที่ตรง (เช่น ซับลิเมชั่น 15 · UV 25)
   * ไม่ระบุ perUnit = ใช้ perUnit กลาง (ข้อที่มีไว้ตั้งแค่โควตาฟรีตามขนาด ก็ไม่ต้องซ้ำเรท)
   */
  rates?: { when: { label: string; choices: string[] }; perUnit?: number; free?: number; max?: number }[];
  /**
   * 🎁 โควตาที่รวมในราคา — คิดเงินเฉพาะ "ส่วนที่เกิน" จากนี้ (จุดไดคัท: A5 ฟรี 50 จุดแรก)
   * ลำดับหา: rates ข้อที่ตรงและตั้ง free ไว้ → freeBySize (ขนาดที่กรอกเอง) → free กลาง → 0
   */
  free?: number;
  /**
   * 🚧 เพดานที่กรอกได้ของขั้นนั้น ๆ — ตารางร้านมีทั้ง "ฟรีถึงเท่าไหร่" (free) และ "รับได้มากสุดเท่าไหร่"
   * เช่น จุดไดคัทชิ้น A7: ฟรี 12 จุด · เกินจากนั้นจุดละ ฿0.50 · แต่รับไม่เกิน 20 จุด
   * ลำดับหาเหมือน free (rates ข้อที่ตรง → freeBySize → max กลาง) · ไม่ตั้งที่ไหนเลย = ใช้ input.max ตามเดิม
   */
  max?: number;
  /**
   * 🎁 โควตาตามขนาดที่ลูกค้ากรอกเอง (คู่ช่องกว้าง×สูง) — ยังกรอกไม่ครบ = ใช้ free กลาง
   * เทียบได้ 2 แบบตามที่ร้านคิดจริง:
   *   by ไม่ตั้ง / "area" — เทียบ "พื้นที่ ตร.ซม." กับ minArea · tiers เรียงมาก→น้อย ใช้ข้อแรกที่พื้นที่ถึง
   *   by "longest"       — เทียบ "ด้านที่ยาวที่สุด" (ซม.) กับ upTo · tiers เรียงน้อย→มาก ใช้ข้อแรกที่ไม่เกิน
   * (ตารางจุดไดคัทของร้านคิดจากด้านยาวสุด: ≤7 ซม. 5 จุด · ≤11 20 · ≤15 50 · ≤21 70 · ใหญ่กว่านั้น 180)
   */
  freeBySize?: {
    widthLabel: string;
    heightLabel: string;
    by?: "area" | "longest";
    /** area ใช้ minArea · longest ใช้ upTo (ไม่ใส่ = ข้อสุดท้ายรับทุกขนาดที่เหลือ) · max = เพดานของขั้นนั้น */
    tiers: { minArea?: number; upTo?: number; free: number; max?: number }[];
  };
  /**
   * 🎁 สั่งถึงจำนวนนี้ "ต่อ 1 ลาย" = ไม่คิดค่าส่วนที่เกินโควตาเลย (จุดไดคัท: 25 แผ่น A3 ต่อ 1 ลาย ฟรีค่าจุด)
   * เทียบด้วย ⌊จำนวนที่สั่ง ÷ จำนวนลาย⌋ — สั่ง 50 แผ่น 2 ลาย = 25 แผ่น/ลาย ก็ได้ฟรีเหมือนกัน
   * ⚠️ ยกเว้นแค่ "ค่าส่วนเกิน" · เพดาน max ยังคุมเหมือนเดิม กรอกเกินเพดานยังสั่งไม่ได้
   */
  freeFromQtyPerDesign?: number;
  /**
   * หน่วยที่ใช้เขียนเกณฑ์ข้างบนให้ลูกค้าอ่าน (เช่น "ตร.ม.") — ไม่ตั้ง = ใช้หน่วยขายของเรทที่เลือกอยู่
   * จำเป็นตอนหน่วยของเรทไม่ตรงกับหน่วยที่กรอกจริง (UV เรทตารางเมตร: tiers เป็น ตร.ม. แต่ pricing.unit ยังเป็น "แผ่น A3")
   */
  freeFromQtyUnit?: string;
}

/** 💰 เรทต่อหน่วยที่มีผลตอนนี้ — ไล่ rates ตามลำดับ ไม่ตรงข้อไหน/ข้อที่ตรงไม่ตั้งเรท ใช้ perUnit กลาง */
export function inputFeeRateOf(cfg: InputFee, selections: Record<string, string>): number {
  for (const r of cfg.rates ?? []) {
    if (valueMatchesAny(selections[r.when.label], r.when.choices)) return r.perUnit ?? cfg.perUnit;
  }
  return cfg.perUnit;
}

/** 🎁 โควตาฟรีที่มีผลตอนนี้ — rates ข้อที่ตรง (และตั้ง free) ชนะ · แล้วค่อยดูขนาดที่กรอกเอง · ท้ายสุด free กลาง */
export function inputFeeQuotaOf(cfg: InputFee, selections: Record<string, string>): number {
  for (const r of cfg.rates ?? []) {
    if (r.free != null && valueMatchesAny(selections[r.when.label], r.when.choices)) return r.free;
  }
  const bs = cfg.freeBySize;
  if (bs) {
    // ค่าที่เก็บมีหน่วยต่อท้าย ("10 ซม.") — ต้องดึงเฉพาะตัวเลขข้างหน้า ไม่งั้น Number() ได้ NaN
    // แล้วโควตาหล่นไปใช้ free กลาง แทนที่จะเทียบขนาดจริง
    // ⚠️ ห้ามใช้ replace(/[^0-9.]/g,"") — "ซม." มีจุดติดมาด้วย "7.1 ซม." จะกลายเป็น "7.1." = NaN
    // (เลขจำนวนเต็มรอดเพราะ "7." ยัง Number() ได้ บั๊กเลยโผล่เฉพาะค่าทศนิยม)
    const num = (v: string | undefined) => Number((v ?? "").match(/\d+(\.\d+)?/)?.[0]);
    const w = num(selections[bs.widthLabel]);
    const h = num(selections[bs.heightLabel]);
    if (Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0) {
      if (bs.by === "longest") {
        const longest = Math.max(w, h);
        for (const t of bs.tiers) if (t.upTo == null || longest <= t.upTo) return t.free;
      } else {
        const area = w * h;
        for (const t of bs.tiers) if (t.minArea == null || area >= t.minArea) return t.free;
      }
    }
  }
  return cfg.free ?? 0;
}

/**
 * 🚧 เพดานที่กรอกได้ตอนนี้ (null = ไม่ได้ตั้งไว้ ใช้ input.max ตามเดิม)
 * ไล่ลำดับเดียวกับโควตาฟรี: rates ข้อที่ตรง → ขั้นตามขนาดที่กรอกเอง → max กลาง
 * แยกจาก inputFeeQuotaOf เพราะบางขั้นตั้งแค่โควตาไม่ได้ตั้งเพดาน (ยังกรอกเกินได้ไม่จำกัด)
 */
export function inputFeeMaxOf(cfg: InputFee, selections: Record<string, string>): number | null {
  for (const r of cfg.rates ?? []) {
    if (r.max != null && valueMatchesAny(selections[r.when.label], r.when.choices)) return r.max;
  }
  const bs = cfg.freeBySize;
  if (bs) {
    const num = (v: string | undefined) => Number((v ?? "").match(/\d+(\.\d+)?/)?.[0]);
    const w = num(selections[bs.widthLabel]);
    const h = num(selections[bs.heightLabel]);
    if (Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0) {
      if (bs.by === "longest") {
        const longest = Math.max(w, h);
        for (const t of bs.tiers) if (t.upTo == null || longest <= t.upTo) return t.max ?? cfg.max ?? null;
      } else {
        const area = w * h;
        for (const t of bs.tiers) if (t.minArea == null || area >= t.minArea) return t.max ?? cfg.max ?? null;
      }
    }
  }
  return cfg.max ?? null;
}

/** 🚧 เพดานที่ใช้จริงของช่องกรอกนี้ — ขั้นตามตัวเลือกที่เลือกอยู่ชนะ input.max ที่ตั้งไว้กลาง ๆ */
export function inputMaxOf(opt: ProductOption, selections?: Record<string, string>): number | undefined {
  const byFee = opt.inputFee && selections ? inputFeeMaxOf(opt.inputFee, selections) : null;
  return byFee ?? opt.input?.max;
}

/**
 * 💰 ค่าบริการของกลุ่มช่องกรอกนี้ = (ค่าที่กรอก − โควตาฟรี) × เรทต่อหน่วย (0 = ยังไม่กรอก/ไม่เกินโควตา)
 * กลุ่มช่องกรอกไม่มี choices ให้บวก จึงเป็นทางเดียวที่กลุ่มชนิดนี้คิดเงินได้
 */
export function inputFeeOf(opt: ProductOption, selections: Record<string, string>, qty?: number): number {
  const cfg = opt.inputFee;
  if (!cfg || !isInputOption(opt)) return 0;
  const n = Number(parseInputValue(opt, selections[opt.label]));
  if (!Number.isFinite(n) || n <= 0) return 0;
  if (inputFeeWaived(cfg, selections, qty)) return 0;   // 🎁 สั่งเยอะพอต่อลาย = ส่วนเกินไม่คิดเงิน
  const rate = inputFeeRateOf(cfg, selections);
  const over = n - inputFeeQuotaOf(cfg, selections);
  return rate > 0 && over > 0 ? over * rate : 0;
}

/**
 * 🎁 จำนวนที่สั่งถึงขั้น "ฟรีค่าส่วนเกิน" แล้วหรือยัง (freeFromQtyPerDesign)
 * เทียบต่อ 1 ลาย: ⌊qty ÷ จำนวนลาย⌋ — งานคละลายต้องสั่งถึงเกณฑ์ "ของแต่ละลาย" ถึงจะฟรี
 * ไม่ได้ตั้งเกณฑ์ / ยังไม่รู้จำนวน (หน้าจอที่ไม่ส่ง qty มา) = ไม่ยกเว้น คิดเงินตามปกติ
 */
export function inputFeeWaived(
  cfg: InputFee,
  selections: Record<string, string>,
  qty?: number
): boolean {
  const need = cfg.freeFromQtyPerDesign;
  if (!need || need <= 0 || qty == null || !Number.isFinite(qty)) return false;
  return Math.floor(qty / Math.max(1, designCountOf(selections))) >= need;
}

/** 📐 ผลของ unitYieldOf — สั่ง 1 หน่วยแล้วได้งานกี่ชิ้น */
export interface UnitYield {
  /** จำนวนชิ้นต่อ 1 หน่วยที่สั่ง · 0 = ขนาดที่กรอกใหญ่เกิน 1 แผ่น */
  per: number;
  /** ขนาดที่ทำให้ได้เท่านี้ เช่น "A5" (ขนาดตัด) หรือ "12 × 8 ซม." (ไดคัทตามขนาด) */
  size: string;
  /** ชื่อกลุ่มแบบอ่านให้ลูกค้า เช่น "ขนาดตัด" — ตัดวงเล็บบอกหน่วย/ด้านท้ายชื่อออกแล้ว */
  label: string;
  /** label จริงของกลุ่ม (ยังมีวงเล็บ) — ฝั่งหน้าสินค้าใช้เทียบว่ากลุ่มไหนเป็นเจ้าของตัวเลขนี้ */
  optLabel: string;
  /**
   * per นับต่อ 1 หน่วยอะไร · null = ต่อ 1 หน่วยขายของเรทที่เลือกอยู่ (คูณจำนวนที่สั่งได้ตรง ๆ)
   * มีชื่อ = ต่อแผ่นวัสดุชื่อนั้น เช่น "แผ่น A3" — เรทที่ขายเป็น ตร.ม. คูณจำนวนที่สั่งตรง ๆ ไม่ได้
   * (1 ตร.ม. ไม่ใช่ 1 แผ่น A3) ฝั่งที่เอาไปโชว์ต้องเทียบกับหน่วยขายก่อนคูณ
   */
  unit: string | null;
  /** true = คำนวณสดจากการจัดวาง (ไดคัทตามขนาด) จำนวนจริงขึ้นกับรูปทรงลาย · false = ขนาดตัดตายตัว */
  approx: boolean;
  /**
   * 🔁 มีเมื่อ per ถูกแปลงจาก "ต่อแผ่น" มาเป็น "ต่อหน่วยขาย" แล้ว (เรทตารางเมตร)
   * ใช้กางที่มาให้ลูกค้าเห็น: 40 ชิ้น/แผ่น A3 × 8 แผ่น = 320 ชิ้น/ตร.ม.
   */
  via?: { perSheet: number; sheets: number; sheetName: string };
}

/**
 * 📐 สั่ง 1 หน่วย (แผ่น A3 / ตร.ม.) แล้วได้งานกี่ชิ้น — งานที่ "แบ่งแผ่น" ทั้งสองแบบมาที่นี่ที่เดียว
 *  - เลือกขนาดตัดตายตัว (A4-A7) → อ่านจาก ProductOptionChoice.piecesPerUnit
 *  - ไดคัทตามขนาดที่กรอกเอง → คำนวณจากการจัดวางเหมือน sheetYieldCount
 * เอากลุ่มที่ "แสดงอยู่จริง" ตัวแรกที่อ่านได้ (สินค้าจริงมีกลุ่มที่โผล่พร้อมกันได้กลุ่มเดียว —
 * ขนาดตัดของแต่ละเรทแยกกลุ่มกันด้วย showWhenAlso อยู่แล้ว)
 * null = งานนี้ไม่ได้แบ่งแผ่น (1 หน่วย = 1 ชิ้น) หรือยังเลือก/กรอกไม่ครบ
 */
export function unitYieldOf(product: Product, selections: Record<string, string>): UnitYield | null {
  for (const opt of product.options ?? []) {
    if (!optionActive(opt, selections)) continue;
    /*
     * ชื่อกลุ่มพวกนี้ห้อยวงเล็บบอกหน่วย/ด้านไว้ท้าย ("ขนาดตัด (ตร.ม.)" · "ขนาดไดคัท (สูง)")
     * ตัดออกเหลือชื่อขนาดเดียว ไม่งั้นสรุปอ่านเป็น "ขนาดไดคัท (สูง) 5 × 5 ซม." ซึ่งงง
     * (หน่วยบอกอยู่ในประโยคสรุปแล้วว่า "ต่อ 1 ตร.ม." จึงไม่ต้องซ้ำในชื่อกลุ่ม)
     */
    const label = opt.label.replace(/\s*\([^()]*\)\s*$/, "").trim() || opt.label;
    const picked = selections[opt.label];
    const choice = picked ? opt.choices.find((c) => c.name === picked) : undefined;
    if (choice?.piecesPerUnit && choice.piecesPerUnit > 0) {
      return { per: choice.piecesPerUnit, size: choice.name, label, optLabel: opt.label, unit: null, approx: false };
    }
    const cfg = opt.sheetYield;
    if (!cfg) continue;
    const perSheet = sheetYieldCount(product, opt, selections);
    if (perSheet == null) continue;
    const pair = product.options.find((o) => o.label === cfg.pairLabel);
    const unit = opt.input?.unit ?? "";
    const w = pair ? parseInputValue(pair, selections[pair.label]) : "";
    const h = parseInputValue(opt, selections[opt.label]);
    const sheetName = cfg.sheetName ?? "แผ่น";
    const size = `${w} × ${h}${unit ? ` ${unit}` : ""}`;
    /*
     * เรทที่ขายเป็นหน่วยใหญ่กว่าแผ่น (ตร.ม.) — แปลง "ต่อแผ่น" เป็น "ต่อหน่วยขาย" ด้วยตัวคูณที่ตั้งไว้
     * ไม่มีตัวคูณ = คืนเลขต่อแผ่นไปตามเดิม (ฝั่งโชว์จะไม่คูณจำนวนที่สั่งให้ ดู UnitYield.unit)
     */
    const saleUnit = activeMatrix(product, selections)?.unit ?? "";
    const sheets = saleUnit && saleUnit !== sheetName ? cfg.unitSheets?.[saleUnit] : undefined;
    if (sheets && sheets > 0) {
      return {
        per: perSheet * sheets,
        size,
        label,
        optLabel: opt.label,
        unit: null,
        approx: true,
        via: { perSheet, sheets, sheetName },
      };
    }
    return { per: perSheet, size, label, optLabel: opt.label, unit: sheetName, approx: true };
  }
  return null;
}

/** ตัวคั่นค่าของกลุ่ม "เลือกได้หลายอย่าง" (display: 'multi') เมื่อเก็บลง selections */
export const MULTI_SEP = " + ";

/** กลุ่มนี้ให้ลูกค้าติ๊กเลือกได้หลายอย่างไหม */
export function isMultiOption(opt: ProductOption): boolean {
  return opt.display === "multi";
}

/**
 * ตัวเลือกนี้ให้ลูกค้าระบุจำนวนได้ไหม (เฉพาะกลุ่ม multi)
 * ตั้งรายตัวที่ choice.qty · กลุ่มที่ตั้งแบบเก่าไว้ทั้งกลุ่ม (qtyPerChoice) ยังใช้ได้เหมือนเดิม
 */
export function hasChoiceQty(opt: ProductOption, choiceName: string): boolean {
  if (!isMultiOption(opt)) return false;
  const c = opt.choices.find((x) => x.name === choiceName);
  return c?.qty ?? opt.qtyPerChoice === true;
}

/** กลุ่มนี้มีตัวเลือกที่ระบุจำนวนได้อย่างน้อยหนึ่งตัวไหม (ใช้ตัดสินใจว่าจะขึ้นป้ายบอกลูกค้าไหม) */
export function anyChoiceQty(opt: ProductOption): boolean {
  return isMultiOption(opt) && opt.choices.some((c) => hasChoiceQty(opt, c.name));
}

/**
 * หน่วยของจำนวนที่ลูกค้าระบุในตัวเลือกนี้ (เช่น "ซม.") — ไม่ตั้ง = ไม่มีหน่วย นับเป็นจำนวนอัน
 * ใช้แค่กับข้อความที่แสดง ไม่แตะการคิดราคา
 */
export function choiceQtyUnit(opt: ProductOption, choiceName: string): string {
  return opt.choices.find((x) => x.name === choiceName)?.qtyUnit?.trim() ?? "";
}

/** เพดานจำนวนต่อตัวเลือก */
export const MAX_CHOICE_QTY = 99;
export function choiceQtyMax(opt: ProductOption, choiceName: string): number {
  const c = opt.choices.find((x) => x.name === choiceName);
  const m = Math.floor(Number(c?.qtyMax ?? opt.qtyMax));
  return Number.isFinite(m) && m > 0 ? Math.min(m, MAX_CHOICE_QTY) : MAX_CHOICE_QTY;
}

/** ตัวเลือกที่ติ๊กไว้ 1 ตัว พร้อมจำนวนที่ลูกค้าระบุ (ไม่ระบุ = 1) */
export interface MultiPick {
  name: string;
  qty: number;
}

/**
 * จำนวนของตัวเลือกเขียนต่อท้ายชื่อว่า " ×N" (เว้นวรรคหน้า × เสมอ) — "เพิ่มสาย ×2"
 * ต้องมีเว้นวรรคหน้า × เพื่อไม่ให้ชื่อที่เป็นขนาด (เช่น "10×15 ซม.") ถูกอ่านเป็นจำนวน
 * และตอนอ่านยังเทียบกับรายชื่อตัวเลือกจริงอีกชั้น (ดู parseMultiEntry)
 */
const MULTI_QTY_RE = /^(.+?)\s+×\s*(\d+)$/;

/** เขียนตัวเลือก+จำนวนเป็นข้อความ (จำนวน 1 = ชื่อเปล่า ๆ เหมือนเดิม) */
export function formatMultiPick(name: string, qty: number): string {
  return qty > 1 ? `${name} ×${qty}` : name;
}

/**
 * อ่านข้อความตัวเลือก 1 ตัวกลับเป็นชื่อ+จำนวน
 * ส่ง choiceNames มาด้วยได้ (รายชื่อตัวเลือกจริงของกลุ่ม) — ชื่อที่ตรงเป๊ะจะไม่ถูกแยกจำนวน
 */
export function parseMultiEntry(entry: string, choiceNames?: string[]): MultiPick {
  const raw = entry.trim();
  if (choiceNames?.includes(raw)) return { name: raw, qty: 1 };
  const m = MULTI_QTY_RE.exec(raw);
  if (!m) return { name: raw, qty: 1 };
  const name = m[1].trim();
  // ชื่อที่แยกออกมาไม่ใช่ตัวเลือกจริง = ข้อความนั้นเป็นชื่อของมันเอง ไม่ใช่จำนวน
  if (choiceNames && !choiceNames.includes(name)) return { name: raw, qty: 1 };
  const qty = Math.floor(Number(m[2]));
  return { name, qty: qty > 1 ? Math.min(qty, MAX_CHOICE_QTY) : 1 };
}

/** แยกค่าที่เก็บรวมไว้กลับเป็นรายชื่อ+จำนวน ("ซิปใน + สายสะพาย ×2" → [{ซิปใน,1},{สายสะพาย,2}]) */
export function splitMultiPicks(value: string | undefined, choiceNames?: string[]): MultiPick[] {
  const parts = (value ?? "")
    .split(MULTI_SEP)
    .map((s) => s.trim())
    .filter(Boolean);
  /*
   * ⚠️ ชื่อตัวเลือกที่มี " + " ในตัว (เช่น "เจาะรู + ใส่ตาไก่") จะโดน split ผ่าแตกเป็นชื่อที่ไม่มีจริง
   * แล้วถูกกรองทิ้ง = ติ๊กไม่ติด — ประกอบชิ้นที่แตกกลับก่อน โดยลองรวมช่วงที่ยาวสุดที่ตรงชื่อจริง
   * (รองรับท้ายชื่อมีจำนวน "×N" ด้วย) · ชื่อปกติไม่เข้าเงื่อนไขนี้ พฤติกรรมเดิมทุกอย่าง
   */
  if (parts.length > 1 && choiceNames?.some((n) => n.includes(MULTI_SEP))) {
    const merged: string[] = [];
    for (let i = 0; i < parts.length; ) {
      let take = 1;
      let piece = parts[i];
      for (let j = parts.length; j > i + 1; j--) {
        const cand = parts.slice(i, j).join(MULTI_SEP);
        if (choiceNames.includes(cand) || choiceNames.includes(cand.replace(/\s*×\s*\d+$/, "").trim())) {
          piece = cand;
          take = j - i;
          break;
        }
      }
      merged.push(piece);
      i += take;
    }
    return merged.map((s) => parseMultiEntry(s, choiceNames));
  }
  return parts.map((s) => parseMultiEntry(s, choiceNames));
}

/** แยกค่าที่เก็บรวมไว้กลับเป็นรายชื่อตัวเลือก (ตัดจำนวนออก) */
export function splitMulti(value: string | undefined, choiceNames?: string[]): string[] {
  return splitMultiPicks(value, choiceNames).map((p) => p.name);
}

/** รวมรายชื่อตัวเลือกที่ติ๊กไว้เป็นข้อความเดียว (ว่าง = ไม่ได้เลือกอะไรเลย) */
export function joinMulti(names: string[]): string {
  return names.join(MULTI_SEP);
}

/** รวมตัวเลือก+จำนวนที่ติ๊กไว้เป็นข้อความเดียว */
export function joinMultiPicks(picks: MultiPick[]): string {
  return joinMulti(picks.map((p) => formatMultiPick(p.name, p.qty)));
}

/** ตัวเลือกที่เลือกอยู่ของกลุ่มนี้ พร้อมจำนวน — กลุ่มปกติได้ 1 ตัว · กลุ่ม multi ได้ 0 ถึงหลายตัว */
export function selectedPicks(opt: ProductOption, selections: Record<string, string>): MultiPick[] {
  const cur = selections[opt.label];
  if (!cur) return [];
  if (!isMultiOption(opt)) return [{ name: cur, qty: 1 }];
  const picks = splitMultiPicks(cur, opt.choices.map((c) => c.name));
  // ตัวที่ไม่ได้เปิดช่องจำนวน นับเป็น 1 เสมอ (กันข้อมูลเก่าที่เคยเปิดไว้ทำราคาเพี้ยน)
  return picks.map((p) =>
    hasChoiceQty(opt, p.name) ? { ...p, qty: Math.min(p.qty, choiceQtyMax(opt, p.name)) } : { ...p, qty: 1 }
  );
}

/** ตัวเลือกที่เลือกอยู่ของกลุ่มนี้ — กลุ่มปกติได้ 1 ตัว · กลุ่ม multi ได้ 0 ถึงหลายตัว */
export function selectedNames(opt: ProductOption, selections: Record<string, string>): string[] {
  return selectedPicks(opt, selections).map((p) => p.name);
}

/**
 * ค่าที่เลือกอยู่ของกลุ่มหนึ่ง เข้าเงื่อนไข "ต้องเป็นหนึ่งใน wanted" ไหม
 * รองรับกลุ่ม multi ด้วย — ติ๊กไว้หลายตัว ถ้ามีตัวใดตรงก็ถือว่าเข้าเงื่อนไข
 * (เช็คค่าตรง ๆ ก่อนเสมอ กันชื่อตัวเลือกที่มี " + " อยู่ในตัวถูกแยกผิด)
 */
function valueMatchesAny(current: string | undefined, wanted: string[]): boolean {
  if (!current) return false;
  if (wanted.includes(current)) return true;
  // เทียบทั้งข้อความดิบ (เผื่อชื่อตัวเลือกมี " ×N" อยู่ในตัว) และชื่อที่ตัดจำนวนออกแล้ว
  return current
    .split(MULTI_SEP)
    .map((s) => s.trim())
    .filter(Boolean)
    .some((raw) => wanted.includes(raw) || wanted.includes(parseMultiEntry(raw).name));
}

/**
 * กลุ่มนี้ต้องโชว์ให้ลูกค้าเลือกไหม ณ ตัวเลือกชุดนี้ (ดู ProductOption.showWhen)
 * ซ่อนอยู่ = ไม่แสดงในหน้าสินค้า ไม่คิดราคา และไม่ติดไปกับตะกร้า/ออเดอร์
 */
export function optionVisible(opt: ProductOption, selections: Record<string, string>): boolean {
  // ตั้งไม่ครบ (ไม่มีกลุ่ม หรือไม่ได้ติ๊กค่าไหนเลย) = ข้อนั้นไม่นับ · ตั้งครบทั้งสองข้อ = ต้องตรงทั้งคู่
  const pass = (s?: { label: string; choices: string[] }) =>
    !s?.label || !s.choices?.length || valueMatchesAny(selections[s.label], s.choices);
  // เงื่อนไข "หรือ" (showWhenAny) — ผ่านเมื่อข้อใดข้อหนึ่งตรง (ข้อที่ตั้งไม่ครบไม่นับเป็นทางเปิด)
  const anyConds = (opt.showWhenAny ?? []).filter((s) => s?.label && s.choices?.length);
  const anyPass = !anyConds.length || anyConds.some((s) => valueMatchesAny(selections[s.label], s.choices));
  return anyPass && pass(opt.showWhen) && pass(opt.showWhenAlso) && (opt.showWhenAll ?? []).every(pass);
}

/** ราคาบวกเพิ่มของกลุ่มนี้ใช้กับจำนวนนี้ไหม (ต่ำกว่าเกณฑ์ = รวมในราคาแล้ว) */
export function optionExtraApplies(opt: ProductOption, qty: number): boolean {
  return !opt.extraFromQty || qty >= opt.extraFromQty;
}

/**
 * +฿ ของตัวเลือกนี้ ณ จำนวนที่สั่ง จากตาราง extraTiers (ดู ProductOptionChoice.extraTiers)
 * ไม่มีตาราง หรือยังไม่รู้จำนวน = undefined → ผู้เรียกใช้ extra ตายตัวตามเดิม
 * เรียงขั้นให้เองก่อนเทียบ (ขั้นที่ไม่ใส่ upTo ถือเป็นขั้นสุดท้ายเสมอ) — ตารางที่กรอกสลับลำดับก็ยังคิดถูก
 */
export function extraTierAt(c: ProductOptionChoice | undefined, qty?: number): number | undefined {
  const rows = (c?.extraTiers ?? []).filter((t) => Number.isFinite(t?.extra));
  if (!rows.length || qty == null || !Number.isFinite(qty)) return undefined;
  const n = Math.max(1, Math.floor(qty));
  const sorted = [...rows].sort((a, b) => (a.upTo ?? Infinity) - (b.upTo ?? Infinity));
  return (sorted.find((t) => t.upTo == null || n <= t.upTo) ?? sorted[sorted.length - 1]).extra;
}

/**
 * ขั้นที่ถูกที่สุดของตาราง (ขั้นสุดท้าย) — ใช้บอกลูกค้าว่า "สั่งครบเท่านี้เหลือเท่านี้"
 * คืน null เมื่อไม่มีตาราง หรือมีขั้นเดียว (ไม่มีอะไรให้ชวนสั่งเพิ่ม)
 */
export function extraTierBest(c: ProductOptionChoice | undefined): { fromQty: number; extra: number } | null {
  const rows = (c?.extraTiers ?? []).filter((t) => Number.isFinite(t?.extra));
  if (rows.length < 2) return null;
  const sorted = [...rows].sort((a, b) => (a.upTo ?? Infinity) - (b.upTo ?? Infinity));
  const last = sorted[sorted.length - 1];
  const prev = sorted[sorted.length - 2];
  return { fromQty: Math.max(1, Math.floor(prev.upTo ?? 0) + 1), extra: last.extra };
}

/**
 * ราคาบวกเพิ่ม (+฿) ของตัวเลือกที่เลือกในกลุ่มนี้ หลังหักเงื่อนไข "ฟรีเมื่อ"
 * ใช้ทั้งตอนคิดราคาและตอนแสดงป้าย +฿ บนหน้าร้าน จะได้ตรงกันเสมอ
 */
export function choiceExtraOf(
  opt: ProductOption,
  selections: Record<string, string>,
  choiceName: string,
  /** จำนวนที่สั่ง — ใส่มาเมื่อไหร่ ตัวเลือกที่มีตาราง extraTiers จะใช้ราคาของช่วงนั้น */
  qty?: number
): number {
  const c = opt.choices.find((ch) => ch.name === choiceName);
  // 📏 ค่าบริการตามขนาดชิ้นงาน (sizeFee) นับเป็นส่วนหนึ่งของ +฿ ตัวเลือกนี้ — โดนกติกา freeWhen ด้วยกัน
  const extra = (extraTierAt(c, qty) ?? c?.extra ?? 0) + (c?.sizeFee ? sizeFeeOf(c.sizeFee, selections) : 0);
  if (!extra) return 0;
  const f = opt.freeWhen;
  if (f && f.choices.includes(choiceName) && valueMatchesAny(selections[f.when.label], f.when.choices)) return 0;
  return extra;
}

/**
 * +฿ รวมของกลุ่มนี้ตามที่ลูกค้าเลือกไว้ — กลุ่มปกติ = ตัวที่เลือก · กลุ่ม multi = บวกทุกตัวที่ติ๊ก
 * กลุ่มที่เปิดช่องจำนวน คูณตามจำนวนที่ลูกค้าระบุ (เพิ่มสาย 2 เส้น = +฿ ของสาย × 2)
 */
/**
 * +฿ ของตัวเลือกหนึ่ง ณ จำนวนที่สั่ง — ถึงเกณฑ์ extraFromQty ใช้ extra ปกติ
 * ยังไม่ถึงเกณฑ์ใช้ extraBelow (ไม่ตั้ง = ไม่คิดเพิ่ม เหมือนเดิม)
 */
export function choiceExtraAtQty(
  opt: ProductOption,
  selections: Record<string, string>,
  choiceName: string,
  qty: number
): number {
  const c = opt.choices.find((x) => x.name === choiceName);
  const free = () => {
    const f = opt.freeWhen;
    return !!f && f.choices.includes(choiceName) && valueMatchesAny(selections[f.when.label], f.when.choices);
  };
  // 💰 ตาราง +฿ ตามจำนวน (extraTiers) มาก่อนทุกกติกาขั้นราคา — ตารางเดียวครอบทุกช่วงอยู่แล้ว
  if (c?.extraTiers?.length) return choiceExtraOf(opt, selections, choiceName, qty);
  // ขั้นที่ 3 (ช่วงสั่งน้อยสุด) มาก่อนเสมอ — ตั้งไว้เฉพาะกลุ่มที่ราคาแต่ละแถวไม่เท่ากัน
  const small = Math.floor(opt.extraSmallUpToQty ?? 0);
  if (small > 0 && qty <= small && c?.extraSmall) return free() ? 0 : c.extraSmall;
  if (optionExtraApplies(opt, qty)) return choiceExtraOf(opt, selections, choiceName);
  const below = c?.extraBelow ?? 0;
  if (!below) return 0;
  return free() ? 0 : below;
}

/**
 * ตัวคูณจำนวนของกลุ่มที่ผูกจำนวนไว้กับกลุ่มอื่น (ดู ProductOption.qtyFrom) — ไม่ตั้ง = 1
 * อ่านจำนวนจากข้อความที่เก็บใน selections ของกลุ่มต้นทาง ("F ตะขอสปริง … ×3")
 * และนับเฉพาะตัวเลือกที่กลุ่มนี้ผูกไว้ (showWhen ที่ชี้กลุ่มต้นทางเดียวกัน) — สีของตะขอ F ต้องไม่นับจำนวนของตะขอ C
 */
export function qtyMultiplierOf(opt: ProductOption, selections: Record<string, string>): number {
  const src = opt.qtyFrom;
  if (!src) return 1;
  const raw = selections[src];
  if (!raw) return 1;
  const only = [opt.showWhen, opt.showWhenAlso, ...(opt.showWhenAll ?? []), ...(opt.showWhenAny ?? [])].find(
    (c) => c?.label === src
  )?.choices;
  let n = 0;
  for (const entry of raw.split(MULTI_SEP).map((s) => s.trim()).filter(Boolean)) {
    const p = parseMultiEntry(entry);
    if (only?.length && !only.includes(p.name)) continue;
    n += p.qty;
  }
  return n > 0 ? n : 1;
}

/** +฿ รวมของกลุ่ม ณ จำนวนที่สั่ง (คู่กับ groupExtraOf แต่รู้จำนวน จึงเลือกเรทถูกช่วง) */
export function groupExtraAtQty(opt: ProductOption, selections: Record<string, string>, qty: number): number {
  let free = Math.max(0, Math.floor(opt.freeFirstN ?? 0));
  let sum = 0;
  for (const p of selectedPicks(opt, selections)) {
    const charged = Math.max(0, p.qty - free);
    free = Math.max(0, free - p.qty);
    sum += choiceExtraAtQty(opt, selections, p.name, qty) * charged;
  }
  return sum * qtyMultiplierOf(opt, selections);
}

export function groupExtraOf(opt: ProductOption, selections: Record<string, string>): number {
  // 🎁 โควตา "รวมในราคาแล้ว" ถูกใช้ไปตามลำดับที่ติ๊ก — เหลือเท่าไหร่ค่อยคิดเงินส่วนที่เกิน
  let free = Math.max(0, Math.floor(opt.freeFirstN ?? 0));
  let sum = 0;
  for (const p of selectedPicks(opt, selections)) {
    const charged = Math.max(0, p.qty - free);
    free = Math.max(0, free - p.qty);
    sum += choiceExtraOf(opt, selections, p.name) * charged;
  }
  return sum * qtyMultiplierOf(opt, selections);
}

/**
 * ค่าธรรมเนียมช่วงสั่งน้อยของกลุ่มนี้ ณ ตัวเลือก/จำนวนนี้ (บาทต่อชิ้น · 0 = ไม่คิด)
 * ค่าติดลบ = ลดให้ต่อชิ้นในช่วงนั้น (เช่น ช่วงปลีกเลือกแบบที่ทำง่ายกว่า ลดชิ้นละ 10)
 * เงื่อนไขครบทุกข้อถึงคิด: จำนวนไม่เกินเกณฑ์ · ตัวเลือกที่เลือกไม่อยู่ในรายการยกเว้น · ตรงกับเงื่อนไขกลุ่มอื่น (ถ้าตั้งไว้)
 */
export function smallQtyFeeOf(
  opt: ProductOption,
  selections: Record<string, string>,
  qty: number
): number {
  const f = opt.smallQtyFee;
  if (!f || !f.fee || !Number.isFinite(f.fee) || !(f.upToQty > 0) || qty > f.upToQty) return 0;
  const chosen = selectedNames(opt, selections);
  if (!chosen.length) return 0;
  // กลุ่มติ๊กหลายอย่าง: ติ๊กแต่ตัวที่ยกเว้นไว้ = ไม่คิด · มีตัวที่ไม่ยกเว้นแม้ตัวเดียว = คิดค่าธรรมเนียม
  if (chosen.every((n) => (f.freeChoices ?? []).includes(n))) return 0;
  if (f.when && !valueMatchesAny(selections[f.when.label], f.when.choices)) return 0;
  return f.fee;
}

/**
 * ราคาที่บวกจริงต่อชิ้นของ "ทั้งกลุ่ม" ณ ตัวเลือก/จำนวนนี้
 *
 * กติกาสำคัญ: ค่าธรรมเนียมช่วงสั่งน้อย (ค่าบวก) คิด **แทน** ราคาตัวเลือกในกลุ่มนั้น ไม่ใช่บวกซ้ำ
 * เช่น ช่วงปลีกเลือกตะขอคิดเหมาชิ้นละ 10 → ตะขอ C (+฿3) ก็คิด 10 ไม่ใช่ 13
 * ตัวที่ติ๊กยกเว้น (freeChoices) ไม่โดนค่าธรรมเนียม จึงคิดราคาตัวเลือกตามปกติ
 * ค่าธรรมเนียมติดลบ (= ส่วนลด) ไม่แทนที่ราคาตัวเลือก แต่ลดจากราคารวมของกลุ่ม
 */
export function groupAddOf(opt: ProductOption, selections: Record<string, string>, qty: number): number {
  const fee = smallQtyFeeOf(opt, selections, qty);
  if (fee > 0) {
    if (!isMultiOption(opt)) return fee;
    /**
     * กลุ่มติ๊กหลายอย่างที่ระบุจำนวนได้ — ค่าเหมาคิด "ต่อชิ้นที่ติ๊ก" ไม่ใช่ต่อกลุ่ม
     * (Acrylic Kit สั่งตะขอ 3 ชิ้นต่อชุด ช่วงปลีกก็คิด 3×10 ไม่ใช่ 10)
     * ตัวที่ยกเว้นค่าเหมา (ห่วงแถม) ยังคิดราคาตัวเองตามปกติ ตามกติกาเดียวกับกลุ่มเลือกอย่างเดียว
     */
    const exempt = opt.smallQtyFee?.freeChoices ?? [];
    let sum = 0;
    for (const p of selectedPicks(opt, selections)) {
      sum += (exempt.includes(p.name) ? choiceExtraOf(opt, selections, p.name) : fee) * p.qty;
    }
    return sum;
  }
  // กลุ่มที่คิดต่อลาย/ต่อแผ่น: +฿ ไม่เข้าราคา/ชิ้น — ไปคิดรวมครั้งเดียวใน designFeeFor
  if (opt.extraPerDesign || opt.sheetFee) return fee;
  // 💰 กลุ่มช่องกรอกที่คิดเงินตามค่าที่กรอก (เช่น เพิ่มขนาดนิ้วละ 15) — ไม่มี choices ให้บวก จึงบวกแยก
  const extra = groupExtraAtQty(opt, selections, qty) + inputFeeOf(opt, selections, qty);
  return extra + fee; // fee ติดลบ = ลดให้
}

/**
 * ป้าย +฿ ที่ควรโชว์ข้างตัวเลือก (0 = ไม่ต้องโชว์)
 *
 * ตัวที่โดนค่าธรรมเนียมเหมาไม่ต้องโชว์ราคา — ในช่วงนั้นทุกตัวราคาเท่ากันหมด
 * ขึ้น "+฿10" ทุกบรรทัดรกเปล่า ๆ · ยอดเหมาบอกไว้ในบรรทัดสรุปใต้กลุ่มแล้ว
 * ส่วนตัวที่ติ๊กยกเว้น (ไม่โดนเหมา) ยังโชว์ราคาตัวเองตามปกติ
 */
export function choiceBadgeOf(
  opt: ProductOption,
  selections: Record<string, string>,
  choiceName: string,
  qty: number,
  product?: Product
): number {
  const view = { ...selections, [opt.label]: choiceName };
  // กลุ่มราคาดึงจากตารางเรท (priceAsDriver) — ป้ายโชว์ราคาช่องจริงของตัวเลือกนั้น ณ จำนวนนี้
  if (opt.priceAsDriver && product) return priceAsDriverExtraOf(product, opt, view, choiceName, qty);
  // กลุ่มติ๊กหลายอย่างก็โดนค่าเหมาเหมือนกัน (คิดต่อชิ้นที่ติ๊ก — ดู groupAddOf)
  // ป้ายราคาตัวเองในช่วงนั้นเป็นเลขที่ไม่ได้คิดจริง (เช่น ติ่งห้อยขึ้น +฿15 แต่ช่วง 1-10 คิด ฿20)
  if (smallQtyFeeOf(opt, view, qty) > 0) return 0;
  // ยังไม่เต็มโควตา "รวมในราคา" = ตัวนี้ยังไม่คิดเงิน อย่าขึ้นป้าย +฿ ให้ลูกค้าเข้าใจผิด
  const free = Math.max(0, Math.floor(opt.freeFirstN ?? 0));
  if (free > 0) {
    const picks = selectedPicks(opt, selections);
    const used = picks.filter((p) => p.name !== choiceName).reduce((n, p) => n + p.qty, 0);
    if (used < free) return 0;
  }
  return choiceExtraAtQty(opt, view, choiceName, qty);
}

export interface ProductImage {
  emoji: string;
  gradient: string;
  label: string;
  /** รูปจริงที่อัปโหลด (data URL) — ถ้ามีจะแสดงแทนอีโมจิ+สีพื้น */
  src?: string;
  /**
   * คลิปวิดีโอ (.mp4) — มีค่า = ช่องนี้ในแกลเลอรีเป็นคลิป กดแล้วเล่นในกรอบรูปเลย
   * src ของช่องนั้นทำหน้าที่เป็น "ภาพปก" ของคลิป (รูปย่อ · การ์ดหน้ารายการ · ตะกร้า ยังใช้ภาพนี้ตามปกติ)
   * ⚠️ อย่าใส่คลิปเป็นรูปแรก — รูปแรกถูกใช้เป็นภาพหน้าปกสินค้าในที่อื่นทั้งเว็บ
   */
  videoSrc?: string;
}

/**
 * ท่อนเนื้อหา "รายละเอียดสินค้า" (body) — หัวข้อ + ข้อความ + รูปประกอบ สลับซ้าย/ขวาได้
 * ขึ้นบรรทัดใหม่ในข้อความได้ และบรรทัดที่ขึ้นต้นด้วย "• " จะแสดงเป็นรายการ
 */
export interface BodySection {
  heading: string;
  text: string;
  /**
   * เนื้อหาแบบจัดรูปแบบ (HTML จากตัวเขียนหลังบ้าน — กรองแท็กอันตรายฝั่งเซิร์ฟเวอร์แล้ว)
   * มีค่า = ใช้แทน text · ไม่มี = ใช้ text แบบเดิม (ขึ้นบรรทัดใหม่ · "• " = รายการ)
   */
  html?: string;
  /** ไม่ใส่ = ท่อนข้อความอย่างเดียว */
  image?: ProductImage;
  /** ตำแหน่งรูป (ค่าเริ่มต้น: left) */
  align?: "left" | "right";
  /**
   * โซนที่ท่อนนี้ไปแสดงในหน้าสินค้า
   * "side" = ช่องข้าง ๆ แผงสั่งซื้อ (คอลัมน์ซ้าย) — ช่วยเติมช่องขาวที่เคยว่าง
   * ไม่ระบุ = ใต้แผงสั่งซื้อ เต็มความกว้าง (ค่าเริ่มต้นเดิม)
   */
  slot?: "side";
}

/**
 * แท็บข้อมูลสินค้า (แบบหน้า pricelist เว็บเดิม) — เช่น รายละเอียดเพิ่มเติม / วิธีสั่งงาน / การรับประกัน
 * text: ขึ้นบรรทัดใหม่ด้วย \n · บรรทัดขึ้นต้น "•" = รายการ · บรรทัดลงท้าย "::" = หัวข้อย่อยตัวหนา
 */
export interface ProductTab {
  title: string;
  text: string;
  /**
   * เนื้อหาแบบจัดรูปแบบ (HTML จากตัวเขียนหลังบ้าน — กรองแล้วฝั่งเซิร์ฟเวอร์)
   * มีค่า = ใช้แทน text · ไม่มี = ใช้ text แบบเดิม (• = รายการ · ::หัวข้อ:: = ตัวหนา)
   */
  html?: string;
  /** รูปประกอบในแท็บ (URL จาก Supabase Storage หรือ base64 ในโหมดเดโม) — เรียงตามลำดับในอาร์เรย์ */
  images?: string[];
  /** วางรูปไว้บนหรือใต้ข้อความ (ไม่ตั้ง = ใต้ข้อความ) */
  imagePos?: "top" | "bottom";
  /** ขนาดรูปในหน้าสินค้า: sm = 3 คอลัมน์ (ค่าเริ่มต้น) · md = 2 คอลัมน์ · lg = เต็มความกว้าง */
  imageSize?: "sm" | "md" | "lg";
  /** จัดวางรูปในแถว: ชิดซ้าย (ค่าเริ่มต้น) · กึ่งกลาง · ชิดขวา */
  imageAlign?: "left" | "center" | "right";
}

/**
 * กฎเงื่อนไขระหว่างตัวเลือก: เมื่อลูกค้าเลือก `when` แล้ว
 * กลุ่ม `limit.label` จะเหลือเฉพาะตัวเลือกใน `limit.allow`
 * เช่น เลือกกระดาษ Canvas → เคลือบ เหลือแค่ "ไม่เคลือบ"
 * ถ้ากลุ่มไหนเหลือตัวเลือกเดียว หน้าเว็บจะแสดงเป็นข้อความล็อกไว้ ลูกค้าสั่งผิดไม่ได้
 */
export interface OptionRule {
  /**
   * เงื่อนไข: กลุ่ม + ตัวเลือกที่ทำให้กฎทำงาน
   * choices (ใหม่) = หลายตัวเลือกในกฎเดียว เช่น สีพิเศษ 44 สี → ชนิดพิเศษ (กฎเดียวจบ)
   * choice (เดิม) = ตัวเดียว — ยังอ่านได้เพื่อข้อมูลเก่า
   */
  when: { label: string; choice: string; choices?: string[] };
  limit: { label: string; allow: string[] };
}

/** ตัวเลือกที่เลือกอยู่เข้าเงื่อนไขของกฎนี้ไหม (รองรับทั้งแบบตัวเดียวและหลายตัว) */
export function ruleWhenMatches(rule: OptionRule, selections: Record<string, string>): boolean {
  const cur = selections[rule.when.label];
  if (!cur) return false;
  return valueMatchesAny(cur, rule.when.choices?.length ? rule.when.choices : [rule.when.choice]);
}

/** ช่วงจำนวน (tier) สำหรับราคาขั้นบันได */
export interface PriceTier {
  /** จำนวนสูงสุดของช่วงนี้ (null = ช่วงสุดท้าย ขึ้นไปไม่จำกัด) */
  upTo: number | null;
  label: string;
}

/**
 * ตารางราคาแบบขั้นบันได (rate card): ราคา/หน่วย ขึ้นกับ (คอลัมน์ตัวเลือก × ช่วงจำนวน)
 * ยิ่งสั่งเยอะ ราคา/หน่วยยิ่งถูก · ถ้าสินค้าไม่มี pricing จะใช้ราคาเดียว (price + option.extra)
 */
export interface PriceMatrix {
  /** หน่วยนับ เช่น "แผ่น A3", "ชิ้น" */
  unit: string;
  /** กลุ่มตัวเลือกที่กำหนดคอลัมน์ (ค่าที่เลือกในกลุ่มเหล่านี้ = key ของคอลัมน์) */
  driverLabels: string[];
  tiers: PriceTier[];
  /** key = ค่าตัวเลือกของ driverLabels ต่อด้วย "│" → ราคา/หน่วยเรียงตาม tiers */
  cells: Record<string, number[]>;
  /**
   * 🏷️ ชื่อหัวคอลัมน์ราคา — ใช้กับตารางคอลัมน์เดียว (driverLabels ว่าง) ที่ปกติหัวจะว่างเปล่า
   * เช่น พวงกุญแจเขย่า: "กรอบเขย่า" ให้รู้ว่าราคาในตารางคือค่ากรอบ (ตัวน้อยอยู่คอลัมน์ noteCol)
   * ตารางที่มีแกนตัวเลือกไม่ใช้ค่านี้ (หัวคอลัมน์เป็นชื่อตัวเลือกอยู่แล้ว)
   */
  colLabel?: string;
  /**
   * 📝 คอลัมน์หมายเหตุต่อช่วงจำนวน — ต่อท้ายขวาสุดของตารางราคาหน้าสินค้า
   * ใช้บอกค่าบริการที่แปรตามช่วงจำนวนแต่ไม่ใช่ราคาหลัก เช่น พวงกุญแจเขย่า:
   * ตัวน้อยเขย่า "+ ตัวละ 20 บาท" ช่วงปลีก / "+ ตัวละ 15 บาท" ช่วงส่ง (ตรงกับตารางเว็บ pricelists)
   * values เรียงตาม tiers (ช่องไหนไม่มีปล่อย "" ได้) — ข้อความบอกทางเฉย ๆ ไม่มีผลกับการคิดเงิน
   */
  noteCol?: { label: string; values: string[] };
}

/** 1 ขั้นของค่าส่งตามจำนวน — สั่งตั้งแต่ minQty ชิ้น → ค่าส่ง price บาท */
export interface ShipTier {
  minQty: number;
  price: number;
}

/**
 * ค่าส่งเฉพาะบางตัวเลือก — ของบางอย่าง "ขนาด" มีผลกับกล่อง/น้ำหนัก
 * เช่น สแตนดี้ A5 ส่งไปรษณีย์ได้ แต่ A2 ต้องกล่องใหญ่/ส่งแมส
 * เข้าเงื่อนไขข้อไหน = ใช้ค่าของข้อนั้นแทนค่ากลางของสินค้า (เข้าหลายข้อ = ใช้ข้อแรก)
 */
export interface ShipOptionRule {
  /** ชื่อกลุ่มตัวเลือก เช่น "ขนาด" */
  label: string;
  /** ค่าตัวเลือกที่เข้าเงื่อนไขนี้ (เลือกได้หลายค่า) */
  choices: string[];
  /** วิธีจัดส่งขั้นต่ำเมื่อเลือกตัวเลือกนี้ (ไม่ตั้ง = ใช้ shippingId ของสินค้า) */
  shippingId?: string;
  /** ตารางค่าส่งตามจำนวนชิ้นเฉพาะตัวเลือกนี้ (ไม่ตั้ง = ใช้ตารางกลางของสินค้า) */
  shipTiers?: ShipTier[];
  /** เกินขั้นสุดท้าย คิดเพิ่มชิ้นละกี่บาท (ใช้คู่กับ shipTiers ของข้อนี้) */
  shipTierExtra?: number;
  /** เกินขั้นสุดท้าย เปลี่ยนเป็นวิธีส่งนี้ (ใช้คู่กับ shipTiers ของข้อนี้) */
  shipTierMethodId?: string;
}

/**
 * เรทราคา 1 แบบของสินค้า — สินค้าบางตัวมีหลายเรท (เช่น พิน: เรทคละดีเทล / เรทไม่คละดีเทล)
 * แต่ละเรทมีตารางขั้นบันไดของตัวเอง (ช่วงจำนวนคนละชุดได้) + เงื่อนไขการสั่ง
 */
export interface PriceRate {
  id: string;
  /** ชื่อเรทที่ลูกค้าเห็น เช่น "เรทที่ 1 แบบคละดีเทล" */
  label: string;
  /** คำอธิบายสั้น ๆ ใต้ชื่อ เช่น "อะคริลิคใส / ขาวขุ่น C-02 (เงา 2 ด้าน)" */
  desc?: string;
  /** ยอดสั่งรวมขั้นต่ำของเรทนี้ เช่น เรท 2 ต้องสั่ง 50 ชิ้นขึ้นไป */
  minQty?: number;
  /**
   * 📦 ขั้นต่ำ (minQty) นับที่ไหน — ไม่ตั้ง = "line" (นับรายบรรทัดตามเดิม)
   *
   * "lot" = นับ "ยอดรวมทั้งล็อตผลิต" ในตะกร้า (บรรทัดสินค้าเดียวกัน เรทเดียวกัน และค่าของกลุ่มใน
   * lotKeyOptions ตรงกัน) แทนที่จะบังคับทีละบรรทัด — ใช้กับสินค้าที่ขั้นต่ำเป็นของ "รอบผลิต"
   * ไม่ใช่ของสเปคใดสเปคหนึ่ง เช่น สติ๊กเกอร์ UV ขั้นต่ำ 3 แผ่น A3 ต่อเนื้อสติ๊กเกอร์ 1 ชนิด
   * แต่ 3 แผ่นนั้นคละไดคัท 50%/100% และคละขนาดกันได้ (= คนละบรรทัดในตะกร้า บรรทัดละ 1 แผ่น)
   *
   * ผลที่ตามมา: หน้าสินค้าไม่ล็อกปุ่มสั่งอีก (กดเพิ่มทีละแผ่นสะสมได้) — ประตูขั้นต่ำย้ายไป
   * ตะกร้า/หน้าชำระเงิน/เซิร์ฟเวอร์ ผ่าน lotShortfalls()
   */
  minQtyScope?: "line" | "lot";
  /** คละลายขั้นต่ำลายละกี่ชิ้น เช่น 25 → สั่ง 50 คละได้ 2 ลาย */
  minPerDesign?: number;
  /** คละลายเกินโควตาได้ โดยคิดเพิ่มลายละ (บาท) — ไม่ตั้ง = คละเกินโควตาไม่ได้ */
  extraDesignFee?: number;
  /**
   * 💰 คละไม่ถึงขั้นต่ำต่อลายได้ โดยคิด "ส่วนต่าง" จากชิ้นที่อยู่ในลายที่ไม่ถึง minPerDesign ชิ้นละ N บาท
   * (กติกาเคสมือถือ 26 ส.ค. 69: 11 ชิ้นขึ้นไปขั้นต่ำลายละ 3 — ลายไหนมีแค่ 2 ชิ้น = 2 × ฿10 = ฿20)
   * ตั้งค่านี้แล้ว: ราคา/ชิ้นคิดเรทตามยอดรวมตามปกติ (tierByDesign ไม่ลดเรทซ้ำ — จ่ายค่าคละแทน)
   * และช่องจำนวนลายไม่ตัน · ช่วงคละอิสระ (freeMixBelowQty) ไม่คิด · ระบบกระจายชิ้นให้ลูกค้าแบบประหยัดสุดเสมอ
   */
  underMinPieceFee?: number;
  /**
   * สั่งต่ำกว่ากี่ชิ้น = คละลายได้อิสระ (ไม่ติดขั้นต่ำต่อลาย ไม่คิดค่าคละเพิ่ม)
   * เช่น ราคาปลีก 1-10 ชิ้น คละได้ทุกชิ้น · ตั้ง 11 = ต่ำกว่า 11 อิสระ ถึง 11 ค่อยใช้ minPerDesign
   */
  freeMixBelowQty?: number;
  /**
   * 🖼 ภาพประกอบของเรทนี้ (URL) — สินค้าที่ใช้เรทเป็น "แบบสินค้า" (เช่น สายคล้องหลายแบบ)
   * แสดงเป็นภาพย่อบนการ์ดเลือกเรท และกดเลือกแล้วแกลเลอรีสลับไปภาพนี้ (ถ้าอยู่ในแกลเลอรี)
   */
  imageSrc?: string;
  /**
   * 🎨 กติกาคละลายเฉพาะเรทนี้ — ทับ mixRule ระดับสินค้า (ดู mixRuleFor)
   * ใช้กับสินค้าที่เรทเป็น "แบบสินค้า" แล้วค่าคละต่างกัน เช่น แม่เหล็กติดตู้เย็น
   * ไดคัท 100% ลายละ 5 · SET-KIT ลายละ 20 (ตรรกะเดียวกับสติ๊กเกอร์ไดคัท 100%/50%)
   */
  mixRule?: MixRule;
  pricing: PriceMatrix;
}

/**
 * กติกาคละลายแบบ "คิดค่าคละเป็นเงินต่อหน่วย"
 *
 * ต่างจาก minPerDesign/extraDesignFee ของ PriceRate ตรงที่:
 *   - ของ PriceRate = โควตาลายต่อออเดอร์ คละเกินแล้วราคาตกไปเรทต่อลาย
 *   - ของตัวนี้ = ราคาเรทไม่เปลี่ยน แต่บวกค่าคละเป็นเงินตรง ๆ ต่อหน่วย
 * ใช้กับสินค้าอย่างสติกเกอร์ที่คละลายแล้วต้นทุนเพิ่มเป็นค่าจัดอาร์ต ไม่ใช่ค่าผลิตต่อชิ้น
 *
 * ตัวอย่าง Super Sticker: baseFee 20 · includedDesigns 4 · extraFee 5 · onePerUnitFromQty 11
 *   คละ 1 ลาย = 0 · 2-4 ลาย = 20 บาท/แผ่น · 6 ลาย = 20 + 2×5 = 30 บาท/แผ่น
 *   สั่ง 11 แผ่นขึ้นไป = คละได้ไม่เกินจำนวนแผ่น (ขั้นต่ำ 1 ลาย/แผ่น)
 */
export interface MixTier {
  /** ใช้กติกาแถวนี้เมื่อสั่งตั้งแต่จำนวนนี้ขึ้นไป (แถวแรกควรเป็น 1) */
  fromQty: number;
  /** คละตั้งแต่ 2 ลายขึ้นไป คิดเหมาต่อหน่วยเท่านี้ (0 = ช่วงนี้คละฟรี) */
  baseFee: number;
  /** จำนวนลายที่รวมอยู่ในค่าเหมาแล้ว (เกินกว่านี้คิด extraFee ต่อลาย) */
  includedDesigns: number;
  /** ลายที่เกินโควตา คิดเพิ่มต่อหน่วย ลายละเท่านี้ */
  extraFee: number;
  /** ช่วงนี้ต้องมีอย่างน้อย 1 ลาย/หน่วย → คละได้ไม่เกินจำนวนที่สั่ง */
  onePerUnit?: boolean;
}

export interface MixRule {
  /** คละตั้งแต่ 2 ลายขึ้นไป คิดเหมาต่อหน่วยเท่านี้ */
  baseFee: number;
  /** จำนวนลายที่รวมอยู่ในค่าเหมาแล้ว (เกินกว่านี้คิด extraFee ต่อลาย) */
  includedDesigns: number;
  /** ลายที่เกินโควตา คิดเพิ่มต่อหน่วย ลายละเท่านี้ */
  extraFee: number;
  /** สั่งตั้งแต่จำนวนนี้ขึ้นไป ต้องมีอย่างน้อย 1 ลาย/หน่วย → คละได้ไม่เกินจำนวนที่สั่ง */
  onePerUnitFromQty?: number;
  /**
   * ตารางค่าคละแยกตามช่วงจำนวน — มีแถวเมื่อไหร่ ใช้แทน 4 ค่าด้านบนทั้งหมด
   * ทำให้ตั้งกติกาต่างกันได้ในแต่ละช่วง เช่น 1-10 คิด 20 บาท · 11-50 คิด 15 บาท · 51+ ฟรี
   * (4 ค่าด้านบนยังอยู่เพื่อให้สินค้าที่ตั้งไว้แบบเดิมทำงานต่อได้)
   */
  tiers?: MixTier[];
}

/** กติกาที่มีผล ณ จำนวนนี้ — เลือกแถวที่ fromQty สูงสุดที่ยังไม่เกินจำนวนที่สั่ง */
export function mixTierFor(rule: MixRule, qty: number): MixTier {
  const rows = (rule.tiers ?? []).filter((t) => Number.isFinite(t.fromQty)).sort((a, b) => a.fromQty - b.fromQty);
  if (rows.length) {
    // ต่ำกว่าแถวแรก = ใช้แถวแรก (กันกรณีแอดมินเริ่มตารางที่ 5 แล้วลูกค้าสั่ง 2)
    let hit = rows[0];
    for (const r of rows) if (qty >= r.fromQty) hit = r;
    return hit;
  }
  // ไม่มีตาราง → ใช้ค่าเดี่ยวแบบเดิม
  return {
    fromQty: 1,
    baseFee: rule.baseFee,
    includedDesigns: rule.includedDesigns,
    extraFee: rule.extraFee,
    onePerUnit: !!rule.onePerUnitFromQty && qty >= rule.onePerUnitFromQty,
  };
}

/** ค่าคละของ "หนึ่งหน่วย" ที่มี n ลายอยู่บนหน่วยนั้น */
function feeOfUnit(t: MixTier, n: number): number {
  if (n <= 1) return 0; // หน่วยที่มีลายเดียว = ไม่ได้คละ ไม่คิด
  const extra = Math.max(0, n - Math.max(1, t.includedDesigns));
  return Math.max(0, t.baseFee) + extra * Math.max(0, t.extraFee);
}

/**
 * เฉลี่ยลายลงแต่ละหน่วยให้ใกล้เคียงที่สุด — คืน [จำนวนลายของแต่ละหน่วย]
 * เช่น 9 ลาย 2 แผ่น → [5,4] · 12 ลาย 11 แผ่น → [2,1,1,…]
 * (ตรงกับที่แอดมินคิดมือ: หารไม่ลงตัวก็แยกคิดเป็นคนละรายการ)
 */
export function spreadDesigns(designs: number, qty: number, cap = Infinity): number[] {
  if (qty <= 0) return [];
  // ลายน้อยกว่าหรือเท่าหน่วยที่สั่ง = ลายซ้ำกันข้ามหน่วย ทุกหน่วยมีลายเดียว (ไม่มีหน่วยไหน "คละ")
  // เช่น 10 แผ่น 4 ลาย → แผ่นละ 1 ลาย ไม่ใช่ 4 แผ่นมีลาย + 6 แผ่นว่าง
  if (designs <= qty) return Array.from({ length: qty }, () => 1);

  const c = Math.max(1, cap);
  if (designs <= c * qty) {
    /*
      ยังใส่ได้ในโควตา → "เติมให้เต็มโควตาต่อหน่วยก่อน แล้วค่อยขึ้นหน่วยใหม่"
      ไม่ใช่เฉลี่ยเท่า ๆ กัน เพราะเฉลี่ยแล้วจะไปโดนค่าคละหลายหน่วยโดยไม่จำเป็น
      เช่น 2 แผ่น 5 ลาย: เฉลี่ย [3,2] = คละ 2 แผ่น (40 บาท) · เติมเต็ม [4,1] = คละแผ่นเดียว (20 บาท)
      หน่วยที่เหลือได้ลายละ 1 (ลายซ้ำจากที่มีอยู่) จึงไม่ถือว่าคละ
    */
    const full = Math.floor(designs / c);
    const rest = designs - full * c;
    const out = Array.from({ length: full }, () => c);
    if (rest > 0) out.push(rest);
    while (out.length < qty) out.push(1);
    return out;
  }

  // ลายเกินโควตารวมแล้ว → เฉลี่ยส่วนที่เกินให้ทุกหน่วยเท่า ๆ กัน (เช่น 2 แผ่น 9 ลาย → [5,4])
  const base = Math.floor(designs / qty);
  const remainder = designs % qty;
  return Array.from({ length: qty }, (_, i) => (i < remainder ? base + 1 : base));
}

/**
 * 📊 การกระจายลายที่ "ถูกสุดสำหรับลูกค้า" ตามกติกาของเรทนั้น
 *
 * เทียบ 2 วิธีแล้วเอาที่รวมถูกกว่า:
 *   - เติมเต็มโควตาต่อหน่วยก่อน (spreadDesigns) — ประหยัดเมื่อค่าเหมาคลุมหลายลาย
 *     เช่น Super Sticker เหมา 20 คลุม 4 ลาย: 3 แผ่น 4 ลาย → [4,1,1] คละแผ่นเดียว = 20
 *   - เฉลี่ยให้ใช้ทุกหน่วย — ประหยัดเมื่อกติกาเชิงเส้นลายละเท่า ๆ กัน
 *     เช่น ไดคัท 50% ลายละ 20 (20/2/20): 3 แผ่น 4 ลาย → [2,1,1] = 20 (เติมเต็มจะได้ [2,2,1] = 40 แพงเกินจริง)
 * เสมอกัน = ใช้วิธีเติมเต็มแบบเดิม (หน้าจอไม่เปลี่ยนหน้าตากับสินค้าเก่า)
 * ⚠️ หน้าสินค้าที่กางรายแผ่นให้ลูกค้าดูต้องใช้ตัวนี้ตัวเดียวกับที่คิดเงิน — ไม่งั้นยอดกางไม่ตรงยอดเก็บ
 */
export function mixSpread(rule: MixRule, designs: number, qty: number): number[] {
  const t = mixTierFor(rule, qty);
  const fill = spreadDesigns(designs, qty, t.includedDesigns);
  if (designs <= qty || qty <= 0) return fill; // ลายละหน่วยขึ้นไป = ไม่ได้คละ ไม่มีอะไรให้เลือก
  const base = Math.floor(designs / qty);
  const rem = designs % qty;
  const even = Array.from({ length: qty }, (_, i) => (i < rem ? base + 1 : base));
  const feeOf = (arr: number[]) => arr.reduce((s, n) => s + feeOfUnit(t, n), 0);
  return feeOf(even) < feeOf(fill) ? even : fill;
}

/**
 * ค่าคละลายทั้งรายการ
 *
 * ⚠️ คิดจาก "ลายต่อหน่วย" ไม่ใช่ "ลายทั้งออเดอร์" — จุดนี้เคยทำผิดมาก่อน
 *    สั่ง 2 แผ่น 2 ลาย = แผ่นละ 1 ลาย → ไม่ได้คละ ไม่คิดเงิน
 *    สั่ง 2 แผ่น 9 ลาย = [5,4] → 25 + 20 = 45 (ไม่ใช่คิดจากเลข 9 ตรง ๆ)
 */
export function mixFeeTotal(rule: MixRule, designs: number, qty: number): number {
  if (designs <= 1 || qty <= 0) return 0;
  const t = mixTierFor(rule, qty);
  return mixSpread(rule, designs, qty).reduce((sum, n) => sum + feeOfUnit(t, n), 0);
}

/**
 * ค่าคละของ "หนึ่งหน่วยที่มี n ลายอยู่บนนั้น" — ใช้กางรายละเอียดให้ลูกค้าเห็นทีละกลุ่ม
 * ⚠️ อย่าสับกับ mixFeeTotal: ตัวนี้ n = ลายบนหน่วยนั้นแล้ว ไม่ต้องเฉลี่ยซ้ำ
 */
export function mixUnitFee(rule: MixRule, designsOnUnit: number, qty: number): number {
  return feeOfUnit(mixTierFor(rule, qty), designsOnUnit);
}

/** ค่าคละของหน่วยที่มีลายมากที่สุด — ไว้โชว์ว่า "แผ่นที่แพงสุดแผ่นละเท่าไหร่" */
export function mixFeePerUnit(rule: MixRule, designs: number, qty = 1): number {
  if (designs <= 1 || qty <= 0) return 0;
  const t = mixTierFor(rule, qty);
  return feeOfUnit(t, Math.max(...mixSpread(rule, designs, qty)));
}

/**
 * เพดานจำนวนลายที่กติกานี้ยอมให้ — ไม่มีเพดาน = Infinity
 * (ช่วงที่ไม่ได้บังคับ 1 ลาย/หน่วย คละได้ไม่จำกัด เพราะหลายลายอยู่บนหน่วยเดียวกันได้)
 */
export function mixMaxDesigns(rule: MixRule | undefined, qty: number): number {
  if (!rule) return Infinity;
  return mixTierFor(rule, qty).onePerUnit ? qty : Infinity;
}

/**
 * กติกาคละลายที่มีผลจริงตามตัวเลือกที่ลูกค้าเลือก
 * ตัวเลือกที่ตั้ง mixRule ของตัวเอง (เช่น "ไดคัท 50%" ค่าคละลายละ 20) ทับกติการะดับสินค้า
 * ถัดมา = เรทราคาที่เลือก (เรทเป็น "แบบสินค้า" ตั้งค่าคละของตัวเองได้ เช่น SET-KIT ลายละ 20)
 * ไม่มีใครตั้ง = ใช้ mixRule ระดับสินค้าตามเดิม · เจอหลายกลุ่มตั้งพร้อมกัน ใช้กลุ่มแรกที่เจอ
 */
export function mixRuleFor(product: Product, selections: Record<string, string>): MixRule | undefined {
  for (const o of product.options ?? []) {
    if (!optionActive(o, selections)) continue;
    const picked = selections[o.label];
    if (!picked) continue;
    const c = o.choices.find((x) => x.name === picked);
    if (c?.mixRule) return c.mixRule;
  }
  const rate = activeRate(product, selections);
  if (rate?.mixRule) return rate.mixRule;
  return product.mixRule;
}

/**
 * จำนวนชิ้นที่ได้ต่อ 1 หน่วยสั่ง ตามตัวเลือกที่ลูกค้าเลือกอยู่ (ไม่มีตัวไหนตั้งไว้ = undefined)
 * มีหลายกลุ่มตั้งไว้ → ใช้ตัวที่น้อยที่สุด (เข้มที่สุดชนะ)
 */
export function perUnitCapacity(product: Product, selections: Record<string, string>): number | undefined {
  let cap: number | undefined;
  for (const o of product.options ?? []) {
    const picked = selections[o.label];
    if (!picked) continue;
    const c = o.choices.find((x) => x.name === picked);
    if (c?.perUnit && c.perUnit > 0) cap = cap === undefined ? c.perUnit : Math.min(cap, c.perUnit);
  }
  /*
   * 📐 งานไดคัท — เพดานลายมาจากจำนวนชิ้นที่ตัดได้จริงต่อแผ่น (ต้องติ๊ก capDesigns ที่กลุ่มนั้น
   * ไม่งั้นตัวเลขต่อแผ่นเป็นแค่ข้อมูลบอกทางเหมือนเดิม) · อ่านได้ทั้งขนาดตายตัวและขนาดที่กรอกเอง
   *
   * ⚠️ เช็ค optionActive ด้วย ต่างจากลูป perUnit ด้านบน — กลุ่มขนาดพวกนี้โผล่ตามการตัดที่เลือก
   * และ resolveSelections ใส่ค่าเริ่มต้นให้กลุ่มที่ซ่อนอยู่ด้วย ไม่เช็คแล้วจะโดนค่าค้างของกลุ่ม
   * ที่ไม่ได้ใช้กดเพดานไว้ (เลือกไดคัทตามทรง 3×3 ซม. แต่ติดเพดาน 2 ลายของ A4 ที่ค้างอยู่)
   *
   * ยังกรอกไม่ครบ = ข้ามไป ปล่อยให้กติกาอื่นคุมแทน · ใหญ่เกินแผ่น (0 ชิ้น) ก็ข้าม
   * ไม่งั้นเพดานเหลือ 0 แล้วช่องจำนวนลายตันจนกดอะไรไม่ได้ (หน้าสินค้าเตือนเรื่องใหญ่เกินแผ่นอยู่แล้ว)
   */
  for (const o of product.options ?? []) {
    if (!o.capDesigns || !optionActive(o, selections)) continue;
    const picked = selections[o.label];
    const fixed = picked ? o.choices.find((x) => x.name === picked)?.piecesPerUnit : undefined;
    const n = fixed && fixed > 0 ? fixed : sheetYieldCount(product, o, selections);
    if (n != null && n > 0) cap = cap === undefined ? n : Math.min(cap, n);
  }
  return cap;
}

/** ช่วงจำนวนนี้คละลายอิสระไหม (ช่วงราคาปลีก) */
export function isFreeMix(rate: PriceRate, qty: number): boolean {
  return !!rate.freeMixBelowQty && qty < rate.freeMixBelowQty;
}

/**
 * จำนวนลายสูงสุดที่คละได้ ณ จำนวนนี้ (รวมส่วนที่จ่ายเพิ่มได้)
 *
 * ⚠️ perUnit = ชิ้นที่ได้ต่อ 1 หน่วยสั่ง (สินค้าขายเป็นเซ็ต เช่น Jibbitz เซ็ตละ 5 ชิ้น)
 * เพดานจริงคือ "จำนวนชิ้น" ไม่ใช่จำนวนหน่วย เพราะคละ 1 ลายใช้อย่างน้อย 1 ชิ้น
 * — สั่ง 1 เซ็ต (5 ชิ้น) ต้องคละได้ 5 ลาย ไม่ใช่ 1 ลาย
 * สินค้าขายเป็นชิ้น (perUnit 1) ผลลัพธ์เท่าเดิมทุกประการ
 */
export function maxDesignsFor(rate: PriceRate, qty: number, perUnit = 1): number {
  const pieces = qty * Math.max(1, perUnit);
  if (!rate.minPerDesign || rate.minPerDesign <= 0) return pieces;
  if (isFreeMix(rate, qty)) return pieces;
  const included = Math.max(1, Math.floor(qty / rate.minPerDesign));
  // เรทที่เปิดให้จ่ายเพิ่มแทนการบล็อก (คละเกินลายละ N / คละไม่ถึงขั้นต่ำชิ้นละ N) → คละได้ถึงจำนวนชิ้น
  return rate.extraDesignFee || rate.underMinPieceFee ? pieces : included;
}

/**
 * 🔢 จำนวนชิ้นที่ "อยู่ในลายที่ไม่ถึงขั้นต่ำต่อลาย" — ฐานคิดค่าคละของ underMinPieceFee
 *
 * ระบบรู้แค่ (จำนวนรวม, จำนวนลาย) ไม่รู้ว่าลูกค้าแบ่งลายละกี่ชิ้น จึงกระจายให้แบบประหยัดสุด:
 * อัดลายให้เต็มขั้นต่ำ (minPerDesign) ให้ได้มากลายที่สุด ที่เหลือหารกันในลายที่ไม่เต็ม
 * เช่น 11 ชิ้น 4 ลาย ขั้นต่ำลายละ 3 → 3+3+3+2 → ชิ้นที่ไม่ถึงขั้นต่ำ = 2
 */
export function underMinPieces(qty: number, designs: number, minPerDesign: number): number {
  const m = Math.max(1, Math.floor(minPerDesign));
  const d = Math.min(Math.max(1, designs), Math.max(1, qty)); // ลาย ≤ ชิ้น (1 ลายใช้อย่างน้อย 1 ชิ้น)
  if (m <= 1 || qty >= m * d) return 0; // ทุกลายถึงขั้นต่ำได้หมด
  // ลายเต็มได้มากสุด k ลาย โดยลายที่เหลือ (d-k) ยังมีอย่างน้อยลายละ 1 ชิ้น: mk + (d-k) ≤ qty
  const k = Math.max(0, Math.floor((qty - d) / (m - 1)));
  return Math.max(0, qty - m * k);
}

/**
 * 💰 ค่าคละ "ไม่ถึงขั้นต่ำต่อลาย" ของเรทที่ตั้ง underMinPieceFee (บาท ทั้งรายการ)
 * qty/designs = ของบรรทัดนั้น · tierQty = ยอดที่ใช้เช็คช่วงคละอิสระ (บรรทัดเดี่ยว = qty เดียวกัน
 * แต่ตะกร้าที่รวมล็อตต้องส่งยอดรวมล็อตมา — บรรทัด 2 ชิ้นในล็อต 11 ชิ้นถือว่าพ้นช่วงปลีกแล้ว)
 */
export function underMinFeeFor(r: PriceRate | undefined, qty: number, designs: number, tierQty = qty): number {
  if (!r?.underMinPieceFee || !r.minPerDesign) return 0;
  if (isFreeMix(r, tierQty)) return 0; // ช่วงราคาปลีกคละอิสระ ไม่คิด
  return r.underMinPieceFee * underMinPieces(qty, designs, r.minPerDesign);
}

/** ชื่อกลุ่มที่ใช้เก็บเรทที่ลูกค้าเลือกไว้ใน selections (แสดงในตะกร้า/ออเดอร์เหมือนตัวเลือกทั่วไป) */
export const RATE_LABEL = "เรทราคา";
/** ชื่อกลุ่มที่เก็บจำนวนลายที่ลูกค้าจะคละ เช่น "3 ลาย" */
export const DESIGN_LABEL = "จำนวนลาย";

/**
 * จำนวนลายที่ "รวมในราคา" ตามจำนวนที่สั่ง = ⌊จำนวน ÷ ขั้นต่ำต่อลาย⌋ (อย่างน้อย 1)
 * perUnit = ชิ้นต่อ 1 หน่วยสั่ง (ดู maxDesignsFor) — ช่วงคละอิสระต้องนับเป็นชิ้น
 * ไม่งั้นสินค้าเซ็ตจะโดนเก็บค่าคละตั้งแต่ช่วงปลีกที่ควรคละฟรี
 */
export function includedDesigns(rate: PriceRate, qty: number, perUnit = 1): number {
  if (!rate.minPerDesign || rate.minPerDesign <= 0) return 0;
  // ช่วงปลีกคละอิสระ — ทุกชิ้นเป็นคนละลายได้ ไม่คิดเพิ่ม
  if (isFreeMix(rate, qty)) return qty * Math.max(1, perUnit);
  return Math.max(1, Math.floor(qty / rate.minPerDesign));
}

/** จำนวนลายที่เลือกไว้ใน selections — "3 ลาย" → 3 (ไม่ได้เลือก = 1 ลาย) */
export function designCountOf(selections: Record<string, string>): number {
  const n = parseInt(String(selections[DESIGN_LABEL] ?? ""), 10);
  return Number.isFinite(n) && n > 0 ? n : 1;
}

/**
 * 🧮 จำนวนชิ้นต่อ 1 หน่วยขาย ตามที่ลูกค้าเลือกในกลุ่ม pieceCountLabel — เลขหน้าชื่อตัวเลือก ("3 ชิ้น" → 3)
 * สินค้าไม่ได้ตั้ง / ยังไม่ได้เลือก = 1 (1 หน่วย = 1 ชิ้น เหมือนเดิม)
 */
export function unitPieceCountOf(product: Product, selections: Record<string, string>): number {
  if (!product.pieceCountLabel) return 1;
  const n = parseInt(String(selections[product.pieceCountLabel] ?? ""), 10);
  return Number.isFinite(n) && n > 0 ? n : 1;
}

/**
 * จำนวนที่ใช้ "หาเรทราคา" ในตารางขั้นบันได
 * สินค้าที่ตั้ง tierByDesign = คิดเรทตามจำนวนชิ้นต่อลาย ⌊จำนวน ÷ ลาย⌋ (อย่างน้อย 1)
 * เช่น เคส 11 ชิ้นคละ 11 ลาย → 1 ชิ้น/ลาย → เรทราคาปลีก (ไม่ใช่เรท 11 ชิ้น)
 * ส่วน "ราคารวม" ยังคูณจำนวนชิ้นจริงทั้งหมดตามเดิม
 *
 * เรทที่ตั้ง "คละลายขั้นต่ำลายละ N" ไว้:
 * - คละอยู่ในโควตา (เช่น 12 ชิ้นลายละ 3 คละ 4 ลาย) = ทำตามเงื่อนไข → คิดเรทตามยอดรวมเต็ม ๆ
 * - คละ "เกิน" โควตา (เช่น 11 ชิ้นคละ 4 ลาย) = ไม่บล็อก แต่ราคาตกไปคิดตามชิ้นต่อลาย
 *   (ลูกค้าอยากคละเยอะยอมจ่ายราคาปลีกได้เอง — ระบบปรับเรทให้เห็นตรง ๆ ไม่ใช่แค่ป้ายเตือน)
 */
export function tierQtyFor(product: Product, selections: Record<string, string>, qty: number): number {
  // สินค้าหลายชิ้นต่อหน่วย (pieceCountLabel) — ช่วงราคานับจาก "จำนวนชิ้นรวม" ไม่ใช่จำนวนหน่วย
  // (เงื่อนไขที่อิงช่วงราคา เช่น extraFromQty/ค่าเหมาช่วงปลีก ใช้เลขเดียวกัน จะได้ไม่คิดซ้ำกับราคาช่วงส่ง)
  qty = qty * unitPieceCountOf(product, selections);
  // สินค้าที่คิดค่าคละเป็นเงินต่อหน่วยแล้ว (mixRule — ระดับสินค้าหรือระดับตัวเลือก) ห้ามลดเรทซ้ำอีก
  // ไม่งั้นลูกค้าโดนสองเด้ง: จ่ายค่าคละ + ราคาตกไปเรทปลีก
  if (mixRuleFor(product, selections)) return qty;
  if (!product.tierByDesign) return qty;
  const r = activeRate(product, selections);
  const d = designCountOf(selections);
  if (r?.minPerDesign) {
    if (isFreeMix(r, qty) || d <= includedDesigns(r, qty, perUnitCapacity(product, selections) ?? 1)) return qty;
    // เรทที่คิดค่าคละไม่ถึงขั้นต่ำเป็นเงินแล้ว (underMinPieceFee) — ห้ามลดเรทซ้ำ ไม่งั้นโดนสองเด้ง
    if (r.underMinPieceFee) return qty;
    return Math.max(1, Math.floor(qty / d));
  }
  return Math.max(1, Math.floor(qty / d));
}

/**
 * ค่าคละลายเกินโควตา (บาท ทั้งรายการ) — ลูกค้าเลือกจำนวนลายมากกว่าที่รวมในราคา
 * และเรทนั้นเปิดให้คละเกินได้ (extraDesignFee) → ส่วนเกินคิดลายละ extraDesignFee
 */
/** 💰 ค่าเพิ่ม "ต่อลาย" จากกลุ่มตัวเลือก (เช่น สีไหมเกิน 3 สี สีละ 10) × จำนวนลายที่คละ */
export function perDesignExtraOf(product: Product, selections: Record<string, string>): number {
  let sum = 0;
  for (const opt of product.options ?? []) {
    if (!opt.extraPerDesign || !optionActive(opt, selections)) continue;
    sum += groupExtraOf(opt, selections); // หักโควตาฟรี (freeFirstN) ให้แล้ว
  }
  return sum * designCountOf(selections);
}

/**
 * 📄 ชิ้นต่อแผ่นวัสดุของกลุ่มที่ sheetFee อ้างถึง — เช่น กลุ่ม "ขนาด" เลือก A5 ไว้ → 4 เล่ม/แผ่น A3
 * อ่านไม่ได้/ไม่ได้ตั้ง = 1 ชิ้นต่อแผ่น (คิดค่าฟิล์มทุกชิ้น — ปลอดภัยกว่าคิดขาด)
 */
export function perSheetOf(product: Product, opt: ProductOption, selections: Record<string, string>): number {
  return sheetNumberOf(product, opt, selections, "perSheet");
}

/**
 * 📄 แผ่นวัสดุที่งาน 1 ชิ้นกิน ของกลุ่มที่ sheetFee อ้างถึง — เช่น ปฏิทิน 8 แผ่น = 4 แผ่น A3 ต่อเล่ม
 * อ่านไม่ได้/ไม่ได้ตั้ง = 1 แผ่นต่อชิ้น (พฤติกรรมเดิมก่อนมีฟิลด์นี้)
 */
export function sheetsPerUnitOf(product: Product, opt: ProductOption, selections: Record<string, string>): number {
  return sheetNumberOf(product, opt, selections, "sheetsPerUnit");
}

/** อ่านตัวเลขแผ่นวัสดุ (perSheet / sheetsPerUnit) จากตัวเลือกที่เลือกอยู่ในกลุ่ม sheetFee.from */
function sheetNumberOf(
  product: Product,
  opt: ProductOption,
  selections: Record<string, string>,
  field: "perSheet" | "sheetsPerUnit"
): number {
  const src = product.options?.find((o) => o.label === opt.sheetFee?.from);
  const picked = src ? selections[src.label] : undefined;
  const raw = src?.choices.find((c) => c.name === picked)?.[field];
  // ตารางตามคู่ตัวเลือก (from × by) — ยังไม่ได้เลือกกลุ่ม by ก็หยิบค่ามากสุดไว้ก่อน ตามหลักเดียวกับ
  // ค่าเริ่มต้น 1 ของ perSheet: ยอมคิดเกินดีกว่าคิดขาด (กลุ่ม by เป็นแกนราคาอยู่แล้ว ปกติมีค่าเสมอ)
  const n =
    raw != null && typeof raw === "object"
      ? (raw[selections[opt.sheetFee?.by ?? ""] ?? ""] ?? Math.max(...Object.values(raw)))
      : raw;
  return Number.isFinite(n) && (n as number) >= 1 ? Math.floor(n as number) : 1;
}

/** 📄 จำนวนแผ่นวัสดุที่ต้องใช้ของกลุ่มนี้ — ⌈จำนวนที่สั่ง × แผ่นต่อชิ้น ÷ ชิ้นต่อแผ่น⌉ (อย่างน้อย 1 แผ่น) */
export function sheetCountOf(product: Product, opt: ProductOption, selections: Record<string, string>, qty: number): number {
  const sheets = (Math.max(1, qty) * sheetsPerUnitOf(product, opt, selections)) / perSheetOf(product, opt, selections);
  return Math.max(1, Math.ceil(sheets));
}

/**
 * 💰 ค่าเพิ่ม "ต่อแผ่นวัสดุ" จากกลุ่มตัวเลือก (เช่น ค่าฟิล์มเคลือบพิเศษ ต่อแผ่น A3)
 * สั่งไม่ถึง 1 แผ่นก็คิด 1 แผ่น · เกินไปแผ่นที่ 2 ก็คิดเพิ่มอีกแผ่น
 */
export function sheetFeeTotalOf(product: Product, selections: Record<string, string>, qty: number): number {
  let sum = 0;
  for (const opt of product.options ?? []) {
    if (!opt.sheetFee || !optionActive(opt, selections)) continue;
    const fee = groupExtraOf(opt, selections); // +฿ ของตัวเลือกที่เลือกในกลุ่มนี้ (เคลือบเงา/ด้าน = 0)
    if (fee <= 0) continue;
    sum += fee * sheetCountOf(product, opt, selections, qty);
  }
  return sum;
}

export function designFeeFor(product: Product, selections: Record<string, string>, qty: number): number {
  // ค่าเพิ่มต่อลายจากตัวเลือก (สีไหมเกินโควตา ฯลฯ) — คิดครั้งเดียวต่อลาย ไม่คูณจำนวนชิ้น
  const optionFee = perDesignExtraOf(product, selections);
  // ค่าเพิ่มต่อแผ่นวัสดุ (ค่าฟิล์มเคลือบพิเศษ ฯลฯ) — คิดตามจำนวนแผ่นที่ใช้จริง
  const sheetFee = sheetFeeTotalOf(product, selections, qty);
  return optionFee + sheetFee + designFeeBase(product, selections, qty);
}

/** 1 บรรทัดของการแจกแจง "Add on" — ชื่อรายการ + ยอด + วิธีคิดสั้น ๆ */
export interface FeeLine {
  label: string;
  amount: number;
  /** วิธีคิด เช่น "฿40 × 2 แผ่น A3" (ไม่มี = ยอดตรง ๆ ไม่ต้องอธิบาย) */
  note?: string;
}

/**
 * 🧾 แจกแจงว่า designFeeFor() มาจากค่าอะไรบ้าง — ลูกค้าเห็นบรรทัด "+ Add on ฿100" แล้วต้องรู้ว่าคืออะไร
 * ไล่ตามลำดับเดียวกับ designFeeFor เป๊ะ ๆ (ต่อลาย → ต่อแผ่น → ค่าคละลาย) ยอดรวมของทุกบรรทัดจึงเท่ากันเสมอ
 */
export function feeBreakdown(product: Product, selections: Record<string, string>, qty: number): FeeLine[] {
  const lines: FeeLine[] = [];
  const designs = designCountOf(selections);
  for (const opt of product.options ?? []) {
    if (!optionActive(opt, selections)) continue;
    const picked = selections[opt.label];
    if (opt.extraPerDesign) {
      const per = groupExtraOf(opt, selections);
      if (per > 0)
        lines.push({
          label: picked ? `${opt.label}: ${picked}` : opt.label,
          amount: per * designs,
          note: `${formatPrice(per)} × ${designs.toLocaleString("th-TH")} ลาย`,
        });
    }
    if (opt.sheetFee) {
      const fee = groupExtraOf(opt, selections);
      if (fee > 0) {
        const sheets = sheetCountOf(product, opt, selections, qty);
        const unit = opt.sheetFee.unit ?? "แผ่น";
        lines.push({
          // ติดชื่อกลุ่มไว้ด้วย — สินค้าที่มีหลายกลุ่มคิดต่อแผ่น (เคลือบด้านหน้า/ด้านหลัง)
          // ชื่อตัวเลือกซ้ำกันได้ ถ้าโชว์แค่ "เคลือบเงา + เคลือบเงา" ลูกค้าแยกไม่ออกว่าด้านไหน
          label: picked ? `${opt.label}: ${picked}` : opt.label,
          amount: fee * sheets,
          note: `${formatPrice(fee)} × ${sheets.toLocaleString("th-TH")} ${unit}`,
        });
      }
    }
  }
  const mix = designFeeBase(product, selections, qty);
  if (mix > 0) {
    // กติกาคละไม่ถึงขั้นต่ำ — บอกฐานคิดตรง ๆ ว่ากี่ชิ้น × ชิ้นละเท่าไหร่ (ไม่ใช่จำนวนลาย)
    const r = activeRate(product, selections);
    const under = r?.underMinPieceFee && r.minPerDesign ? underMinPieces(qty, designs, r.minPerDesign) : 0;
    lines.push(
      under > 0
        ? {
            label: "ค่าคละลายไม่ถึงขั้นต่ำ",
            amount: mix,
            note: `${formatPrice(r!.underMinPieceFee!)} × ${under.toLocaleString("th-TH")} ชิ้นที่ไม่ถึงลายละ ${r!.minPerDesign!.toLocaleString("th-TH")}`,
          }
        : { label: "ค่าคละลาย", amount: mix, note: `คละ ${designs.toLocaleString("th-TH")} ลาย` }
    );
  }
  return lines;
}

/**
 * 🧾 แจกแจง Add on ที่ "รวมอยู่ในราคาต่อหน่วยแล้ว" — คนละก้อนกับ feeBreakdown
 *
 * ต่างกันตรง:
 *   - feeBreakdown       = ค่าที่บวกท้ายบิล (ค่าวัสดุต่อแผ่น · ค่าต่อลาย · ค่าคละลาย) → โผล่เป็นบรรทัด "+ Add on"
 *   - ตัวนี้             = +฿ ต่อหน่วยธรรมดา (เช่น พิมพ์รองสีขาว +20/แผ่น) ซึ่งบวกเข้าไปในราคาต่อหน่วยไปแล้ว
 *
 * ไม่มีบรรทัดนี้ ลูกค้าเห็นแค่ "฿110 / แผ่น A3" แล้วไม่รู้ว่ามีค่าพิมพ์รองสีขาว 20 บาทรวมอยู่ข้างใน
 * ⚠️ อย่าเอายอดจากที่นี่ไปบวกกับราคารวม — มันถูกนับไปแล้วในราคาต่อหน่วย ที่นี่ทำหน้าที่ "อธิบาย" อย่างเดียว
 */
export function unitAddOnBreakdown(product: Product, selections: Record<string, string>, qty: number): FeeLine[] {
  const m = activeMatrix(product, selections);
  const lines: FeeLine[] = [];
  for (const opt of product.options ?? []) {
    if (!optionActive(opt, selections)) continue;
    // กลุ่มที่เป็นแกนตารางราคา — ราคาอยู่ในช่องตารางอยู่แล้ว ไม่ใช่ของแถมที่บวกทีหลัง
    if (m?.driverLabels.includes(opt.label)) continue;
    // สองชนิดนี้ไม่เข้าราคาต่อหน่วย (ไปโผล่ที่ feeBreakdown แทน) — ใส่ซ้ำจะกลายเป็นบอกสองรอบ
    if (opt.extraPerDesign || opt.sheetFee) continue;
    const add = groupAddOf(opt, selections, qty);
    if (add <= 0) continue;
    const picked = selections[opt.label];
    // ช่องกรอกเก็บแค่ตัวเลข ("2 นิ้ว") — ลำพังอ่านไม่รู้ว่าค่าอะไร ใส่ชื่อกลุ่มนำหน้าให้
    const label = isInputOption(opt) && picked ? `${opt.label} ${picked}` : picked || opt.label;
    lines.push({ label, amount: add });
  }
  return lines;
}

function designFeeBase(product: Product, selections: Record<string, string>, qty: number): number {
  // กติกาคละแบบคิดต่อหน่วยมาก่อน — ค่าคละ = (ค่าต่อหน่วยตามจำนวนลาย) × จำนวนที่สั่ง
  // อ่านผ่าน mixRuleFor เสมอ ให้ตัวเลือกที่ตั้งกติกาเอง (เช่น ไดคัท 50%) ได้ค่าคละของตัวเอง
  const mr = mixRuleFor(product, selections);
  if (mr) return mixFeeTotal(mr, designCountOf(selections), Math.max(0, qty));
  const r = activeRate(product, selections);
  // กติกา "คละไม่ถึงขั้นต่ำ คิดส่วนต่างชิ้นละ N" (เคสมือถือ) — คิดจากชิ้นในลายที่ไม่เต็มขั้นต่ำ
  if (r?.underMinPieceFee) return underMinFeeFor(r, qty, designCountOf(selections));
  if (!r?.minPerDesign || !r.extraDesignFee) return 0;
  const n = parseInt(String(selections[DESIGN_LABEL] ?? ""), 10);
  if (!Number.isFinite(n) || n <= 0) return 0;
  const extra = n - includedDesigns(r, qty, perUnitCapacity(product, selections) ?? 1);
  return extra > 0 ? extra * r.extraDesignFee : 0;
}

export interface Product {
  id: string;
  /**
   * ลิงก์ตามชื่อ (slug) — ตั้งได้จากหลังบ้าน ให้ URL หน้าสินค้าอ่านรู้เรื่อง เช่น /products/ส่วนเสริม-ติ่งห้อย-2cm
   * ไม่ตั้ง = ใช้ id ตามเดิม · ลิงก์เก่าแบบ id ยังเปิดได้เสมอ (หน้าเซิร์ฟเวอร์ค้นทั้งสองแบบ)
   */
  slug?: string;
  name: string;
  category: CategoryId;
  price: number;
  oldPrice?: number;
  emoji: string;
  gradient: string;
  /** รูปหลักจริง (data URL) สำหรับการ์ดสินค้า — ถ้ามีจะแสดงแทนอีโมจิ+สีพื้น */
  imageSrc?: string;
  rating: number;
  sold: number;
  badge?: "ขายดี" | "ใหม่" | "ลดราคา";
  featured?: boolean;
  description: string;
  highlights: string[];
  options: ProductOption[];
  /** กฎจำกัดตัวเลือกข้ามกลุ่ม (ไม่มี = ทุกตัวเลือกใช้ร่วมกันได้หมด) */
  rules?: OptionRule[];
  images: ProductImage[];
  /** เนื้อหารายละเอียดสินค้าท้ายหน้า (แก้ได้จากหลังบ้าน) */
  body?: BodySection[];
  /** แท็บข้อมูลสินค้า (รายละเอียดเพิ่มเติม / วิธีสั่งงาน / การรับประกัน ฯลฯ) — แสดงเป็นแถบแท็บท้ายหน้า */
  tabs?: ProductTab[];
  /** ตารางราคาขั้นบันได (ไม่มี = ใช้ราคาเดียว price + option.extra) */
  pricing?: PriceMatrix;
  /**
   * หลายเรทราคา (เช่น พิน: เรทคละดีเทล / เรทไม่คละดีเทล) — มีเมื่อไหร่ใช้แทน pricing
   * เรทแรกคือค่าเริ่มต้น · pricing จะถูกตั้งเป็นตารางของเรทแรกไว้ด้วยเสมอ (ให้โค้ดเดิมทำงานต่อได้)
   */
  priceRates?: PriceRate[];
  /**
   * วางแผงเลือกเรทราคาไว้ "ใต้" กลุ่มตัวเลือก (ไม่ตั้ง = อยู่ด้านบนเหมือนเดิม)
   * ใช้กับสินค้าที่ต้องรู้ "ของอะไร" ก่อนถึงจะเลือก "ขายแบบไหน" ได้
   * เช่น สติ๊กเกอร์ UV — เลือกเนื้อสติ๊กเกอร์ก่อน แล้วค่อยเลือกขายแบบแผ่น A3 หรือแบบตารางเมตร
   */
  rateAfterOptions?: boolean;
  /**
   * วางแผงเลือกเรทราคาไว้ "ใต้กลุ่มที่ระบุ" — เจาะจงกว่า rateAfterOptions (ได้แค่บนสุด/ล่างสุด)
   * ใช้เมื่อมีกลุ่มที่ขึ้นกับเรท ต้องให้เลือกเรทก่อนถึงจะเจอกลุ่มนั้น
   * เช่น สติ๊กเกอร์ UV — เนื้อสติ๊กเกอร์ → เรทราคา (A3/ตร.ม.) → แบบไดคัท → ขนาดตัดของเรทนั้น
   * ชื่อกลุ่มไม่ตรง/กลุ่มถูกซ่อนอยู่ = ตกกลับไปใช้ตำแหน่งตาม rateAfterOptions ตามเดิม
   */
  rateAfterOption?: string;
  /**
   * คิดเรทราคาตามจำนวนชิ้น "ต่อลาย" ไม่ใช่ยอดรวม — สำหรับสินค้าที่คละลายแล้วต้นทุนไม่ลด
   * เช่น เคส 11 ชิ้นคละ 11 ลาย = ลายละ 1 ชิ้น → คิดเรทราคาปลีก (ราคารวมยังคูณ 11 ชิ้นตามเดิม)
   */
  tierByDesign?: boolean;
  /**
   * 🧮 ชื่อกลุ่ม "จำนวนชิ้นต่อ 1 หน่วยขาย" — สินค้าที่ 1 หน่วยมีหลายชิ้น (พวงกุญแจหลายชิ้นใน 1 พวง)
   * ตั้งแล้ว: จำนวนที่ใช้หาช่วงราคาขั้นบันได = จำนวนที่สั่ง × ชิ้นต่อหน่วย (เลขหน้าชื่อตัวเลือก เช่น "3 ชิ้น")
   * สั่ง 4 พวง พวงละ 3 ชิ้น = 12 ชิ้น → เข้าช่วง 11-29 ชิ้น · ราคารวมยังคูณจำนวนหน่วย (พวง) ตามเดิม
   * ใช้คู่กับ ProductOption.priceAsDriver (ราคาชิ้นที่ 2+ ดึงจากตารางเรทเดียวกัน)
   */
  pieceCountLabel?: string;
  /**
   * 🔒 ห้ามคละเกินโควตาของเรท — ช่อง "คละกี่ลาย" ตันที่ ⌊จำนวน ÷ ขั้นต่ำต่อลาย⌋
   *
   * ค่าเริ่มต้นของ tierByDesign คือ "ไม่บล็อก แต่ราคาตกไปคิดตามชิ้นต่อลาย" (ลูกค้าเลือกจ่ายราคาปลีกเพื่อคละเยอะได้)
   * สินค้าที่ขั้นต่ำต่อลายเป็นข้อจำกัดการผลิตจริง ๆ ให้เปิดอันนี้ — อยากคละมากกว่าโควตาต้องเพิ่มจำนวนสั่งเท่านั้น
   * เช่น เคสมือถือ ลายละ 3 ชิ้น: สั่ง 11 ชิ้น คละได้ 3 ลาย กด + ต่อไม่ได้ (ต้องสั่ง 12 ชิ้นถึงจะคละ 4 ลาย)
   */
  hardMaxDesigns?: boolean;
  /**
   * กติกาคละลายแบบคิดค่าคละเป็นเงินต่อหน่วย (ดู MixRule)
   * ตั้งอันนี้แล้วราคาเรทจะไม่ถูกลดตามจำนวนลายอีก — คิดค่าคละตรง ๆ แทน
   */
  mixRule?: MixRule;
  /** ข้อมูล SEO/AEO (ไม่มี = ใช้ค่าจากชื่อ/รายละเอียดอัตโนมัติ) */
  seo?: ProductSeo;
  /**
   * สั่งตั้งแต่กี่ชิ้นขึ้นไป = ต้องเช็คสต๊อก/คิวผลิตกับแอดมินก่อน (0 หรือไม่ตั้ง = ใช้ค่ากลาง BULK_ASK_DEFAULT)
   * ไม่ได้บล็อกการสั่ง — แค่เตือนลูกค้า + ติดธงให้แอดมินยืนยันจำนวนก่อนเริ่มงาน
   */
  bulkAskQty?: number;
  /**
   * วิธีจัดส่ง "ขั้นต่ำ" ของสินค้านี้ (id จากตั้งค่าระบบ → การจัดส่ง)
   * ใช้กับของชิ้นใหญ่ที่ยังไงก็ต้องกล่องใหญ่ — มีในตะกร้าเมื่อไหร่ ระบบยกระดับค่าส่งให้เอง
   * ไม่ตั้ง = ปล่อยให้คิดตามจำนวน/ยอดตามปกติ
   */
  shippingId?: string;
  /**
   * ค่าส่งขั้นบันไดตามจำนวนชิ้นของสินค้านี้ (ของหนัก เช่น แผ่นหินรองแก้ว)
   * แต่ละขั้น: สั่งตั้งแต่ minQty ชิ้น → ค่าส่ง price บาท (ใช้ขั้นสูงสุดที่จำนวนถึง)
   * ตอนคิดเงิน ระบบใช้ค่าที่แพงกว่าระหว่างวิธีส่งที่เลือกกับค่าตามจำนวนนี้
   */
  shipTiers?: ShipTier[];
  /** เกินขั้นสุดท้ายแล้ว คิดเพิ่มชิ้นละกี่บาท (ไม่ตั้ง = ใช้ราคาขั้นสุดท้ายไปเรื่อย ๆ) */
  shipTierExtra?: number;
  /**
   * เกินขั้นสุดท้ายแล้ว "เปลี่ยนเป็นวิธีส่งนี้" แทนการคิดตามตาราง (id จากตั้งค่าระบบ → การจัดส่ง)
   * ใช้กับของที่เกินจำนวนหนึ่งแล้วต้องส่งแมสเซนเจอร์ — ตั้งคู่กับ shipTierExtra ไม่ได้ (เลือกอย่างใดอย่างหนึ่ง)
   */
  shipTierMethodId?: string;
  /**
   * ค่าส่งที่ขึ้นกับ "ตัวเลือกที่ลูกค้าเลือก" (ขนาด/วัสดุมีผลกับกล่อง)
   * เข้าเงื่อนไขข้อไหน ใช้ค่าส่งขั้นต่ำ/ตารางตามจำนวนของข้อนั้นแทนค่ากลางด้านบน
   */
  shipRules?: ShipOptionRule[];
  /**
   * 📐 เทมเพลตไฟล์งานที่ให้ลูกค้าโหลด (id จากคลังเทมเพลต /admin/templates)
   * ไฟล์ .ai เก็บในคลังกลาง — สินค้าเก็บแค่ id เพื่อให้แก้ไฟล์ที่เดียวแล้วอัปเดตทุกสินค้า
   */
  templateIds?: string[];
  /**
   * 🎨 ปิดปุ่ม "เริ่มสร้าง — วางลายบนสินค้า" ของสินค้านี้ (ตั้งจากหลังบ้าน)
   * ไม่ตั้ง/false = เปิดตามเดิม (ผูกเทมเพลตที่ถอดกรอบงานได้เมื่อไหร่ ปุ่มขึ้นเอง)
   * true = ไม่ให้ลูกค้าวางลายบนเว็บ — กลับไปเป็น "แนบไฟล์ลาย" ตามปกติ
   *        แต่กล่อง 📐 ไฟล์เทมเพลตยังแสดงให้โหลดไปทำเองในโปรแกรมเหมือนเดิม
   */
  studioOff?: boolean;
  /**
   * ข้อควรทราบ / เงื่อนไขงานของสินค้านี้ (ข้อความหลายบรรทัด)
   * เช่น ขนาดยึดด้านไหน · ค่าคลาดเคลื่อนของงานสกรีน · ลักษณะธรรมชาติของวัสดุ
   * แสดงบนหน้าสินค้าให้ลูกค้าอ่านก่อนสั่ง — กันเข้าใจผิด/เคลมทีหลัง
   */
  terms?: string;
  /**
   * ต้องแนบลาย (รูป หรือ ลิงก์/อีเมล) ก่อนถึงจะสั่งได้ไหม
   * ไม่ระบุ = ต้องแนบ (ค่าเริ่มต้นของร้านงานพิมพ์ตามสั่ง) · ตั้ง false สำหรับของเปล่า/วัสดุที่ไม่ต้องใช้ลาย
   */
  artworkRequired?: boolean;
  /**
   * 💬 ต้องคุยเรื่องลาย/ไฟล์กับแอดมินก่อนสั่ง (งานปัก งานตีลาย งานที่ต้องดูตัวอย่างก่อน)
   * ไม่ระบุ = สั่งได้เลยตามปกติ
   */
  artworkConsult?: ArtworkConsult;
  /**
   * 📐 กล่องงานสั่งทำเปิดค้างไว้เสมอ — ไม่ต้องให้ลูกค้าติ๊ก "ต้องการสั่งทำ" ก่อน
   * ใช้กับสินค้าที่ "ไม่มีขนาดมาตรฐาน" ทุกออเดอร์ต้องระบุขนาดเองอยู่แล้ว (เช่น อาร์มปักที่คิดราคาตาม ตร.ซม.)
   * ไม่ตั้ง = ตามเดิม ลูกค้าต้องติ๊กก่อนถึงกางช่องกรอก (ไม่ติ๊ก = ใช้ขนาดมาตรฐาน ราคาตามตารางปกติ)
   */
  mtoAlways?: boolean;
  /**
   * 🔒 บังคับ "ขั้นต่ำต่อลาย" (minPerDesign ของเรท) แบบแข็ง — จำนวน ÷ ลาย ต่ำกว่าเกณฑ์ = กดสั่งไม่ได้
   * ค่าเริ่มต้นของระบบเป็นแบบนุ่ม (สั่งน้อยกว่าได้ แค่ราคาปรับ) — สินค้าที่โรงงานไม่รับผลิตต่ำกว่า
   * ขั้นต่ำจริง ๆ (เช่น อาร์มปัก 5 ชิ้น/ลาย) ตั้งธงนี้
   */
  hardMinPerDesign?: boolean;
  /**
   * 🔒 บังคับ "ยอดสั่งขั้นต่ำ" (minQty ของเรท) แบบแข็ง — ลดจำนวนต่ำกว่าขั้นต่ำของเรทที่เลือกไม่ได้
   * ค่าเริ่มต้นของระบบเป็นแบบนุ่ม: minQty = "เรทนี้เริ่มใช้ที่เท่าไหร่" สั่งน้อยกว่าได้ แล้วระบบสลับลงเรทที่รับ
   * สินค้าที่โรงงานไม่รับต่ำกว่าขั้นต่ำจริง ๆ (เช่น สติ๊กเกอร์ UV เริ่มขายที่ 3 แผ่น A3) ตั้งธงนี้
   * เปิดแล้วปุ่มเลือกเรทจะไม่ล็อกอีก — กดเรทที่ขั้นต่ำสูงกว่า ระบบดันจำนวนขึ้นให้ถึงขั้นต่ำแทน
   */
  hardMinQty?: boolean;
  /**
   * 📦 กลุ่มตัวเลือกที่ "แยกล็อตผลิตออกจากกัน" — ค่าต่างกัน = คนละล็อต ไม่รวมยอดกัน
   * ทั้งขั้นราคาตามจำนวน (tier) และขั้นต่ำแบบ minQtyScope: "lot"
   *
   * เช่น สติ๊กเกอร์ UV ตั้ง ["เนื้อสติ๊กเกอร์"] — ขั้นต่ำ 3 แผ่น A3 คิดต่อ "เนื้อ 1 ชนิด"
   * (เนื้อขาว 2 แผ่น + เนื้อใส 1 แผ่น ≠ ครบ 3 เพราะผลิตคนละรอบ) และช่วงราคาก็นับแยกเนื้อ
   *
   * ไม่ตั้ง = รวมล็อตทั้งสินค้าตามเดิม (สเปคต่างกันได้ ราคาอ่านจากคอลัมน์ของบรรทัดตัวเอง)
   */
  lotKeyOptions?: string[];
  /**
   * 📦 คำเรียก "1 รายการ" ในโหมดสั่งหลายสเปคในครั้งเดียว (ปุ่ม ➕ / หัว "…ที่ 2" / ลิสต์สรุป)
   * ไม่ตั้ง = "แผ่น" (สติ๊กเกอร์ UV ที่เป็นต้นแบบของโหมดนี้) · เคสมือถือตั้ง "รุ่น" → "➕ เพิ่มอีกรุ่น"
   * แค่คำพูดบนหน้าจอ ไม่กระทบราคา/การรวมล็อต
   */
  lotItemWord?: string;
  /** อีโมจิหน้าคำเรียกข้างบน — ไม่ตั้ง = 📄 (เคสมือถือใช้ 📱) */
  lotItemEmoji?: string;
  /**
   * 🛒 กด ➕ แล้ว "หย่อนลงตะกร้าทันที" ไม่ต้องพักสเปคไว้ในหน้าแล้วกดสั่งรวดเดียว
   * เปิด = แต่ละรุ่น/แผ่นลงตะกร้าเป็นบรรทัดของตัวเองตั้งแต่ตอนกด ➕ · ไปนับ/แก้จำนวนกันต่อในตะกร้า
   *        (ตะกร้ารวมยอดทั้งล็อตให้อยู่แล้ว — ราคาขั้นบันไดจึงคิดจากยอดรวมเหมือนเดิม)
   *        ปิดหน้าไปแล้วกลับมาเติมทีหลังของก็ไม่หาย · เคสมือถือทุกตัวใช้โหมดนี้
   * ไม่ตั้ง = โหมดเดิม พักไว้ในหน้าก่อน (สติ๊กเกอร์ UV) — ของยังไม่เข้าตะกร้าจนกว่าจะกดสั่ง
   */
  lotToCart?: boolean;
  /**
   * 📐 คิดราคาจาก "พื้นที่ลาย" ที่ลูกค้ากรอก แทนราคาคอลัมน์เดียวในตาราง
   * ใช้กับงานที่ราคาผูกกับขนาด เช่น อาร์มปัก: 15 ตร.ซม. แรก ฿40 · ตร.ซม. ต่อไป ฿2
   */
  areaPricing?: AreaPricing;
  /**
   * 📐 จำนวนที่สั่งล็อกตามขนาดที่ลูกค้ากรอก — สินค้าที่ขายเป็น "พื้นที่" (เช่น ป้ายไวนิลขายเป็น ตร.ม.)
   * qty = ⌈กว้าง × สูง ÷ areaPerUnit⌉ ปัดขึ้นเต็มหน่วยขาย · ช่องจำนวนหน้าสินค้า/ตะกร้าถูกล็อก
   * กันเคสกรอก 140×200 ซม. (2.8 ตร.ม.) แต่จำนวนค้างที่ 1 แล้วจ่ายแค่เรท 1 หน่วย
   */
  qtyFromArea?: QtyFromArea;
  /** สถานะตรวจสอบหลังบ้าน — มีค่า = ทีมงานเช็คสินค้านี้แล้ว (ใช้กันเช็คซ้ำเมื่อหลายคนช่วยกัน) */
  reviewed?: ProductReview;
  /**
   * ช่วงราคาที่คำนวณไว้ตอนบันทึก (ต่ำสุด/สูงสุดจากตารางราคา) — เซิร์ฟเวอร์เขียนให้เอง
   * มีไว้ให้หน้ารายการ/หน้าแรกโชว์ราคาได้โดยไม่ต้องโหลดตารางราคาทั้งก้อน (หนัก ~320 KB รวมทุกสินค้า)
   */
  priceMin?: number;
  priceMax?: number;
  /**
   * สินค้านี้มีทางเลือกที่ต้องให้แอดมินตีราคาไหม (เซิร์ฟเวอร์เขียนให้เองตอนบันทึก)
   * มีไว้ให้การ์ดหน้ารายการ/หน้าแรกรู้ได้โดยไม่ต้องโหลด options ทั้งก้อน — โชว์ "เริ่มต้น ฿X" แทนช่วงราคา
   */
  quoteOption?: boolean;
  /**
   * ซ่อนจากหน้าร้าน — true = ลูกค้าไม่เห็นทั้งในหน้ารายการ/หน้าแรก/ค้นหา/sitemap
   * และเปิดลิงก์ตรงก็ไม่เจอ (ยกเว้นทีมงานที่ล็อกอินหลังบ้าน — เอาไว้พรีวิวก่อนเปิดขาย)
   * ไม่ตั้ง/false = ขายปกติ · ของที่ยังทำไม่เสร็จหรือเลิกขายชั่วคราว ใช้อันนี้แทนการลบ
   */
  hidden?: boolean;
  /**
   * เวลาที่บันทึกล่าสุด (เซิร์ฟเวอร์เขียนให้เอง) — ใช้กันแท็บที่เปิดค้างไว้บันทึกทับข้อมูลใหม่กว่า
   * หน้าแก้ไขส่งค่านี้กลับมาตอนบันทึก ถ้าไม่ตรงกับในฐานข้อมูล = มีคนแก้ไปแล้ว เซิร์ฟเวอร์จะปฏิเสธ
   */
  savedAt?: string;
  /** ตัวเลือก "กำหนดขนาด/สเปกเอง" (custom) สำหรับงานสั่งทำนอกเหนือขนาดมาตรฐาน */
  custom?: CustomOption;
}

/**
 * ตัวเลือกกำหนดเอง (custom) — ลูกค้าระบุขนาดเอง (กว้าง × ยาว) สำหรับงานสั่งทำ
 * คิดราคาพิเศษนอกเหนือจากตารางราคาปกติ:
 *  - mode "area"  = คิดอัตโนมัติจากพื้นที่ (baseFee + ตร.ม. × ratePerSqm, ไม่ต่ำกว่า minPrice)
 *  - mode "quote" = กรอกขนาดได้ แต่ไม่คิดราคาอัตโนมัติ ให้แอดมินตีราคา (ลูกค้าเห็น "สอบถามราคา")
 *  - mode "size"  = กรอกขนาดที่ต้องการ แต่ราคายังคิดตามตารางราคาปกติ (ขนาดติดไปกับออเดอร์ให้ทีมผลิต)
 *  - mode "chat"  = ไม่ต้องกรอกอะไร โชว์ปุ่มทักไลน์ให้คุยรายละเอียดกับแอดมินก่อน (ราคา = สอบถาม)
 *  - mode "longest" = คิดอัตโนมัติจากตารางราคาเดิม โดยอิง "ด้านที่ยาวที่สุด" (ดู longestSizePlan)
 */
export interface CustomOption {
  enabled: boolean;
  /** ป้ายกลุ่ม เช่น "กำหนดขนาดเอง" */
  label: string;
  mode: "area" | "quote" | "size" | "chat" | "longest";
  /** หน่วยที่ลูกค้ากรอก (area) — ป้ายหน่วย เช่น "ซม." "หลา" (มาจากคลังหน่วย) */
  unit: string;
  /** ตัวแปลง 1 หน่วย → เมตร (area) เก็บติดสินค้าไว้ให้คิดพื้นที่ได้เองแม้คลังเปลี่ยน */
  unitToMeter?: number;
  /** ราคาต่อ 1 ตารางเมตร (area) */
  ratePerSqm?: number;
  /** ค่าธรรมเนียม/ค่าเริ่มต้นคงที่ บวกเพิ่มทุกชิ้น (area) */
  baseFee?: number;
  /** ราคาขั้นต่ำต่อชิ้น (area) */
  minPrice?: number;
  /** คำอธิบาย/เงื่อนไขให้ลูกค้าเห็น */
  note?: string;
  /**
   * กลุ่มตัวเลือกที่ "ยังให้ลูกค้าเลือกได้" ขณะติ๊กกำหนดขนาดเอง (เช่น เปิดสี แต่ปิดขนาด)
   * ไม่ตั้ง/ว่าง = ปิดทุกกลุ่ม
   */
  keepOptions?: string[];
  /**
   * 📐 (longest) ชื่อกลุ่มแกนตารางราคาที่เป็น "ขนาด" เช่น "ขนาด"
   * ราคาอิงแถวที่ครอบด้านยาวสุดของงาน — สั่ง 3×14 ซม. คิดราคาแถว "14×14 ซม."
   */
  sizeLabel?: string;
  /** 📐 (longest) ด้านยาวสุดเกินแถวใหญ่สุดในตาราง คิดเพิ่มต่อ 1 หน่วย ต่อชิ้น (เช่น ซม. ละ 3 บาท) */
  overRate?: number;
  /**
   * 📐 (longest) บวกเรทส่วนเกินเพิ่มอีก เมื่อกลุ่มอื่นเลือกค่าที่ระบุ
   * เช่น สติ๊กเกอร์สูญญากาศ: ใหญ่กว่า 15 ซม. ซม. ละ 3 · ถ้าพิมพ์ 2 ด้าน บวกอีก ซม. ละ 2.5 (รวม 5.5)
   */
  overRateWhen?: { label: string; choices: string[]; add: number }[];
  /** 📐 (longest) ด้านยาวสุดที่รับผลิตได้ (หน่วยเดียวกับ unit) — เกินนี้กดสั่งไม่ได้ */
  maxLongest?: number;
  /** 📐 (longest) อีกด้าน (ด้านสั้น) ที่รับผลิตได้ — คู่กับ maxLongest ใช้จำกัดให้อยู่ในกระดาษ A3 */
  maxShortest?: number;
}

/**
 * 📐 คิดราคาตาม "พื้นที่ลาย" — ราคาเหมาก้อนแรก + ส่วนที่เกินคิดต่อหน่วยพื้นที่
 *
 * ทั้งสองเรทดึงจากตารางราคาเดิม (คนละคอลัมน์) จึงเปลี่ยนตามช่วงจำนวนที่สั่งเองอัตโนมัติ
 * ตัวอย่างอาร์มปัก 150 ชิ้น ลาย 5×7 = 35 ตร.ซม.
 *   15 ตร.ซม. แรก ฿25 + (35−15) × ฿1.25 = ฿25 → รวม ฿50/ชิ้น
 *
 * ยังไม่กรอกขนาด = ตกกลับไปใช้ราคาคอลัมน์ตามปกติ (ลูกค้าเห็น "เริ่มต้น ฿X" ก่อนกรอก)
 */
export interface AreaPricing {
  enabled: boolean;
  /** ชื่อกลุ่มช่องกรอกด้านกว้าง/ยาว — พื้นที่ = กว้าง × ยาว (หน่วยเดียวกับที่ตั้งในช่องกรอก) */
  widthLabel: string;
  heightLabel: string;
  /** ชื่อคอลัมน์ในตารางราคาที่เป็น "ราคาเหมาก้อนแรก" (เช่น "15 ตร.ซม. แรก") */
  baseColumn: string;
  /** ชื่อคอลัมน์ที่เป็น "ราคาต่อ 1 หน่วยพื้นที่ที่เกินก้อนแรก" (เช่น "ตร.ซม. ต่อไป") */
  stepColumn: string;
  /** พื้นที่ที่รวมอยู่ในราคาก้อนแรกแล้ว (เช่น 15 ตร.ซม.) */
  baseArea: number;
  /** ปัดเศษราคาต่อชิ้น — ไม่ตั้ง = ปัดขึ้น (ร้านไม่ขาดทุนเศษสตางค์) */
  round?: "none" | "ceil" | "round";
}

/** ตัวเลขที่ลูกค้ากรอกในกลุ่มช่องกรอก (ตัดหน่วยท้ายออก) — ยังไม่กรอก/ไม่ใช่ตัวเลข = 0 */
function inputNumberOf(selections: Record<string, string>, label: string): number {
  const n = Number(String(selections[label] ?? "").replace(/[^\d.]/g, ""));
  return Number.isFinite(n) && n > 0 ? n : 0;
}

/** รายละเอียดการคิดราคาตามพื้นที่ — ใช้ทั้งคิดเงินและโชว์วิธีคิดให้ลูกค้าอ่าน */
export interface AreaBreakdown {
  width: number;
  height: number;
  /** พื้นที่รวม (กว้าง × ยาว) */
  area: number;
  /** พื้นที่ที่รวมในราคาก้อนแรก */
  baseArea: number;
  /** ราคาก้อนแรกของช่วงจำนวนที่สั่งอยู่ */
  basePrice: number;
  /** ราคาต่อหน่วยพื้นที่ส่วนเกิน ของช่วงจำนวนที่สั่งอยู่ */
  stepPrice: number;
  /** พื้นที่ส่วนที่เกินก้อนแรก */
  extraArea: number;
  /** เงินของส่วนเกิน */
  extraPrice: number;
  /** ราคาต่อชิ้นสุทธิ (ปัดแล้ว) */
  unitPrice: number;
}

/**
 * คิดราคา/ชิ้น จากพื้นที่ที่ลูกค้ากรอก · คืน null เมื่อยังคิดไม่ได้
 * (ไม่ได้เปิดใช้ · ยังไม่กรอกขนาด · ไม่มีคอลัมน์ที่อ้างถึงในตาราง)
 */
export function areaPriceBreakdown(
  p: Product,
  selections: Record<string, string>,
  qty: number
): AreaBreakdown | null {
  const a = p.areaPricing;
  if (!a?.enabled) return null;
  const width = inputNumberOf(selections, a.widthLabel);
  const height = inputNumberOf(selections, a.heightLabel);
  if (!width || !height) return null;
  const m = activeMatrix(p, selections);
  if (!m) return null;
  const i = tierIndex(m, tierQtyFor(p, selections, qty));
  const basePrice = m.cells[a.baseColumn]?.[i];
  const stepPrice = m.cells[a.stepColumn]?.[i];
  if (typeof basePrice !== "number" || typeof stepPrice !== "number") return null;
  const area = width * height;
  const extraArea = Math.max(0, area - a.baseArea);
  const extraPrice = extraArea * stepPrice;
  const raw = basePrice + extraPrice;
  const unitPrice = a.round === "none" ? raw : a.round === "round" ? Math.round(raw) : Math.ceil(raw);
  return { width, height, area, baseArea: a.baseArea, basePrice, stepPrice, extraArea, extraPrice, unitPrice };
}

/**
 * 📐 สเปกของ Product.qtyFromArea — จำนวนที่สั่งคำนวณจากขนาดที่ลูกค้ากรอก (ปัดขึ้นเต็มหน่วยขาย)
 * ใช้กับสินค้าขายเป็นพื้นที่ เช่น ป้ายไวนิล: กรอก ซม. ขายเป็น ตร.ม. → areaPerUnit 10000
 * กติกาปัดขึ้น: เศษพื้นที่คิดเป็นหน่วยเต็ม (เช่น 2.8 ตร.ม. → คิด 3 ตร.ม.) — ผู้ใช้เคาะ 25 ส.ค. 69
 */
export interface QtyFromArea {
  /** ชื่อกลุ่มช่องกรอกด้านกว้าง/สูง (standardInput หน่วยเดียวกัน เช่น ซม.) */
  widthLabel: string;
  heightLabel: string;
  /** พื้นที่ต่อ 1 หน่วยขาย ในหน่วยช่องกรอกยกกำลังสอง เช่น กรอก ซม. ขาย ตร.ม. = 10000 */
  areaPerUnit: number;
  /**
   * ขั้นต่ำต่อด้าน (หน่วยช่องกรอก) — ด้านที่สั้นกว่านี้คิดเงินเท่าค่านี้ เช่น 100 ซม. = ด้านละ 1 เมตร
   * (ป้าย 50×200 ซม. พื้นที่จริง 1 ตร.ม. แต่คิดเป็น 100×200 = 2 ตร.ม. — ผู้ใช้เคาะ 25 ส.ค. 69)
   * ไม่ตั้ง = ไม่มีขั้นต่ำต่อด้าน คิดจากขนาดจริง
   */
  minSide?: number;
}

/** ผลคำนวณจำนวนตามขนาด — พกขนาดที่กรอก/ขนาดที่ใช้คิดเงิน/พื้นที่ ไว้โชว์วิธีคิดให้ลูกค้าเห็น */
export interface AreaQty {
  width: number;
  height: number;
  /** ขนาดที่ใช้คิดเงิน — ด้านที่สั้นกว่า minSide ถูกดันขึ้นเป็น minSide แล้ว (ไม่ตั้ง = เท่าที่กรอก) */
  billedWidth: number;
  billedHeight: number;
  /** พื้นที่คิดเงินในหน่วยขาย (จาก billedWidth×billedHeight ยังไม่ปัด) เช่น 2.8 ตร.ม. */
  area: number;
  /** จำนวนหน่วยที่ต้องสั่ง = ปัดขึ้นเต็มหน่วย อย่างน้อย 1 */
  qty: number;
}

/** จำนวนหน่วยที่ต้องสั่งตามขนาดที่กรอก — null = สินค้าไม่ได้ตั้ง qtyFromArea หรือยังกรอกไม่ครบ */
export function qtyFromAreaOf(p: Product, selections: Record<string, string>): AreaQty | null {
  const c = p.qtyFromArea;
  if (!c || !(c.areaPerUnit > 0)) return null;
  const width = inputNumberOf(selections, c.widthLabel);
  const height = inputNumberOf(selections, c.heightLabel);
  if (!width || !height) return null;
  const billedWidth = Math.max(width, c.minSide ?? 0);
  const billedHeight = Math.max(height, c.minSide ?? 0);
  const area = (billedWidth * billedHeight) / c.areaPerUnit;
  return { width, height, billedWidth, billedHeight, area, qty: Math.max(1, Math.ceil(area)) };
}

/**
 * 💬 คุยลายกับแอดมินก่อนสั่ง — งานที่ตกลงแบบกันก่อนถึงจะเริ่มได้
 * (งานปักต้องตีลาย/แปลงไฟล์ให้ดูก่อน · งานที่ลายต้องปรับให้เข้ากับวัสดุ)
 * ลูกค้าเห็นกล่องสีเขียว: ทักไลน์ → คุยกับแอดมิน → ติ๊กยืนยันว่าคุยแล้ว → ถึงจะกดสั่งได้
 */
export interface ArtworkConsult {
  enabled: boolean;
  /** เหตุผล/รายละเอียดที่แสดงให้ลูกค้าอ่าน (ไม่ใส่ = ใช้ข้อความกลางของระบบ) */
  note?: string;
  /**
   * ไม่ระบุ/true = สั่งไม่ได้จนกว่าจะติ๊กยืนยันว่าคุยกับแอดมินแล้ว
   * false = แค่แนะนำให้ทักก่อน (กดสั่งได้เลย)
   */
  block?: boolean;
  /**
   * 👁 บังคับเฉพาะเมื่อลูกค้าเลือกค่าที่กำหนด — ไม่ตั้ง = บังคับทุกกรณี (ทั้งสินค้า)
   * label อ้างชื่อกลุ่มตัวเลือก หรือ "เรทราคา" (RATE_LABEL) ก็ได้ เหมือนเงื่อนไข showWhen ของกลุ่ม
   * เช่น หมวก/เสื้อ ที่ขายทั้งงานพิมพ์และงานปัก: { label: "เรทราคา", choices: ["งานปัก"] }
   * → เลือกเรทพิมพ์ = สั่งได้เลย · เลือกเรทงานปัก = ต้องคุยลายก่อน
   */
  when?: { label: string; choices: string[] };
  /** เงื่อนไขข้อที่สอง — ต้องตรงพร้อมกันกับ when ถึงจะบังคับ (ไม่ตั้ง = ใช้ข้อเดียว) */
  whenAlso?: { label: string; choices: string[] };
  /**
   * เงื่อนไข "หรือ" — ข้อใดข้อหนึ่งตรงก็บังคับ (ต่างจาก when/whenAlso ที่ต้องตรงพร้อมกัน)
   * ใช้เมื่อมีหลายทางที่พาไปสู่งานที่ต้องคุยก่อน เช่น พวงกุญแจหลายชิ้น:
   * เลือก "แบบอื่น ๆ" ได้ทั้งกลุ่มรูปแบบการห้อยของชิ้นงาน และของติ่งห้อย
   */
  whenAny?: { label: string; choices: string[] }[];
}

/** ป้ายที่ติดไปกับรายการในตะกร้า/ออเดอร์เมื่อลูกค้ายืนยันว่าคุยลายกับแอดมินแล้ว */
export const CONSULT_LABEL = "คุยลายกับแอดมิน";

/** ข้อความกลางเมื่อแอดมินไม่ได้เขียนเหตุผลเอง */
export const CONSULT_NOTE_DEFAULT =
  "งานแบบนี้ต้องคุยเรื่องลายกับแอดมินก่อนนะครับ — ส่งไฟล์/แบบที่ต้องการมาทางไลน์ ทางร้านจะตีลายให้ดูก่อน ตกลงแบบกันเรียบร้อยแล้วค่อยกดสั่ง";

/**
 * ต้องคุยลายกับแอดมินก่อนไหม ณ ตัวเลือกชุดนี้ (คืน null ถ้าไม่เข้าเงื่อนไข/ไม่ได้เปิดใช้)
 * เปิดสวิตช์แล้วไม่ตั้งเงื่อนไข = บังคับทุกกรณี · ตั้งเงื่อนไขไว้ = บังคับเฉพาะตอนที่ลูกค้าเลือกค่านั้น
 * (เช่น เรทราคา = งานปัก · แบบงาน = ปักนูน) — ตั้งครบสองข้อต้องตรงพร้อมกัน
 * selections ที่ส่งมาต้องมี "เรทราคา" (RATE_LABEL) รวมอยู่ด้วย ถึงจะอ้างเรทเป็นเงื่อนไขได้
 */
export function artworkConsultOf(p: Product, selections?: Record<string, string>): ArtworkConsult | null {
  const c = p.artworkConsult;
  if (!c?.enabled) return null;
  const set = (w?: { label: string; choices: string[] }) => !!w?.label && !!w.choices?.length;
  const anyConds = (c.whenAny ?? []).filter(set);
  if (!set(c.when) && !set(c.whenAlso) && !anyConds.length) return c;
  // ตั้งเงื่อนไขไว้แต่ไม่รู้ว่าลูกค้าเลือกอะไร = ตัดสินไม่ได้ ถือว่ายังไม่บังคับ
  if (!selections) return null;
  /**
   * กลุ่มที่อ้างถึงถูกซ่อนอยู่ = ลูกค้าไม่ได้เลือกค่านั้นจริง (ค่าที่ค้างเป็นของเก่าที่เคยเลือกไว้)
   * ห้ามเอามาบล็อกการสั่ง — ไม่งั้นเลือก "แบบอื่น ๆ" ไว้แล้วปิดกลุ่มนั้นทิ้ง ปุ่มสั่งจะค้างบล็อกทั้งที่
   * ลูกค้าไม่เห็นกลุ่มนั้นแล้ว (กติกาเดียวกับที่ allowedChoices ใช้กับกฎเงื่อนไข)
   */
  const hiddenSrc = (label: string) => {
    const g = p.options?.find((o) => o.label === label);
    return !!g && !optionVisible(g, selections);
  };
  const pass = (w?: { label: string; choices: string[] }) =>
    !set(w) || (!hiddenSrc(w!.label) && valueMatchesAny(selections[w!.label], w!.choices));
  // เงื่อนไข "หรือ" ผ่านเมื่อข้อใดข้อหนึ่งตรง · ไม่ได้ตั้งไว้ = ไม่มีข้อจำกัดฝั่งนี้
  const anyPass =
    !anyConds.length || anyConds.some((w) => !hiddenSrc(w.label) && valueMatchesAny(selections[w.label], w.choices));
  return anyPass && pass(c.when) && pass(c.whenAlso) ? c : null;
}

/**
 * แปลงข้อความ (เช่น ชื่อสินค้า) เป็น slug สำหรับลิงก์ — คงภาษาไทยไว้
 * เว้นวรรค→ขีดกลาง · ตัดอักขระที่มีความหมายพิเศษใน URL ออก
 */
export function slugifyProductName(name: string): string {
  return name
    .trim()
    .replace(/[()[\]{}<>#%?&=+/\\'"`!,;:@^|~*$]/g, " ")
    .trim()
    .replace(/\s+/g, "-");
}

/**
 * ย่อชื่อตัวเลือกสำหรับ "ป้ายกำกับ" (หัวตารางราคา / ชื่อแถวคู่ตัวเลือก)
 * — ตัดคำอธิบายในวงเล็บ เช่น "สีพิเศษ (โฮโลแกรม/กลิสเตอร์/สี)" → "สีพิเศษ"
 * — บีบช่องว่างรอบ "/" เช่น "ใส / ขาวขุ่น C-02" → "ใส/ขาวขุ่น C-02"
 * ชื่อเต็มยังใช้เป็นคีย์ราคาและแสดงในกลุ่มตัวเลือกตามเดิม (ย่อเฉพาะตอนแสดงผล)
 */
export function shortChoice(name: string): string {
  const s = name
    .replace(/\s*\([^)]*\)/g, "")
    .replace(/\s*\/\s*/g, "/")
    .replace(/\s+/g, " ")
    .trim();
  return s || name.trim();
}

/** ชิ้นส่วนของคีย์คู่ตัวเลือก (a│b│c) แบบย่อแล้ว — ใช้แสดงทีละบรรทัด ไม่ให้ป้ายยาวเป็นพืด */
export function shortComboParts(key: string): string[] {
  return key.split("│").filter(Boolean).map(shortChoice);
}

/** ลิงก์หน้าสินค้า — ใช้ slug (ลิงก์ตามชื่อ) ถ้าตั้งไว้ ไม่งั้นใช้ id ตามเดิม */
export function productPath(p: { id: string; slug?: string }): string {
  const s = (p.slug ?? "").trim();
  return `/products/${encodeURIComponent(s || p.id)}`;
}

/**
 * ลิงก์หน้าแก้ไขสินค้าในหลังบ้าน — ใช้ชื่อเดียวกับลิงก์หน้าร้าน (slug) เพื่อให้สองที่อ่านตรงกัน
 * เช่น หน้าร้าน /products/กระเป๋าผ้าแคนวาส → หลังบ้าน /admin/products/กระเป๋าผ้าแคนวาส
 * ลิงก์ด้วย id เดิมยังเปิดได้ตามปกติ (หน้าแก้ไขค้นด้วย id ก่อน ไม่เจอค่อยค้นด้วย slug)
 */
export function adminProductPath(p: { id: string; slug?: string }): string {
  const s = (p.slug ?? "").trim();
  return `/admin/products/${encodeURIComponent(s || p.id)}`;
}

/** ตัวแปลงหน่วยเดิม (backward-compat กับสินค้าที่บันทึกก่อนมีคลังหน่วย) */
const UNIT_TO_M: Record<string, number> = { cm: 0.01, inch: 0.0254, m: 1, "ซม.": 0.01, "นิ้ว": 0.0254, "เมตร": 1 };

/** ราคา/ชิ้น ของงานกำหนดขนาดเอง (area mode) จากกว้าง×ยาว ตามหน่วยที่ตั้งไว้ · โหมดอื่นคืน 0 */
export function customUnitPrice(c: CustomOption, width: number, height: number): number {
  if (c.mode !== "area" || !(width > 0) || !(height > 0)) return 0;
  const m = c.unitToMeter ?? UNIT_TO_M[c.unit] ?? 0.01;
  const areaSqm = width * m * (height * m);
  const raw = (c.baseFee ?? 0) + areaSqm * (c.ratePerSqm ?? 0);
  return Math.max(c.minPrice ?? 0, Math.round(raw));
}

/**
 * กลุ่มนี้ยังให้ลูกค้าเลือกได้ไหมขณะใช้ขนาดกำหนดเอง
 * เทียบชื่อแบบตัดช่องว่างหัว-ท้าย — ชื่อกลุ่มเก่าบางตัวเคยมีเว้นวรรคท้ายติดมา
 * พอชื่อกลุ่มถูก trim ทีหลัง keepOptions ที่เก็บชื่อเดิมไว้เลยไม่แมตช์ กลุ่มโดนล็อกทั้งที่แอดมินติ๊กเปิดไว้
 */
export function customKeepsOption(c: CustomOption | null | undefined, label: string): boolean {
  if (!c) return false;
  const want = label.trim();
  return (c.keepOptions ?? []).some((l) => l.trim() === want);
}

/** อ่านค่า กว้าง×ยาว จากข้อความที่เก็บใน selections (เช่น "200×150") */
export function parseCustomDims(raw?: string): { w: number; h: number } | null {
  const m = (raw ?? "").match(/(\d+(?:\.\d+)?)\s*[×xX*]\s*(\d+(?:\.\d+)?)/);
  return m ? { w: +m[1], h: +m[2] } : null;
}

/** ขนาด (ด้านยาวสุด) ที่ชื่อตัวเลือกสื่อถึง เช่น "10×10 ซม." → 10 · ไม่มีตัวเลข = null */
export function choiceSizeCm(name: string): number | null {
  const nums = String(name).match(/\d+(?:\.\d+)?/g);
  return nums?.length ? Math.max(...nums.map(Number)) : null;
}

/** 📐 ที่มาของราคางานกำหนดขนาดเอง แบบอิงด้านที่ยาวที่สุด — ใช้ทั้งคิดเงินและกางให้ลูกค้าอ่าน */
export interface LongestSizePlan {
  /** ด้านยาวสุดที่ลูกค้ากรอก (ปัดขึ้นเต็มหน่วย) */
  longest: number;
  /** ชื่อตัวเลือกขนาดในตารางที่ใช้เป็นราคาฐาน */
  choice: string;
  /** ขนาดของแถวนั้น (ซม.) */
  choiceCm: number;
  /** หน่วยที่เกินแถวใหญ่สุด (0 = อยู่ในตาราง ไม่มีส่วนเกิน) */
  overCm: number;
  /** เรทส่วนเกินต่อ 1 หน่วย ต่อชิ้น (รวมส่วนที่บวกตามตัวเลือกอื่นแล้ว เช่น พิมพ์ 2 ด้าน) */
  overRate: number;
  /** ค่าเพิ่มของส่วนเกิน ต่อชิ้น */
  overFee: number;
}

/** เรทส่วนเกินต่อหน่วย ณ ตัวเลือกที่เลือกอยู่ = overRate + ทุกข้อใน overRateWhen ที่เข้าเงื่อนไข */
function overRateOf(c: CustomOption, selections: Record<string, string>): number {
  let r = c.overRate ?? 0;
  for (const w of c.overRateWhen ?? []) if (valueMatchesAny(selections[w.label], w.choices)) r += w.add;
  return r;
}

/**
 * 📐 แผนราคาของงานกำหนดขนาดเอง โหมด "longest" — null เมื่อยังคิดไม่ได้
 * (ไม่ได้เปิดใช้ · ไม่ใช่โหมดนี้ · ยังไม่กรอกขนาด · ไม่พบกลุ่มขนาด/แถวราคา)
 *
 * ด้านยาวสุดปัดขึ้นเต็มหน่วยก่อนเสมอ แล้วเลือก "แถวที่เล็กที่สุดที่ยังครอบขนาดนั้นได้"
 * เช่น 3×14 ซม. → แถว 14×14 ซม. · 3×14.2 ซม. → แถว 15×15 ซม.
 * ใหญ่กว่าแถวสุดท้าย = ใช้แถวสุดท้ายเป็นฐาน แล้วคิดส่วนเกินหน่วยละ overRate ต่อชิ้น
 */
export function longestSizePlan(p: Product, selections: Record<string, string>): LongestSizePlan | null {
  const c = p.custom;
  if (!c?.enabled || c.mode !== "longest" || !c.sizeLabel) return null;
  const dims = parseCustomDims(selections[c.label]);
  if (!dims) return null;
  const want = c.sizeLabel.trim();
  const opt = p.options.find((o) => o.label.trim() === want);
  if (!opt) return null;
  const rows = opt.choices
    .map((ch) => ({ name: ch.name, cm: choiceSizeCm(ch.name) }))
    .filter((r): r is { name: string; cm: number } => r.cm != null)
    .sort((a, b) => a.cm - b.cm);
  if (!rows.length) return null;
  // ปัดขึ้นเต็มหน่วย (เผื่อ floating point ของเลขที่ลูกค้าพิมพ์ เช่น 14.000000001)
  const longest = Math.ceil(Math.max(dims.w, dims.h) - 1e-9);
  const row = rows.find((r) => longest <= r.cm) ?? rows[rows.length - 1];
  const overCm = Math.max(0, longest - row.cm);
  const overRate = overCm > 0 ? overRateOf(c, selections) : 0;
  return { longest, choice: row.name, choiceCm: row.cm, overCm, overRate, overFee: overCm * overRate };
}

/**
 * ขนาดที่ลูกค้ากรอกเกินที่รับผลิตได้ไหม — คืนข้อความบอกเหตุผล (null = ผ่าน)
 * ใช้ทั้งหน้าสินค้า (ล็อกปุ่มสั่ง) และตอนตรวจของในตะกร้า
 */
export function customSizeError(c: CustomOption | null | undefined, w: number, h: number): string | null {
  if (!c || !(w > 0) || !(h > 0)) return null;
  const long = Math.max(w, h);
  const short = Math.min(w, h);
  if (c.maxLongest && long > c.maxLongest) return `ด้านยาวสุดไม่เกิน ${c.maxLongest} ${c.unit}`;
  if (c.maxShortest && short > c.maxShortest) return `อีกด้านไม่เกิน ${c.maxShortest} ${c.unit}`;
  return null;
}

/** บันทึกว่าใคร "ตรวจแล้ว" เมื่อไหร่ — โชว์เป็นป้ายในหลังบ้านให้ทีมงานไม่ทำงานซ้ำกัน */
export interface ProductReview {
  /** ชื่อผู้ตรวจล่าสุด (โหมดเดโมที่ไม่มีชื่อ = "ทีมงาน") */
  by: string;
  /** เวลาที่ตรวจ (ISO string) */
  at: string;
}

/** ข้อมูลปรับแต่งการค้นหา — SEO (meta) + AEO (คำถาม-คำตอบให้ AI/answer engine ดึงไปตอบ) */
export interface ProductSeo {
  /** meta/OG title (เว้นว่าง = ใช้ชื่อสินค้า) */
  title?: string;
  /** meta description (เว้นว่าง = ใช้ description) */
  description?: string;
  /** คำค้น (keywords) */
  keywords?: string[];
  /** คำถามพบบ่อย — แสดงหน้าสินค้า + ฝัง FAQPage JSON-LD ให้ answer engine */
  faqs?: { q: string; a: string }[];
}

