export function getProduct(id: string): Product | undefined {
  // id ก่อน ไม่เจอค่อยลองลิงก์ตามชื่อ (slug) — ลิงก์แบบ /products/ชื่อไทย และ /admin/products/ชื่อไทย ใช้ตัวเดียวกัน
  return PRODUCTS.find((p) => p.id === id) ?? PRODUCTS.find((p) => (p.slug ?? "") === id);
}

export function formatPrice(n: number): string {
  // มีสตางค์ = โชว์สองตำแหน่งเสมอ (฿2.50 · ฿202.50) — ตั้งแต่มีค่าบริการระดับสตางค์ (จุดไดคัทจุดละ ฿0.50)
  // ยอดอย่าง "฿2.5" อ่านเหมือนราคายังพิมพ์ไม่จบ · จำนวนเต็มคงรูปเดิมทุกที่ (฿202 ไม่กลายเป็น ฿202.00)
  const opts = n % 1 ? { minimumFractionDigits: 2, maximumFractionDigits: 2 } : undefined;
  return `฿${n.toLocaleString("th-TH", opts)}`;
}

/** เรทที่ลูกค้าเลือกอยู่ (จาก selections) — ไม่เจอ/ไม่ได้เลือก = เรทแรก · สินค้าไม่มีหลายเรท = undefined */
export function activeRate(p: Product, selections: Record<string, string>): PriceRate | undefined {
  const rs = p.priceRates;
  if (!rs?.length) return undefined;
  return rs.find((r) => r.label === selections[RATE_LABEL]) ?? rs[0];
}

/** ตารางราคาที่ใช้จริงตามเรทที่เลือก — สินค้าเรทเดียวคืน pricing เดิม */
export function activeMatrix(p: Product, selections: Record<string, string>): PriceMatrix | undefined {
  return activeRate(p, selections)?.pricing ?? p.pricing;
}

/**
 * ตัวเลือกนี้มีราคาขายในตารางนี้ไหม — แถวที่แอดมินล้างราคาทิ้ง (ไม่ขายในเรทนั้น)
 * จะไม่มีคีย์ในตาราง → หน้าร้านซ่อนตัวเลือกนั้นเมื่อลูกค้าเลือกเรทนั้นอยู่
 */
export function matrixChoiceAvailable(m: PriceMatrix, label: string, choice: string): boolean {
  const di = m.driverLabels.indexOf(label);
  if (di < 0) return true; // กลุ่มที่ไม่ใช่แกนตาราง ไม่เกี่ยวกับตาราง
  return Object.keys(m.cells).some((k) => k.split("│")[di] === choice);
}

/**
 * ทุกกลุ่มที่เป็น "แกนตารางราคา" ของสินค้านี้ (รวมทุกเรท) — ค่าของกลุ่มพวกนี้คือกุญแจหาราคาในตาราง
 * ขาดไปแม้กลุ่มเดียว คีย์จะหาช่องไม่เจอ แล้วราคาหล่นไปใช้ราคาตั้งต้นของสินค้า
 * → ตะกร้า/ออเดอร์ต้องเก็บค่ากลุ่มพวกนี้ไว้เสมอ แม้กลุ่มนั้นจะถูกซ่อนจากหน้าร้าน (showWhen ไม่ตรง)
 */
export function priceDriverLabels(p: Product): string[] {
  const all = [p.pricing, ...(p.priceRates ?? []).map((r) => r.pricing)];
  return [...new Set(all.flatMap((m) => m?.driverLabels ?? []))];
}

/**
 * คีย์คอลัมน์ราคา ที่เติมค่าเริ่มต้นให้แกนตารางที่ "ไม่มีค่า" ใน selections
 * ใช้กับของที่อยู่ในตะกร้า/ออเดอร์เก่าซึ่งเคยถูกตัดกลุ่มที่ซ่อนไว้ออกไป — ราคาจะได้ตรงกับที่ลูกค้าเห็นตอนสั่ง
 * (ค่าเริ่มต้นเลือกแบบเดียวกับ resolveSelections: ตัวแรกที่กฎอนุญาตและมีราคาในตาราง)
 */
function matrixKeyFilled(product: Product, m: PriceMatrix, selections: Record<string, string>): string {
  const filled = { ...selections };
  for (const label of m.driverLabels) {
    if (filled[label]) continue;
    if (!product.options?.some((o) => o.label === label)) continue;
    const allowed = allowedChoices(product, filled, label);
    const priced = allowed.filter((n) => matrixChoiceAvailable(m, label, n));
    const pick = (priced.length > 0 ? priced : allowed)[0];
    if (pick) filled[label] = pick;
  }
  return priceMatrixKey(m, filled);
}

/** ช่วงราคาต่ำสุด–สูงสุดของสินค้า — ถ้ามีตารางราคาขั้นบันไดคิดจากทุกช่อง, ไม่งั้นคิดจากราคาตั้งต้น + option.extra */
export function priceRange(p: Product): { min: number; max: number } {
  /**
   * 📐 สินค้าคิดตามพื้นที่: คอลัมน์ "ต่อหน่วยพื้นที่" (เช่น ฿1/ตร.ซม.) ไม่ใช่ราคาต่อชิ้น
   * เอามารวมช่วงราคาจะได้ "฿1 – ฿40" ซึ่งอ่านผิดความหมาย — ใช้เฉพาะคอลัมน์ราคาก้อนแรก
   * (= ราคาต่อชิ้นของลายที่ไม่เกินพื้นที่ก้อนแรก คือราคาเริ่มต้นจริง ๆ ของงาน)
   */
  const ap = p.areaPricing;
  if (ap?.enabled) {
    const base = [
      ...(p.priceRates ?? []).flatMap((r) => r.pricing.cells[ap.baseColumn] ?? []),
      ...(p.pricing?.cells[ap.baseColumn] ?? []),
    ].filter((n) => n > 0);
    if (base.length) return { min: Math.min(...base), max: Math.max(...base) };
  }
  if (p.priceRates?.length) {
    const all = p.priceRates.flatMap((r) => Object.values(r.pricing.cells).flat()).filter((n) => n > 0);
    if (all.length) return { min: Math.min(...all), max: Math.max(...all) };
  }
  if (p.pricing) {
    const all = Object.values(p.pricing.cells).flat();
    if (all.length) return { min: Math.min(...all), max: Math.max(...all) };
  }
  // ข้อมูลแบบเบา (การ์ดหน้ารายการ) ไม่มีตารางราคามาด้วย → ใช้ช่วงที่คำนวณไว้ตอนบันทึก
  if (typeof p.priceMin === "number" && typeof p.priceMax === "number") {
    return { min: p.priceMin, max: p.priceMax };
  }
  let min = p.price;
  let max = p.price;
  for (const opt of p.options) {
    if (opt.choices.length === 0) continue;
    const extras = opt.choices.map((c) => c.extra ?? 0);
    if (isMultiOption(opt)) {
      // ติ๊กได้หลายอย่าง: ไม่ติ๊กเลย = ไม่บวก · ติ๊กครบ = บวกทุกตัว
      max += extras.reduce((s, e) => s + Math.max(0, e), 0);
      continue;
    }
    min += Math.min(...extras);
    max += Math.max(...extras);
  }
  return { min, max };
}

/** index ของ tier ที่จำนวน qty ตกอยู่ */
export function tierIndex(m: PriceMatrix, qty: number): number {
  for (let i = 0; i < m.tiers.length; i++) {
    const up = m.tiers[i].upTo;
    if (up == null || qty <= up) return i;
  }
  return Math.max(0, m.tiers.length - 1);
}

/** key ของคอลัมน์ในตารางราคา จากตัวเลือกที่เลือกอยู่ */
export function priceMatrixKey(m: PriceMatrix, selections: Record<string, string>): string {
  return m.driverLabels.map((l) => selections[l] ?? "").join("│");
}

/**
 * 📐 คีย์ในตัวเลือกที่บอกว่าลูกค้า "ติ๊กสั่งทำ" ไว้
 * เก็บเป็นตัวเลือกปกติ จะได้ติดไปกับตะกร้า/ออเดอร์/ใบงานเองว่าใบนี้เป็นงานสั่งทำ
 */
export const MTO_LABEL = "งานสั่งทำ";
export const MTO_ON = "กำหนดขนาด/รายละเอียดเอง";

/**
 * กลุ่มนี้เป็นของงานสั่งทำไหม — ช่องกรอกเป็นโดยธรรมชาติ · กลุ่มตัวเลือกปกติต้องถูกย้ายเข้ามา (madeToOrder)
 * ยกเว้นช่องกรอกที่ตั้ง standardInput = ข้อมูลประกอบของงานปกติ (เช่น ขนาดไดคัท) ไม่เข้ากล่อง 📐
 */
export function isMadeToOrderOption(o: ProductOption): boolean {
  return (isInputOption(o) && o.standardInput !== true) || o.madeToOrder === true;
}

/** ลูกค้าติ๊ก "สั่งทำ" ไว้ไหม */
export function madeToOrderOn(selections: Record<string, string>): boolean {
  return selections[MTO_LABEL] === MTO_ON;
}

/**
 * กลุ่มนี้ "มีผลจริง" กับลูกค้าตอนนี้ไหม — ต้องทั้งไม่ถูกซ่อนด้วย showWhen
 * และถ้าเป็นกลุ่มงานสั่งทำ ลูกค้าต้องติ๊กสั่งทำไว้ด้วย
 * ไม่เข้าเงื่อนไข = ไม่ถาม ไม่คิดเงิน ไม่ติดไปกับออเดอร์ (เหมือนกลุ่มที่ถูกซ่อน)
 */
export function optionActive(opt: ProductOption, selections: Record<string, string>): boolean {
  if (!optionVisible(opt, selections)) return false;
  return !isMadeToOrderOption(opt) || madeToOrderOn(selections);
}

/**
 * 💬 ตัวเลือกชุดนี้เป็น "งานสั่งทำที่ต้องให้แอดมินตีราคา" ไหม
 *
 * เข้าเงื่อนไขเมื่อกลุ่มที่แสดงอยู่ (ไม่ถูกซ่อนด้วย showWhen) เข้าข้อใดข้อหนึ่ง:
 *  - กลุ่มตั้ง askPrice ไว้ และลูกค้ากรอก/เลือกค่าแล้ว
 *  - ตัวเลือกที่เลือกอยู่ในกลุ่มนั้นตั้ง askPrice ไว้ (เช่น "แบบที่ 3")
 *
 * ผลคือราคา/หน่วย = 0 (หน้าร้านขึ้น "รอแอดมินตีราคา") แต่ลูกค้ายังกดสั่งได้ตามปกติ
 */
export function needsQuote(p: Product, selections: Record<string, string>): boolean {
  for (const opt of p.options) {
    if (!optionActive(opt, selections)) continue;
    const picked = selectedNames(opt, selections);
    // ช่องกรอกที่ตั้ง 💬 ไว้: แค่ "โผล่ให้กรอก" ก็ถือว่าเป็นงานสั่งทำแล้ว
    // (ไม่ต้องรอให้พิมพ์ก่อน ไม่งั้นราคาจะกระพริบจากราคาปกติ → รอตีราคา ตอนลูกค้าเริ่มพิมพ์)
    if (opt.askPrice && (isInputOption(opt) || picked.length)) return true;
    if (opt.choices.some((c) => c.askPrice && picked.includes(c.name))) return true;
  }
  return false;
}

/** สินค้านี้มีทางเลือกที่ต้องให้แอดมินตีราคาไหม (ใช้ตัดสินใจว่าจะโชว์ราคาเป็น "เริ่มต้น ฿X") */
export function hasQuoteOption(p: Product): boolean {
  return (p.options ?? []).some((o) => o.askPrice || o.choices.some((c) => c.askPrice));
}

/** ค่าเพิ่มต่อชิ้นที่มาจากตัวเลือก 1 กลุ่ม — ไว้แจกแจงให้ลูกค้าเห็นว่าราคาต่อชิ้นมาจากไหน */
export interface UnitPriceAddOn {
  /** ชื่อกลุ่มตัวเลือก เช่น "ตะขอ" */
  label: string;
  /** ค่าที่ลูกค้าเลือก เช่น "E ตะขอสปริง 19.2×33mm (เงิน)" */
  choice: string;
  /** บวกเพิ่มกี่บาทต่อชิ้น (ติดลบได้ = ส่วนลดช่วงปลีก) */
  amount: number;
}

/**
 * ราคา/หน่วย แบบแจกแจง — ราคาฐานจากตารางเรท + ค่าตัวเลือกที่บวกเพิ่มทีละกลุ่ม
 * ใช้ตอนอยากอธิบายให้ลูกค้าเห็นว่าทำไมสองบรรทัดในล็อตเดียวกันราคาต่อชิ้นไม่เท่ากัน
 * (เช่น ตะขอสปริง +฿10 ขณะที่ห่วงกลมฟรี — ราคาฐานเรทรวมเท่ากันทั้งคู่)
 */
/**
 * 💰 +฿ ของตัวเลือกในกลุ่ม priceAsDriver — ราคาช่องตารางเรทของตัวเลือกนั้น ณ จำนวน qty
 * (qty ต้องเป็นเลขเดียวกับที่ใช้หาช่วงราคาฐาน — ผ่าน tierQtyFor มาแล้ว)
 * ไม่มีช่องในตาราง/ยังไม่ได้เลือก = 0
 */
export function priceAsDriverExtraOf(
  product: Product,
  opt: ProductOption,
  selections: Record<string, string>,
  choiceName: string,
  qty: number
): number {
  const driver = opt.priceAsDriver;
  if (!driver || !choiceName) return 0;
  const m = activeMatrix(product, selections);
  if (!m || !m.driverLabels.includes(driver)) return 0;
  const view = { ...selections, [driver]: choiceName };
  // แกนอื่นของชิ้นนี้ที่เลือกแยกจากกลุ่ม global (priceAsDriverAlso) — เช่น ประเภท/งานสกรีนรายชิ้น
  for (const [axis, srcGroup] of Object.entries(opt.priceAsDriverAlso ?? {})) {
    if (!m.driverLabels.includes(axis)) continue;
    const v = selections[srcGroup];
    if (v) view[axis] = v;
  }
  const cells = m.cells[priceMatrixKey(m, view)];
  return cells?.length ? (cells[tierIndex(m, qty)] ?? 0) : 0;
}

export function unitPriceParts(
  product: Product,
  selections: Record<string, string>,
  qty: number
): { base: number; addOns: UnitPriceAddOn[]; total: number } {
  const addOns: UnitPriceAddOn[] = [];
  const total = unitPriceFor(product, selections, qty, addOns);
  // ราคาฐาน = ราคาต่อชิ้นหักค่าตัวเลือกออก (ใช้ total เป็นตัวตั้งเพื่อไม่ให้ต่างจากที่คิดเงินจริง)
  const base = total - addOns.reduce((s, a) => s + a.amount, 0);
  return { base, addOns, total };
}

/**
 * ราคา/หน่วย ตามตัวเลือก + จำนวน — ใช้ตารางราคาถ้ามี, ไม่งั้น price + option.extra
 * `collect` (ถ้าส่งมา) จะถูกเติมรายการค่าตัวเลือกที่บวกเพิ่ม — ดู unitPriceParts()
 */
export function unitPriceFor(
  product: Product,
  selections: Record<string, string>,
  qty: number,
  collect?: UnitPriceAddOn[]
): number {
  const note = (label: string, amount: number) => {
    if (!collect || !amount) return;
    const choice = selections[label] ?? "";
    collect.push({ label, choice, amount });
  };
  // 💬 งานสั่งทำที่ต้องให้แอดมินตีราคา — ยังไม่มีราคาจนกว่าแอดมินจะใส่ให้
  if (needsQuote(product, selections)) return 0;
  // งานกำหนดขนาดเอง (custom) มาก่อน — ราคาพิเศษแทนตารางปกติ
  const c = product.custom;
  /**
   * 📐 ค่าเพิ่มของงานกำหนดขนาดเองที่ "ใหญ่กว่าแถวสุดท้ายในตาราง" (โหมด longest)
   * บวกท้ายสุดหลังคิดราคาตารางเสร็จ — ไม่ใช่ราคาแทนตาราง
   */
  let overFee = 0;
  if (c?.enabled) {
    // โหมด "chat" = คุยกับแอดมินก่อน ยังไม่มีราคา · โหมด "size" = ระบุขนาดเฉย ๆ ราคาคิดตามตารางปกติ
    if (c.mode === "chat" && selections[c.label]) return 0;
    const dims = parseCustomDims(selections[c.label]);
    if (dims && c.mode === "longest") {
      // 📐 อิงด้านที่ยาวที่สุด — สลับค่าแกน "ขนาด" เป็นแถวที่ครอบขนาดนั้น แล้วคิดต่อตามตารางปกติ
      // (แกนตารางต้องมีค่าเสมอ ไม่งั้นราคาหล่นไปที่ราคาตั้งต้นของสินค้าเงียบ ๆ)
      const plan = longestSizePlan(product, selections);
      if (plan) {
        selections = { ...selections, [c.sizeLabel!]: plan.choice };
        overFee = plan.overFee;
      }
    } else if (dims && c.mode !== "size") {
      return c.mode === "quote" ? 0 : customUnitPrice(c, dims.w, dims.h);
    }
  }
  // จำนวนที่ใช้ "เทียบช่วงราคา" — สินค้าที่คิดเรทตามชิ้นต่อลายจะเป็น ⌊จำนวน ÷ ลาย⌋
  // เงื่อนไขที่ผูกกับช่วงราคา (ค่าธรรมเนียมช่วงปลีก · extraFromQty) ต้องใช้ตัวเลขเดียวกับที่เลือกช่วงราคา
  // ไม่งั้นจะกลายเป็น "ได้ราคาช่วงปลีก แต่ไม่โดนค่าธรรมเนียมช่วงปลีก" (สั่ง 11 ชิ้น คละ 3 ลาย = ตกลายละ 3)
  const tierQty = tierQtyFor(product, selections, qty);
  const m = activeMatrix(product, selections);
  if (m) {
    // หาช่องราคาไม่เจอเพราะแกนตารางบางกลุ่มไม่มีค่า (ของเก่าในตะกร้าที่ถูกตัดกลุ่มซ่อนออกไป)
    // → เติมค่าเริ่มต้นให้แกนที่ขาด แล้วหาใหม่ ก่อนจะยอมตกไปใช้ราคาตั้งต้นของสินค้า
    const cells =
      m.cells[priceMatrixKey(m, selections)] ??
      (m.driverLabels.some((l) => !selections[l]) ? m.cells[matrixKeyFilled(product, m, selections)] : undefined);
    let base = cells && cells.length ? (cells[tierIndex(m, tierQty)] ?? product.price) : product.price;
    // 📐 คิดตามพื้นที่ลาย — ราคาก้อนแรก + ส่วนเกินคูณเรทต่อหน่วยพื้นที่ (แทนราคาคอลัมน์เดียว)
    // ยังไม่กรอกขนาด = คืน null แล้วใช้ราคาคอลัมน์ตามเดิม (โชว์เป็นราคาเริ่มต้น)
    const areaBd = areaPriceBreakdown(product, selections, qty);
    if (areaBd) base = areaBd.unitPrice;
    // กลุ่มตัวเลือกที่ไม่ใช่แกนตาราง (เช่น อะไหล่พิเศษ) บวกเพิ่มต่อหน่วยตาม extra ของตัวที่เลือก
    // (กลุ่มที่ตั้ง extraFromQty ไว้ ต่ำกว่าเกณฑ์ = ราคารวมแล้ว ไม่บวก)
    for (const opt of product.options) {
      // กลุ่มที่ถูกซ่อน หรือกลุ่มงานสั่งทำที่ลูกค้ายังไม่ได้ติ๊ก = ไม่คิดเงิน
      if (!optionActive(opt, selections)) continue;
      // กลุ่มที่เป็นแกนตาราง ราคาอยู่ในช่องตารางแล้ว — เหลือแค่ค่าธรรมเนียมช่วงปลีกของกลุ่มนั้น
      if (m.driverLabels.includes(opt.label)) {
        const fee = smallQtyFeeOf(opt, selections, tierQty);
        base += fee;
        note(opt.label, fee);
        continue;
      }
      // 💰 กลุ่มราคาดึงจากตารางเรท (priceAsDriver) — เช่น "ขนาดชิ้นที่ 2" บวกราคาช่องขนาดนั้น
      // ของเรทปัจจุบัน ณ ช่วงจำนวนเดียวกับราคาฐาน (สเปคอื่น ๆ ตามที่เลือกอยู่)
      if (opt.priceAsDriver && m.driverLabels.includes(opt.priceAsDriver)) {
        const add = priceAsDriverExtraOf(product, opt, selections, selections[opt.label] ?? "", tierQty);
        base += add;
        note(opt.label, add);
        continue;
      }
      const add = groupAddOf(opt, selections, tierQty);
      base += add;
      note(opt.label, add);
    }
    // 📐 ส่วนที่ใหญ่กว่าแถวสุดท้ายของตาราง (งานกำหนดขนาดเอง) — บวกท้ายสุด
    if (overFee) note(c!.label, overFee);
    // ค่าธรรมเนียมช่วงปลีกใส่ค่าติดลบได้ (ลดให้) — กันหักจนราคาติดลบ
    return Math.max(0, base + overFee);
  }
  let price = product.price;
  for (const opt of product.options) {
    // กลุ่มที่ถูกซ่อน หรือกลุ่มงานสั่งทำที่ลูกค้ายังไม่ได้ติ๊ก = ไม่คิดเงิน
    if (!optionActive(opt, selections)) continue;
    const add = groupAddOf(opt, selections, tierQty);
    price += add;
    note(opt.label, add);
  }
  if (overFee) note(c!.label, overFee);
  return Math.max(0, price + overFee);
}

/**
 * รวมราคาแบบ "ล็อตผลิตเดียวกัน" ในตะกร้า
 *
 * ปัญหา: ลูกค้าสั่งของชิ้นเดียวกันคนละลายเป็นหลายบรรทัด (เช่น พวงกุญแจ 25 ชิ้น 1 ลาย × 2 บรรทัด)
 * แต่ละบรรทัดคิดราคาแยก → ได้เรท 25 ชิ้นทั้งคู่ ทั้งที่จริงเป็นงานผลิตล็อตเดียว 50 ชิ้น 2 ลาย ควรได้เรท 2
 *
 * กติกา (ตามที่ร้านกำหนด):
 * 1. สินค้าเดียวกัน = รวมยอดหาเรท/ขั้นราคา แม้สเปคต่างกัน (ตะขอคนละแบบ · อะคริลิคพิเศษ · ขนาด)
 *    — เรทเลือกจากจำนวนรวม (minQty ≤ จำนวนรวม สูงสุด — กติกาเดียวกับหน้าสินค้า) ทับเรทที่กดไว้
 *    — แต่ "ราคาต่อชิ้นของแต่ละบรรทัด" ยังอ่านจากคอลัมน์สเปคของบรรทัดนั้นเอง (ของแพงยังแพงตามสเปค)
 * 2. ยกเว้นบรรทัดช่วงราคาปลีกคละอิสระ (isFreeMix เช่น 1-10 ชิ้น) = ออเดอร์ปลีก ไม่นับรวมล็อต
 * 3. สินค้า hardMinQty (เรทเป็นคนละหน่วยสั่ง เช่น สติ๊กเกอร์ UV แผ่น A3 / ตร.ม.) — เรทเป็นทางเลือก
 *    เชิงโครงสร้าง ไม่ใช่ขั้นบันไดจำนวน: รวมได้เฉพาะบรรทัดที่อยู่เรทเดียวกัน และไม่สลับเรทให้
 *
 * คืนค่า index ตรงกับ lines ที่ส่งเข้ามา — บรรทัดที่ไม่ได้ถูกรวม (กลุ่มมีบรรทัดเดียว/ของพิเศษ) คงราคาเดิมเป๊ะ
 */
export interface GroupReprice {
  unitPrice: number;
  extraFee: number;
  /** แจกแจงราคาต่อชิ้น: ราคาฐานจากเรท + ค่าตัวเลือกแต่ละกลุ่ม (ไว้อธิบายว่าทำไมแต่ละบรรทัดไม่เท่ากัน) */
  addOns?: UnitPriceAddOn[];
  /** ข้อมูลกลุ่มไว้โชว์ใน UI — undefined = ไม่ได้ถูกรวมกับใคร (คิดแบบบรรทัดเดี่ยวตามเดิม) */
  merged?: { lines: number; totalQty: number; totalDesigns: number; rateLabel?: string };
}

/** เรทที่จำนวน qty เข้าเงื่อนไข minQty สูงสุด (กติกาเดียวกับ ProductDetail) — ไม่มีหลายเรท = undefined */
function pickRateForQty(p: Product, qty: number): PriceRate | undefined {
  const rs = p.priceRates;
  if (!rs?.length) return undefined;
  return [...rs].filter((r) => (r.minQty ?? 1) <= qty).sort((a, b) => (b.minQty ?? 1) - (a.minQty ?? 1))[0] ?? rs[0];
}

/**
 * บรรทัดนี้ยังเป็น "ราคาปลีก" (ยังไม่เข้าเรทขายส่งเรทไหนเลย เช่น 1-10 ชิ้น) ไหม
 * — ใช้ตัดสินว่าตะกร้าเป็นออเดอร์ปลีกล้วน (ของแพงไม่กี่ชิ้น กล่องเดิมใส่พอ ไม่ต้องเด้งค่าส่ง)
 *
 * ⚠️ ปลีก = "จำนวนยังไม่ถึงขั้นต่ำของเรทไหนเลย" ไม่ใช่ "อยู่เรทต่ำสุด" —
 * สินค้าที่มีเรทเดียว (เช่น ผ้าห่ม เรทที่ 1 เริ่ม 11 ชิ้น) สั่ง 14 ชิ้น = ขายส่งแล้ว ต้องเด้งกล่องใหญ่ได้
 * mergedRateLabel = เรทที่ตะกร้ารวมล็อตสรุปให้แล้ว (แม่นกว่าคิดรายบรรทัด — 6+6 รวมเป็น 12 ได้เรทส่ง)
 */
export function isRetailRateLine(
  p: Product,
  selections: Record<string, string>,
  qty: number,
  mergedRateLabel?: string
): boolean {
  const rs = p.priceRates ?? [];
  if (!rs.length) return true; // ไม่มีเรทส่ง = ราคาเดียวตลอด ไม่มีอะไรให้ขยับ
  // ตะกร้าสรุปเรทจาก "ยอดรวมล็อต" มาแล้ว = เข้าเรทส่งแน่ (บรรทัดเดี่ยวอาจยังไม่ถึงขั้นต่ำ แต่รวมกันแล้วถึง)
  if (mergedRateLabel && rs.some((r) => r.label === mergedRateLabel)) return false;
  // สินค้าที่ล็อกให้เลือกเรทเอง (hardMinQty) — ยึดเรทที่ลูกค้าเลือกไว้ เทียบกับขั้นต่ำของเรทนั้น
  const picked = p.hardMinQty ? activeRate(p, selections) : undefined;
  if (picked) return (picked.minQty ?? 1) > qty;
  return !rs.some((r) => (r.minQty ?? 1) <= qty);
}

/**
 * บรรทัดนี้เอามารวมล็อตได้ไหม — เช็คเป็น "รายบรรทัด" ไม่ใช่ทั้งสินค้า
 * (สินค้าที่แค่ "มี" ออปชั่นกำหนดเอง custom.enabled แต่ลูกค้าไม่ได้เลือก ยังต้องรวมได้ —
 * เจอกับพวงกุญแจอะคริลิคที่มีออปชั่น "อุปกรณ์เสริม" mode chat กันทั้งสินค้าแล้วไม่มีวันรวมเลย)
 */
/**
 * แบ่งบรรทัดในล็อตเป็น "กลุ่มเรท" ตามเงื่อนไขที่แต่ละบรรทัดเข้า — ไล่จากเรทสูงสุด (minQty มาก) ลงมา:
 * บรรทัดที่จำนวนถึงโควตาต่อลายของเรทนั้น (qty ≥ minPerDesign × จำนวนลายของบรรทัด) และกลุ่มผู้เข้าเงื่อนไข
 * รวมกันถึงขั้นต่ำของเรท (minQty) = ได้เรทนั้น · ที่เหลือไล่ต่อเรทถัดไป · ไม่เข้าเรทไหนเลย = คงราคาเดี่ยว
 *
 * ตัวอย่างกติการ้าน (เรท 1 = 11 ชิ้นขึ้น ลายละ 5 · เรท 2 = 50 ชิ้นขึ้น ลายละ 25):
 * สั่ง 25+25+10+5 → {25,25} รวม 50 เข้าเรท 2 · {10,5} เข้าเรท 1 — ไม่ใช่เหมารวมก้อนเดียวแล้วตกเรท 1 หมด
 *
 * คืน array ยาวเท่า entries: เรทของแต่ละบรรทัด (undefined = ไม่เข้าเรทไหน)
 */
function ratePoolsFor(p: Product, entries: { qty: number; designs: number }[]): (PriceRate | undefined)[] {
  const out: (PriceRate | undefined)[] = entries.map(() => undefined);
  const rs = p.priceRates ?? [];
  if (!rs.length) return out;
  const taken = entries.map(() => false);
  for (const r of [...rs].sort((a, b) => (b.minQty ?? 1) - (a.minQty ?? 1))) {
    const per = r.minPerDesign ?? 0;
    const cand = entries
      .map((_, i) => i)
      // เรทที่ตั้ง underMinPieceFee — บรรทัดที่คละไม่ถึงโควตาต่อลายก็เข้าเรทได้ (จ่ายส่วนต่างชิ้นละ N แทน)
      .filter(
        (i) =>
          !taken[i] && (per <= 0 || !!r.underMinPieceFee || entries[i].qty >= per * Math.max(1, entries[i].designs))
      );
    const candQty = cand.reduce((s, i) => s + entries[i].qty, 0);
    if (!cand.length || candQty < (r.minQty ?? 1)) continue;
    for (const i of cand) {
      out[i] = r;
      taken[i] = true;
    }
  }
  return out;
}

/**
 * บรรทัดนี้ "ใช้สิทธิ์คละอิสระช่วงปลีก" จริงไหม — จำนวนอยู่ช่วงปลีก และจำนวนลายเกินโควตา
 * minPerDesign ที่จำนวนนั้น (เช่น 8 ชิ้น 5 ลาย ที่กติกาลายละ 5)
 * สั่งน้อยแต่เข้าเกณฑ์ต่อลายอยู่แล้ว (เช่น 5 ชิ้น 1 ลาย = ลายละ 5 พอดี) = ล็อตผลิตปกติ รวมล็อตได้
 * — เดิมตัดทุกบรรทัดช่วงปลีกแบบเหมารวม ทำให้ 25+5 ไม่รวมเป็น 30 ทั้งที่ควรได้เรทส่ง
 */
function usesFreeMixRetail(r: PriceRate | undefined, qty: number, designs: number): boolean {
  if (!r || !isFreeMix(r, qty)) return false;
  // เรทที่คิดค่าคละไม่ถึงขั้นต่ำเป็นเงิน (underMinPieceFee) — รวมล็อตได้เสมอ
  // (เข้าเรทส่งแล้วชิ้นที่ไม่ถึงลายละ 3 จ่ายส่วนต่างเอง ไม่ต้องกันออกไปจ่ายราคาปลีก)
  if (r.underMinPieceFee) return false;
  const per = r.minPerDesign ?? 0;
  return per > 0 && designs > Math.floor(qty / per);
}

function lineMergeable(p: Product, selections: Record<string, string>, qty: number): boolean {
  if (p.areaPricing?.enabled) return false;
  // ใช้ออปชั่นกำหนดเอง/ตีราคาจริงในบรรทัดนี้ (เลือกค่าไว้) = ราคาไม่อิงเรทตามจำนวน ไม่รวม
  // ยกเว้นโหมดที่ราคายังมาจากตารางเรทตามจำนวน (size = ระบุขนาดเฉย ๆ · longest = อิงด้านยาวสุด)
  // — บรรทัดพวกนี้เป็นงานล็อตเดียวกับบรรทัดปกติจริง ๆ ต้องรวมยอดหาเรทด้วย
  const customPriced = p.custom?.mode === "size" || p.custom?.mode === "longest";
  if (p.custom?.enabled && !customPriced && (selections[p.custom.label] ?? "").trim()) return false;
  if (needsQuote(p, selections)) return false;
  // ออเดอร์ปลีกคละอิสระ (ลายเกินโควตาต่อลายในช่วงปลีก) = จ่ายราคาปลีกตามเดิม ไม่นับรวมล็อตผลิต
  const r = p.hardMinQty ? activeRate(p, selections) : pickRateForQty(p, qty);
  if (usesFreeMixRetail(r, qty, designCountOf(selections))) return false;
  return true;
}

/**
 * คีย์จัดกลุ่ม — สินค้าเรทตามจำนวน: รวมกันทั้งสินค้า (สเปคต่างกันได้ ราคาแยกตามคอลัมน์ของใครของมัน)
 * สินค้า hardMinQty: แยกกลุ่มตามเรทที่เลือก เพราะเรทคนละหน่วยสั่ง เอายอดข้ามเรทมาบวกกันไม่ได้
 * lotKeyOptions: แยกกลุ่มตามค่าของกลุ่มที่ระบุด้วย (เช่น เนื้อสติ๊กเกอร์ = คนละรอบผลิต)
 * ⚠️ ห้ามเอาของแนบต่อบรรทัด (ภาพลาย/ลิงก์/หมายเหตุ) มาเป็นคีย์ — ต่างกันทุกบรรทัด จะไม่มีวันรวม
 */
function groupKeyOf(p: Product, selections: Record<string, string>): string {
  const base = p.hardMinQty ? `${p.id}|${activeRate(p, selections)?.label ?? ""}` : p.id;
  const split = p.lotKeyOptions?.length
    ? p.lotKeyOptions.map((l) => `${l}=${selections[l] ?? ""}`).join("|")
    : "";
  return split ? `${base}|${split}` : base;
}

/** ป้ายบอกว่าล็อตนี้คือกลุ่มไหน (ค่าของ lotKeyOptions) เช่น "เนื้อพลาสติกใส-แผ่นรองขุ่น" */
function lotGroupLabel(p: Product, selections: Record<string, string>): string {
  return (p.lotKeyOptions ?? [])
    .map((l) => selections[l]?.trim())
    .filter(Boolean)
    .join(" · ");
}

/**
 * เติมค่า "กลุ่มควบคุม" (showWhen/showWhenAlso/showWhenAll) ที่หายไป ให้ของเก่าในตะกร้า
 * บรรทัดเก่าอาจเกิดก่อนร้านเพิ่มกลุ่มใหม่ (เช่น "รับตะขอไหม") — selections จึงไม่มีค่ากลุ่มนั้น
 * ทำให้กลุ่มลูก (เช่น "สีตะขอ · โลหะ" ที่ตั้ง showWhenAlso: รับตะขอ) ถูกมองว่าซ่อน
 * → ค่าตะขอ +฿8 ไม่ถูกคิดเงินและไม่โชว์ป้าย ทั้งที่ลูกค้าเลือกตะขอไว้ชัด ๆ
 *
 * กติกา: กลุ่มไหน "มีค่าที่ลูกค้าเลือกไว้" = กลุ่มนั้นเคยแสดงจริงตอนสั่ง → เงื่อนไขที่อ้างถึง
 * กลุ่มที่ไม่มีค่า ให้เติมเป็นตัวเลือกแรกของเงื่อนไข (ค่าที่ทำให้แสดง)
 * ⚠️ กลุ่มควบคุมที่มีค่าอยู่แล้ว "ไม่แตะ" — ค่าไม่ตรงเงื่อนไข = ลูกค้าตั้งใจเปลี่ยน ต้องซ่อนตามจริง
 */
function backfillShowWhen(p: Product, selections: Record<string, string>): Record<string, string> {
  let out = selections;
  for (const opt of p.options ?? []) {
    if (!selections[opt.label]) continue; // กลุ่มนี้ไม่มีค่า — ไม่มีหลักฐานว่าเคยแสดง
    for (const cond of [opt.showWhen, opt.showWhenAlso, ...(opt.showWhenAll ?? [])]) {
      if (!cond?.label || !cond.choices?.length) continue;
      if (out[cond.label] !== undefined) continue;
      if (out === selections) out = { ...selections };
      out[cond.label] = cond.choices[0];
    }
  }
  return out;
}

/**
 * 🩹 ซ่อมบรรทัดที่ "เรทราคาขัดกับสเปคของตัวเอง"
 *
 * เจอจริง 31 ส.ค. 69: บรรทัดในตะกร้ามี `ขนาดตัด: A7` + `จำนวนจุดไดคัท: 12` (สองกลุ่มนี้ตั้ง
 * showWhenAlso ให้โผล่เฉพาะเรท "ขายแบบ ขนาด A3") แต่ `เรทราคา` กลับเป็น "ขายแบบ ขนาด ตารางเมตร"
 * → ราคาถูกคิดที่ตาราง ตร.ม. (฿950/หน่วย) ทั้งที่ลูกค้าสั่งเป็นแผ่น A3 (฿130)
 * ต้นเหตุคือบั๊กเก่าที่เรทเด้งเองตอนจำนวนเป็น 1 — แก้ที่หน้าสินค้าแล้ว แต่บรรทัดที่ค้าง
 * อยู่ในตะกร้าลูกค้าฝังเรทผิดไว้ถาวร คิดราคาเพี้ยนไปเรื่อย ๆ เงียบ ๆ
 *
 * กติกา: กลุ่มไหน "มีค่าที่ลูกค้าเลือกไว้" แปลว่ากลุ่มนั้นเคยแสดงจริงตอนสั่ง → เงื่อนไขที่อ้าง
 * ถึงกลุ่มเรทจึงเป็นหลักฐานว่าตอนนั้นอยู่เรทไหน · เชื่อสเปคมากกว่าค่าเรทที่ฝังไว้
 * ⚠️ ซ่อมเฉพาะตอนที่ "กลุ่มที่ยังมีค่าอยู่ชี้ไปเรทเดียวกันหมด" — ชี้กันคนละทางถือว่าไม่รู้ ไม่แตะ
 */
export function repairRateFromOptions(p: Product, selections: Record<string, string>): Record<string, string> {
  const rates = p.priceRates ?? [];
  const cur = selections[RATE_LABEL];
  if (rates.length < 2 || !cur) return selections;
  const wanted = new Set<string>();
  for (const opt of p.options ?? []) {
    if (!(selections[opt.label] ?? "").trim()) continue; // ไม่มีค่า = ไม่ใช่หลักฐาน
    for (const cond of [opt.showWhen, opt.showWhenAlso, ...(opt.showWhenAll ?? [])]) {
      if (cond?.label !== RATE_LABEL || !cond.choices?.length) continue;
      for (const c of cond.choices) wanted.add(c);
    }
  }
  // ชี้ไปเรทเดียวกันหมด และไม่ตรงกับที่ฝังไว้ → เชื่อสเปค
  if (wanted.size !== 1) return selections;
  const only = [...wanted][0];
  if (only === cur || !rates.some((r) => r.label === only)) return selections;
  return { ...selections, [RATE_LABEL]: only };
}

export function repriceCartGroups(
  rawLines: { productId: string; selections: Record<string, string>; qty: number }[],
  productOf: (id: string) => Product | undefined
): GroupReprice[] {
  // เติมค่ากลุ่มควบคุมที่หายไปก่อนคิดราคา (ของเก่าในตะกร้าที่เกิดก่อนร้านเพิ่มกลุ่มใหม่)
  const lines = rawLines.map((l) => {
    const p = productOf(l.productId);
    return p ? { ...l, selections: repairRateFromOptions(p, backfillShowWhen(p, l.selections)) } : l;
  });

  // ตั้งต้น: คิดแบบบรรทัดเดี่ยวตามเดิม แล้วค่อยทับเฉพาะกลุ่มที่รวมได้
  const out: GroupReprice[] = lines.map((l) => {
    const p = productOf(l.productId);
    const parts = p ? unitPriceParts(p, l.selections, l.qty) : undefined;
    return {
      unitPrice: parts?.total ?? 0,
      extraFee: p ? designFeeFor(p, l.selections, l.qty) : 0,
      addOns: parts?.addOns,
    };
  });

  const groups = new Map<string, number[]>();
  lines.forEach((l, idx) => {
    const p = productOf(l.productId);
    if (!p || !lineMergeable(p, l.selections, l.qty)) return;
    const key = groupKeyOf(p, l.selections);
    const arr = groups.get(key);
    if (arr) arr.push(idx);
    else groups.set(key, [idx]);
  });

  for (const idxs of groups.values()) {
    if (idxs.length < 2) continue; // บรรทัดเดี่ยว = ตรงกับราคาตั้งต้น ไม่ต้องทำอะไร
    const p = productOf(lines[idxs[0]].productId);
    if (!p) continue;
    // ขั้นราคา (tier) คิดที่ "ยอดรวมทั้งล็อต" เสมอ — ผลิตพร้อมกันทั้งหมด นับรวมกันทุกบรรทัด
    const lotQty = idxs.reduce((s, i) => s + lines[i].qty, 0);

    // แบ่งบรรทัดเป็นกลุ่มเรทตามเงื่อนไขที่แต่ละบรรทัดเข้า (25+25+10+5 → {25,25}=เรท 2 · {10,5}=เรท 1)
    // hardMinQty = เรทเป็นทางเลือกเชิงโครงสร้าง (กลุ่มนี้อยู่เรทเดียวกันอยู่แล้ว) — คงเรทเดิม กลุ่มเดียว
    let pools: { rate?: PriceRate; idxs: number[] }[];
    if (p.hardMinQty || !p.priceRates?.length) {
      pools = [{ rate: p.hardMinQty ? activeRate(p, lines[idxs[0]].selections) : undefined, idxs: [...idxs] }];
    } else {
      const assigned = ratePoolsFor(
        p,
        idxs.map((i) => ({ qty: lines[i].qty, designs: designCountOf(lines[i].selections) }))
      );
      const byLabel = new Map<string, { rate: PriceRate; idxs: number[] }>();
      idxs.forEach((idx, n) => {
        const r = assigned[n];
        if (!r) return; // ไม่เข้าเรทไหน → คงราคาเดี่ยวตามตั้งต้น
        const cur = byLabel.get(r.label);
        if (cur) cur.idxs.push(idx);
        else byLabel.set(r.label, { rate: r, idxs: [idx] });
      });
      pools = [...byLabel.values()];
    }

    for (const pool of pools) {
      const poolDesigns = pool.idxs.reduce((s, i) => s + designCountOf(lines[i].selections), 0);
      /**
       * ค่าคละลายในล็อตที่มี "กติกาคละ" ปนกัน — เช่น สติ๊กเกอร์แผ่นไดคัท 50% (ตั้ง mixRule ของตัวเอง
       * ลายละ 20 ต่อแผ่น) กับแผ่นไดคัท 100% (ใช้กติการะดับสินค้า ลายละ 5) อยู่ล็อตเดียวกัน
       *
       * เดิมคิดครั้งเดียวจาก selections ของ "บรรทัดแรก" ที่ยอดรวมทั้งล็อต → ได้กติกาของบรรทัดแรก
       * ไปคิดกับจำนวนแผ่นของทั้งล็อต ราคาจึงเปลี่ยนตามลำดับที่ลูกค้าหยิบใส่ตะกร้า
       * ตอนนี้แยกคิดตามกลุ่มกติกา: แต่ละกลุ่มใช้จำนวน+จำนวนลายของกลุ่มตัวเอง เกาะบรรทัดแรกของกลุ่ม
       * (กติกาเดียวทั้งล็อต = ไม่แตะ คิดแบบเดิมเป๊ะ)
       */
      const mixGroups = new Map<string, { idxs: number[]; qty: number; designs: number }>();
      for (const i of pool.idxs) {
        const mk = JSON.stringify(mixRuleFor(p, lines[i].selections) ?? null);
        const g = mixGroups.get(mk) ?? { idxs: [], qty: 0, designs: 0 };
        g.idxs.push(i);
        g.qty += lines[i].qty;
        g.designs += designCountOf(lines[i].selections);
        mixGroups.set(mk, g);
      }
      const splitMix = mixGroups.size > 1;
      const mixFeeAt = new Map<number, number>();
      if (splitMix) {
        for (const g of mixGroups.values()) {
          const head = g.idxs[0];
          const gsel: Record<string, string> = {
            ...lines[head].selections,
            [DESIGN_LABEL]: String(g.designs),
          };
          if (pool.rate) gsel[RATE_LABEL] = pool.rate.label;
          mixFeeAt.set(head, designFeeBase(p, gsel, g.qty));
        }
      }
      pool.idxs.forEach((i, k) => {
        const own = lines[i].selections;
        const sel: Record<string, string> = { ...own, [DESIGN_LABEL]: String(poolDesigns) };
        if (pool.rate) {
          // สเปคของบรรทัดนี้มีราคาขายในเรทนั้นไหม — แถวที่แอดมินล้างราคา (ไม่ขายในเรทนั้น) ห้ามสลับเรทให้
          // ไม่งั้นคีย์หาช่องไม่เจอ ราคาหล่นไป product.price เงียบ ๆ · แกนที่ไม่มีค่าปล่อยให้ matrixKeyFilled เติม
          const m = pool.rate.pricing;
          const cellOk = !!m.cells[priceMatrixKey(m, sel)] || m.driverLabels.some((l) => !sel[l]);
          if (cellOk) sel[RATE_LABEL] = pool.rate.label;
        }
        const parts = unitPriceParts(p, sel, lotQty);
        out[i] = {
          unitPrice: parts.total,
          addOns: parts.addOns,
          // ค่าประจำบรรทัด (ต่อลาย/ต่อแผ่น) คิดตามสเปค+จำนวนลายของบรรทัดตัวเอง (สเปคในกลุ่มต่างกันได้)
          // ส่วน "ค่าคละลาย" เป็นของกลุ่มเรท — เกาะบรรทัดแรกของกลุ่มบรรทัดเดียว กันนับซ้ำ
          // ยกเว้นเรท underMinPieceFee: คิด "รายบรรทัด" จากชิ้น/ลายของบรรทัดตัวเอง (แม่นกว่ารวมทั้งล็อต —
          // ลายของแต่ละบรรทัดแยกกันจริง เอาชิ้นข้ามบรรทัดมาเติมลายกันไม่ได้) · เช็คช่วงปลีกที่ยอดรวมล็อต
          extraFee:
            perDesignExtraOf(p, own) +
            sheetFeeTotalOf(p, own, lines[i].qty) +
            (pool.rate?.underMinPieceFee
              ? underMinFeeFor(pool.rate, lines[i].qty, designCountOf(own), lotQty)
              : splitMix
                ? (mixFeeAt.get(i) ?? 0)
                : k === 0
                  ? designFeeBase(p, sel, lotQty)
                  : 0),
          merged: { lines: idxs.length, totalQty: lotQty, totalDesigns: poolDesigns, rateLabel: sel[RATE_LABEL] },
        };
      });
    }
  }
  return out;
}

/** ล็อตที่ยังไม่ถึงยอดสั่งขั้นต่ำ (เรทที่ตั้ง minQtyScope: "lot") */
export interface LotShortfall {
  /** คีย์ล็อต (groupKeyOf) — ใช้แยกแถวเตือน/จับคู่กับบรรทัดในตะกร้า */
  key: string;
  productId: string;
  productName: string;
  rateLabel: string;
  /** ค่าของกลุ่มที่แยกล็อต เช่น "เนื้อขาว (เงา/ด้าน)-แผ่นรองกระดาษขาว" (ว่าง = สินค้าไม่ได้ตั้ง lotKeyOptions) */
  groupLabel: string;
  /** หน่วยขายของเรทนั้น เช่น "แผ่น A3" */
  unit: string;
  /** ขั้นต่ำของเรท */
  need: number;
  /** มีแล้วในล็อตนี้ */
  have: number;
  /** ยังขาดอีกเท่าไหร่ (need − have) */
  short: number;
}

/**
 * ล็อตไหนในตะกร้ายังไม่ถึงยอดสั่งขั้นต่ำบ้าง — ประตูขั้นต่ำของเรทที่ตั้ง `minQtyScope: "lot"`
 *
 * ขั้นต่ำแบบนี้เป็นของ "รอบผลิต" ไม่ใช่ของบรรทัดใดบรรทัดหนึ่ง — สติ๊กเกอร์ UV ขั้นต่ำ 3 แผ่น A3
 * ต่อเนื้อ 1 ชนิด แต่ 3 แผ่นนั้นคละไดคัท 50%/100% และคละขนาดกันได้ (= คนละบรรทัด บรรทัดละ 1 แผ่น)
 * หน้าสินค้าจึงปล่อยให้กดเพิ่มทีละแผ่น แล้วมาเช็คยอดรวมตอนจะสั่งจริงแทน
 *
 * บรรทัดที่ไม่เข้าล็อต (งานตีราคา/กำหนดขนาดเอง/คิดตามพื้นที่) ไม่นับและไม่ถูกบล็อก
 * ใช้ที่ตะกร้า · หน้าชำระเงิน · และ /api/orders (ฝั่งเซิร์ฟเวอร์ ห้ามเชื่อ client อย่างเดียว)
 */
export function lotShortfalls(
  rawLines: { productId: string; selections: Record<string, string>; qty: number }[],
  productOf: (id: string) => Product | undefined
): LotShortfall[] {
  const groups = new Map<string, LotShortfall>();
  for (const l of rawLines) {
    const p = productOf(l.productId);
    if (!p) continue;
    const sel = backfillShowWhen(p, l.selections);
    if (!lineMergeable(p, sel, l.qty)) continue;
    const rate = p.hardMinQty ? activeRate(p, sel) : pickRateForQty(p, l.qty);
    if (rate?.minQtyScope !== "lot" || !rate.minQty || rate.minQty <= 1) continue;
    const key = groupKeyOf(p, sel);
    const cur = groups.get(key);
    if (cur) {
      cur.have += l.qty;
      continue;
    }
    groups.set(key, {
      key,
      productId: p.id,
      productName: p.name,
      rateLabel: rate.label,
      groupLabel: lotGroupLabel(p, sel),
      unit: rate.pricing.unit || "ชิ้น",
      need: rate.minQty,
      have: l.qty,
      short: 0,
    });
  }
  return [...groups.values()]
    .map((g) => ({ ...g, short: Math.max(0, g.need - g.have) }))
    .filter((g) => g.short > 0);
}

/**
 * พรีวิว "รวมล็อตกับของที่อยู่ในตะกร้าแล้ว" — ใช้ที่หน้าสินค้า ให้ลูกค้าเห็นก่อนกดเพิ่มลงตะกร้า
 * ว่าจำนวนที่กำลังเลือกจะถูกคิดรวมกับบรรทัดในตะกร้าเป็นยอดเดียว (กติกาชุดเดียวกับ repriceCartGroups)
 * คืน undefined เมื่อไม่มีอะไรให้รวม (ตะกร้าไม่มีสินค้านี้ / บรรทัดนี้เป็นงานตีราคา / ช่วงปลีกคละอิสระ)
 */
export interface LotPreview {
  /** จำนวนที่อยู่ในตะกร้าแล้ว (นับเฉพาะบรรทัดที่รวมล็อตได้) */
  cartQty: number;
  /** กี่บรรทัดในตะกร้า */
  cartLines: number;
  /** ยอดรวมล็อตที่ใช้คิดพรีวิว (retailLine = คิดที่ mergeFromQty แทนจำนวนที่เลือกอยู่) */
  combinedQty: number;
  totalDesigns: number;
  rateLabel?: string;
  /** ราคา/ชิ้นของสเปคที่เลือกอยู่ เมื่อคิดที่ยอดรวมล็อต */
  unitPrice: number;
  /** จำนวนที่เลือกอยู่อยู่ช่วงราคาปลีกคละอิสระ (เช่น 1-10 ชิ้น) — บรรทัดนี้ยังไม่ถูกรวมล็อต */
  retailLine?: boolean;
  /** ต้องสั่งอย่างน้อยกี่ชิ้นบรรทัดนี้ถึงเริ่มรวมล็อต (มีเมื่อ retailLine) */
  mergeFromQty?: number;
}

export function lotPreviewFor(
  product: Product,
  cartLines: { productId: string; selections: Record<string, string>; qty: number }[],
  selections: Record<string, string>,
  qty: number,
  designs = 1
): LotPreview | undefined {
  if (qty < 1) return undefined;
  // งานตีราคา/กำหนดเอง/คิดตามพื้นที่ = ไม่รวมล็อตเสมอ — ไม่มีอะไรให้บอก
  if (product.areaPricing?.enabled) return undefined;
  if (product.custom?.enabled && (selections[product.custom.label] ?? "").trim()) return undefined;
  if (needsQuote(product, selections)) return undefined;

  const key = groupKeyOf(product, selections);
  const match = cartLines.filter(
    (l) =>
      l.productId === product.id &&
      lineMergeable(product, l.selections, l.qty) &&
      groupKeyOf(product, l.selections) === key
  );
  const cartQty = match.reduce((s, l) => s + l.qty, 0);
  if (cartQty <= 0) return undefined;
  const cartDesigns = match.reduce((s, l) => s + designCountOf(l.selections), 0);

  // บรรทัดที่ "ใช้สิทธิ์คละอิสระช่วงปลีก" (ลายเกินโควตาต่อลาย) → คิดราคาปลีกแยก แต่บอกเกณฑ์เริ่มรวมให้รู้
  // พรีวิวราคาคิดที่ "สั่งขั้นต่ำที่เริ่มรวมได้" = จำนวนถึงโควตาลาย (ลาย × ลายละ) แทนจำนวนที่เลือกอยู่
  const myDesigns = Math.max(1, designs);
  const rNow = product.hardMinQty ? activeRate(product, selections) : pickRateForQty(product, qty);
  const retailLine = usesFreeMixRetail(rNow, qty, myDesigns);
  const mergeFromQty = retailLine ? (rNow!.minPerDesign ?? 1) * myDesigns : undefined;
  const lineQty = retailLine ? mergeFromQty! : qty;

  // ขั้นราคาคิดที่ยอดรวมทั้งล็อต · เรทของบรรทัดนี้มาจากการแบ่งกลุ่มเรทชุดเดียวกับตะกร้า
  // (25 ในตะกร้า + เลือก 25 อยู่ → เรท 2 · แต่เลือก 10 อยู่ → บรรทัดนี้เข้าเรท 1 แม้ล็อตรวม 35)
  const combinedQty = cartQty + lineQty;
  const entries = [
    ...match.map((l) => ({ qty: l.qty, designs: designCountOf(l.selections) })),
    { qty: lineQty, designs: myDesigns },
  ];
  const assigned = product.hardMinQty ? undefined : ratePoolsFor(product, entries);
  const rate = product.hardMinQty ? activeRate(product, selections) : assigned![entries.length - 1];
  // มีหลายเรทแต่บรรทัดนี้ไม่เข้าเรทไหนเลย (เช่น ลายเยอะเกินโควตาทุกเรท) = ไม่มีอะไรให้รวม
  if (!rate && (product.priceRates?.length ?? 0) > 0) return undefined;
  // จำนวนลายนับเฉพาะกลุ่มเรทเดียวกัน (กลุ่มอื่นคนละเงื่อนไข ไม่เกี่ยวกับโควตาลายของบรรทัดนี้)
  const totalDesigns = assigned
    ? entries.reduce((s, e, i) => (assigned[i]?.label === rate?.label ? s + e.designs : s), 0)
    : cartDesigns + myDesigns;
  const sel: Record<string, string> = { ...selections, [DESIGN_LABEL]: String(totalDesigns) };
  if (rate) {
    const m = rate.pricing;
    const cellOk = !!m.cells[priceMatrixKey(m, sel)] || m.driverLabels.some((l) => !sel[l]);
    if (cellOk) sel[RATE_LABEL] = rate.label;
  }
  return {
    cartQty,
    cartLines: match.length,
    combinedQty,
    totalDesigns,
    rateLabel: sel[RATE_LABEL],
    unitPrice: unitPriceFor(product, sel, combinedQty),
    ...(retailLine ? { retailLine, mergeFromQty } : {}),
  };
}

/** ข้อความราคา: แสดงเป็นช่วง "฿ต่ำสุด – ฿สูงสุด" ถ้าตัวเลือกทำให้ราคาต่างกัน */
export function formatPriceRange(p: Product): string {
  const { min, max } = priceRange(p);
  return max > min ? `${formatPrice(min)} – ${formatPrice(max)}` : formatPrice(min);
}

/**
 * สินค้านี้มีแบบ "งานสั่งทำ ให้แอดมินตีราคา" อยู่ด้วยไหม
 * อ่านจากธงที่เซิร์ฟเวอร์เขียนไว้ก่อน (ข้อมูลแบบเบาของการ์ดไม่มี options) ไม่มีธงค่อยดูจาก options จริง
 */
export function isQuoteProduct(p: Product): boolean {
  return p.quoteOption === true || hasQuoteOption(p);
}

/**
 * ราคาที่โชว์บน "การ์ด/รายการสินค้า"
 * สินค้าที่มีแบบสั่งทำ ราคาสูงสุดไม่มีความหมาย (แล้วแต่งานที่ลูกค้าสั่ง) → บอกเป็น "เริ่มต้น ฿X"
 * หน้าสินค้ายังใช้ formatPriceRange ตามเดิม เพราะตรงนั้นรู้ว่าลูกค้าเลือกแบบไหนอยู่
 */
export function formatPriceLabel(p: Product): string {
  const { min } = priceRange(p);
  return isQuoteProduct(p) ? `เริ่มต้น ${formatPrice(min)}` : formatPriceRange(p);
}

/**
 * ตัวเลือกที่อนุญาตของกลุ่ม `label` ภายใต้สิ่งที่เลือกอยู่ตอนนี้
 * (ตัดตามกฎทุกข้อที่เงื่อนไข `when` ตรง — ถ้ากฎตัดจนหมดจะคืนทั้งกลุ่มไว้กันหน้าพัง)
 */
export function allowedChoices(
  product: Product,
  selections: Record<string, string>,
  label: string
): string[] {
  const group = product.options.find((o) => o.label === label);
  if (!group) return [];
  let allowed = group.choices.map((c) => c.name);
  for (const rule of product.rules ?? []) {
    if (rule.limit.label !== label) continue;
    // กลุ่มต้นทางของกฎถูกซ่อนอยู่ (showWhen ไม่ตรง) = ลูกค้าไม่ได้เลือกค่านั้นจริง
    // ค่าที่ค้างเป็นแค่ default/ของเก่า — ห้ามเอามาตัดตัวเลือกของกลุ่มที่มองเห็น
    // (เช่น กลุ่มเฉดสีพิเศษที่โชว์เฉพาะตอนเลือก "สีพิเศษ" ต้องไม่จำกัดงานสกรีนตอนลูกค้าเลือก "ใส")
    const whenGroup = product.options.find((o) => o.label === rule.when.label);
    if (whenGroup && !optionVisible(whenGroup, selections)) continue;
    if (ruleWhenMatches(rule, selections)) {
      allowed = allowed.filter((n) => rule.limit.allow.includes(n));
    }
  }
  return allowed.length > 0 ? allowed : group.choices.map((c) => c.name);
}

/**
 * ปรับสิ่งที่ลูกค้าเลือกให้ถูกกฎเสมอ: ไล่ตามลำดับกลุ่ม
 * ถ้าค่าที่เลือกไว้ใช้ไม่ได้แล้ว (เพราะกลุ่มก่อนหน้าเปลี่ยน) จะสลับเป็นตัวแรกที่อนุญาต
 */
export function resolveSelections(
  product: Product,
  selections: Record<string, string>
): Record<string, string> {
  const resolved: Record<string, string> = {};
  for (const opt of product.options) {
    const view = { ...selections, ...resolved };
    const allowed = allowedChoices(product, view, opt.label);
    const current = selections[opt.label];
    // ช่องกรอก: ค่ามาจากลูกค้า ไม่มีรายการให้เทียบ/ไม่มีค่าเริ่มต้น — คงไว้ตามที่พิมพ์
    if (isInputOption(opt)) {
      resolved[opt.label] = current ?? "";
      continue;
    }
    if (isMultiOption(opt)) {
      // ติ๊กได้หลายอย่าง: เก็บเฉพาะตัวที่ยังอนุญาต · ไม่เหลือเลยก็ได้ (กลุ่มนี้ไม่บังคับเลือก)
      // ติ๊กได้หลายอย่าง: เก็บจำนวนที่ลูกค้าระบุไว้ด้วย (เช่น "เพิ่มสาย ×2")
      const names = opt.choices.map((c) => c.name);
      resolved[opt.label] = joinMultiPicks(
        splitMultiPicks(current, names).filter((p) => allowed.includes(p.name))
      );
      continue;
    }
    // ตัวที่ไม่มีราคาในตารางเรทนี้ หน้าร้านซ่อนไว้ (แถวราคาว่าง = ไม่ขายคู่นี้)
    // ค่าเริ่มต้นจึงต้องไม่ไปตกที่ตัวที่ถูกซ่อน ไม่งั้นหัวข้อจะโชว์ชื่อที่ลูกค้าเลือกซ้ำในเมนูไม่ได้
    // แถมราคาหล่นไปใช้ราคาตั้งต้นแทนราคาในตาราง · ไม่เหลือตัวที่มีราคาเลยค่อยคงชุดเดิมไว้กันหน้าพัง
    const m = activeMatrix(product, view);
    const priced = m ? allowed.filter((n) => matrixChoiceAvailable(m, opt.label, n)) : allowed;
    const pool = priced.length > 0 ? priced : allowed;
    resolved[opt.label] = current && pool.includes(current) ? current : pool[0];
  }
  return resolved;
}

/* ยอดส่งฟรีไม่เก็บไว้ตรงนี้แล้ว — แหล่งจริงคือค่าที่แอดมินตั้งที่ /admin/settings
   อ่านผ่าน freeShippingMinOf() ใน lib/shop-settings.ts */
